[2458]={"臥底密探",{"到淤泥沼澤北邊的風險投資公司塔樓去，聯系碎手氏族的臥底費蘇勒。","","看到塔樓之後，用信號槍發射信號，向工頭費蘇勒示意妳已經到達。發出兩個閃光信號，然後使用碎手軍禮和工頭費蘇勒接頭。","","註意，這些步驟必須依次進行，因為費蘇勒會攻擊並幹掉任何他無法識別的人。"}},
[2459]={"噬夢者菲羅斯塔",{"多蘭納爾的塔隆凱·捷根要妳殺掉7個瘤背秘法師，並找到遺失的珠寶。"}},
[2460]={"碎手軍禮",{"對著申蘇爾練習碎手軍禮。"}},
[2478]={"基本不可能的任務",{"從工頭希裏克斯那裏偷出希裏克斯的塔樓鑰匙，進入塔樓，然後殺掉兩個變異風險投資公司工人、兩個風險投資公司巡邏員、兩個風險投資公司看守。","","殺掉大工頭普茲克·加裏維克斯，取了他的首級，然後打開加裏維克斯的箱子，拿走贊吉爾的改良藥劑。將藥劑和加裏維克斯的頭顱交給奧格瑞瑪的申蘇爾，等候進壹步的指示。"}},
[2479]={"希諾特的幫助",{"到希爾斯布萊德丘陵的塔倫米爾去，把贊吉爾的藥劑樣品交給瑟爾格·希諾特。","","要去塔倫米爾，可以搭乘飛艇到幽暗城，然後沿著大路向南穿過銀松森林，直到希爾斯布萊德丘陵。跟著路標走！"}},
[2480]={"希諾特的幫助",{"等待瑟爾格·希諾特完成解藥。"}},
