[2521]={"為庫米沙效力",{"在妳探索詛咒之地的旅程中，如果碰巧發現了無暇的德萊尼水晶球，就把它交給收藏家庫米沙。","","妳要知道，這種寶石是整個艾澤拉斯最珍稀的水晶。詛咒之地上的任何壹種生物都有可能帶著壹顆無暇的德萊尼水晶球。","","每找到壹顆，妳都會得到相應的酬勞。"}},
