[3374]={"伊蘭尼庫斯精華",{"把伊瑟拉巨龍軍團的誓言石和被禁錮的伊蘭尼庫斯精華交給悲傷沼澤的伊薩裏奧斯。在那裏妳可以決定是否要幫助伊瑟拉的綠龍軍團。"}},
[3375]={"占蔔之瓶",{"把壹瓶法力藥水、壹塊煤和壹瓶蜂蜜酒送到鐵爐堡的塔瓦斯德·基瑟爾那裏，用以換取塔瓦斯德的占蔔之瓶。"}},
[3376]={"刺鬃酋長",{"把刺鬃酋長的頭顱交給紅雲臺地的衛兵維薩羅·風羽。"}},
