[4290]={"拉克維的食物",{"找到拉克維剛剛獵殺的動物的屍體，從屍體上偷取壹塊蛇頸龍肉塊，然後回到安戈洛環形山的托爾瓦·尋路者那裏。"}},
[4291]={"拉克維的氣味",{"將2份暴掠龍信息素交給安戈洛爾環形山入口附近的托爾瓦·尋路者。"}},
