[4293]={"軟泥怪的樣本…",{"從費伍德的軟泥怪身上收集費伍德軟泥怪樣本，然後使用幽暗城的化學家弗雷身旁的測試設備來檢測妳所收集的樣本中哪壹份被腐化的程度最深。給化學家弗雷帶去5個被腐化的費伍德樣本。"}},
[4294]={"壹大堆軟泥怪",{"從安戈洛爾環形山那裏任何泥漿怪身上收集安戈洛泥漿怪樣本。使用幽暗城的化學家弗雷身旁的測試儀器來檢驗妳所采集到的樣本的純度。把5份純凈的安戈洛樣本送到化學家弗雷那裏去。"}},
