[4740]={"通緝：莫克迪普！",{"找到並殺死名為莫克迪普的魚人。它守護著位於奧伯丁南部海岸的魚人營地。","","向奧伯丁的哨兵戈琳達·納希恩報告莫克迪普的死訊。"}},
[4741]={"冬泉谷的梟獸",{"費伍德森林的特魯爾·法貝恩要妳去冬泉谷獵殺13頭月光梟獸。"}},
[4742]={"晉升印章",{"找到三塊命令寶石：燃棘寶鉆、尖石寶鉆和血斧寶鉆。把它們和原始晉升印章壹起交給維埃蘭。","","可能攜帶者三塊寶石的將軍是：燃棘氏族的指揮官沃恩、尖石氏族的歐莫克大王，以及血斧氏族的維姆薩拉克。"}},
[4743]={"晉升印章",{"到塵泥沼澤中的巨龍沼澤去。找到上古老龍埃博斯塔夫，對他發起無情的攻擊，直到他的意誌被摧毀。","","此時，妳必須盡快將未鑄造的晉升印章放在這條龍面前，並使用龍力寶珠控制他的軀體，強迫他將黑龍的烈焰噴向未鑄造的晉升印章！"}},
[4761]={"桑迪斯·織風",{"與奧伯丁的桑迪斯·織風談壹談。"}},
[4762]={"壁泉河",{"到奧伯丁的北面去，沿著壁泉河到達第壹個瀑布處，從瀑布下的水潭中取出壹份水樣。","","將壁泉河水樣交給奧伯丁的桑迪斯·織風。"}},
[4763]={"黑木熊怪的墮落",{"在空的凈化碗裏盛滿奧伯丁月亮井的井水。","","在黑木熊怪的北部營地裏收集水果、堅果和谷物各壹份。","","將水和三種食物混合起來，放置在壁泉河附近的營火邊，這樣就會召來喚引誘熊怪墮落的薩特。","","取回墮落護符，將它交給奧伯丁的桑迪斯·織風。"}},
[4764]={"末日扣環",{"將末日扣環交給燃燒平原的瑪亞拉·布萊特文。"}},
[4765]={"瑞治維爾的箱子",{"將瑞治維爾的箱子交給暴風城的雷明頓·瑞治維爾。"}},
