[4811]={"紅色水晶",{"到奧伯丁的東邊去，沿著黑海岸東部邊界的山脈尋找壹顆巨大的紅色水晶，然後向奧伯丁的哨兵戈琳達·納希恩匯報妳的發現。"}},
