[4906]={"更深重的墮落",{"費伍德森林的艾瑞丹·藍風要妳去殺掉8個碧火喚魔者、8個碧火背叛者、8個碧火欺詐者和薩瓦裏克。任務完成之後回到艾瑞丹那裏復命。"}},
