[4971]={"時間問題",{"在安多哈爾的壹處倉庫附近使用時光置換器，使時光寄生蟲現身。","","殺掉15只時光寄生蟲，然後將時光置換器還給西瘟疫之地安多哈爾旅店的克羅米。"}},
