[4986]={"雕文橡木枝",{"根據雕文橡木枝上面所附加的魔法，這個牛頭人德魯伊本來準備把它交給達納蘇斯的塞納裏奧議會。看來妳應該到那裏去找壹個德魯伊，並尋求他的幫助。"}},
[4987]={"雕文橡木枝",{"根據雕文橡木枝上面所附加的魔法，這個牛頭人德魯伊本來準備把它交給雷霆崖的塞納裏奧議會。看來妳應該到那裏去找壹個德魯伊，並尋求他的幫助。"}},
