[5021]={"遲到總比不到好",{"這個女人的幽靈告訴妳她要送出壹只包裹。她說那只包裹就在她的馬旁邊。至於馬在哪裏或者包裹要送到哪裏去，她卻根本沒有說。"}},
[5022]={"遲到總比不到好",{"與暴風城的皇家代理人巴瑟羅爾協商，查找到艾瑪·費爾斯通的下落。通常在市政廳裏都有壹個人口普查官。"}},
[5023]={"遲到總比不到好",{"與幽暗城的皇家管理人巴哈烏斯協商，查找傑雷米亞·費爾斯通的下落。通常在公會註冊處附近會有壹個人口普查官。"}},
