[5048]={"善良的艾瑪",{"找到暴風城的艾瑪並弄清她是否就是艾瑪·費爾斯通。如果是的話，那麽她可能想要拿到詹妮絲·費爾斯通給她的包裹。"}},
[5049]={"傑雷米亞的憂傷",{"在幽暗城找到傑雷米亞·派森並查明他是否就是妳要找的傑雷米亞·費爾斯通。如果他是的話，那麽他可能會想要拿到詹妮絲·費爾斯通寄給他的包裹。"}},
[5050]={"好運護符",{"把半個好運護符還給西瘟疫之地的詹妮絲·費爾斯通。"}},
