[5063]={"血色學者之帽",{"為了制造血色學者之帽，妳必須將下列物品交給瑪雷弗斯·暗錘：1塊比斯巨獸的皮，5根磨損的憎惡縫合線，8塊奧術水晶，5根魔化紅線。","","另外妳還必須支付50金幣的制作費用。"}},
[5064]={"恐怖圖騰的密信",{"在黑雲峰拿到三封密信。"}},
[5065]={"失落的摩沙魯石板",{"把第三塊和第四塊摩沙魯石板交給塔納利斯的勘查員詹斯·鐵靴。"}},
[5066]={"戰鬥的號角：瘟疫之地！",{"找到指揮官阿什拉姆·瓦羅菲斯特。他的大本營位於奧特蘭克山脈以北的冰風崗。"}},
[5067]={"阿卡納護腿",{"為了制造阿卡納護腿，妳必須將下列物品交給瑪雷弗斯·暗錘：1塊比斯巨獸的皮，5根磨損的憎惡縫合線，5塊奧金錠，5份萊斯·霜語的防腐液。","","另外妳還必須支付50金幣的制作費用。"}},
[5068]={"嗜血胸甲",{"為了制造嗜血胸甲，妳必須將下列物品交給瑪雷弗斯·暗錘：1塊比斯巨獸的皮，10根磨損的憎惡縫合線，5塊奧金錠，5塊暗影之皮。","","另外妳還必須支付50金幣的制作費用。"}},
[5081]={"麥克斯韋爾的任務",{"到黑石塔去消滅指揮官沃恩、歐莫克大王和維姆薩拉克。完成任務之後回到麥克斯韋爾元帥處復命。"}},
[5082]={"冬泉熊怪的威脅",{"冬泉谷的多諾瓦·雪山要妳去殺死8個冬泉探路者、8個冬泉巢穴守衛和8個冬泉圖騰師。"}},
