[5084]={"墮落熊怪",{"搜尋費伍德森林北部的死木熊怪的營帳，繼續尋找線索。"}},
[5085]={"神秘的粘液",{"將妳的發現報告給多諾瓦·雪山。"}},
[5086]={"劇毒之水",{"為冬泉谷的多諾瓦·雪山收集3份劇毒水滴。"}},
