[5092]={"掃清道路",{"殺掉悔恨嶺中的10個骷髏剝皮者和10個被奴役的食屍鬼。","","然後向西瘟疫之地冰風崗的指揮官阿什拉姆·瓦羅菲斯特復命。"}},
[5093]={"戰鬥的號角：瘟疫之地！",{"找到高級執行官德靈頓。他將自己的大本營建在提瑞斯法林地和幽暗城以東的亡靈壁壘。"}},
