[5095]={"戰鬥的號角：瘟疫之地！",{"找到高級執行官德靈頓。他將自己的大本營建在提瑞斯法林地和幽暗城以東的亡靈壁壘。"}},
[5096]={"誤導血色十字軍",{"到血色十字軍建在費爾斯通農場和達爾松之淚之間的營地去，摧毀他們的指揮帳篷。","","將亡靈天災的戰旗插在營地中，然後回到西瘟疫之地亡靈壁壘的高級執行官德靈頓那兒。"}},
[5097]={"標記哨塔",{"使用信號火炬為安多哈爾城中的四座哨塔做上標記，妳必須站在哨塔門口才能成功地進行標記。","","在做完了標記之後，將信號火炬還給西瘟疫之地冰風崗的指揮官阿什拉姆·瓦羅菲斯特。"}},
[5098]={"標記哨塔",{"使用信號火炬為安多哈爾城中的四座哨塔做上標記，妳必須站在哨塔門口才能成功地進行標記。","","在做完了標記之後，將信號火炬還給西瘟疫之地亡靈壁壘的高級執行官德靈頓。"}},
[5102]={"達基薩斯將軍之死",{"到黑石塔去殺掉達基薩斯將軍，完成任務之後就回到麥克斯韋爾元帥那裏復命。"}},
