[5122]={"信仰獎章",nil},
[5123]={"最後壹片",{"把潦草的日誌交給冬泉谷的多諾瓦·雪山。"}},
[5124]={"熾熱板甲護手",{"將6塊魔化瑟銀錠、2份火焰精華和4顆紅寶石交給瑪雷弗斯·暗錘。另外妳還得把未淬火的板甲護手也交給他。"}},
[5125]={"奧裏克斯的清算",nil},
[5126]={"羅拉克斯的故事",{"與羅拉克斯談壹談，聽聽他要說什麽。"}},
[5127]={"惡魔熔爐",{"到黑石塔去找到古拉魯克。殺死他，然後用血汙長矛刺入他的屍體。當他的靈魂被吸幹後，這支矛就會成為穿魂長矛。","","妳還必須找到未鑄造的符文覆飾胸甲。","","將穿魂長矛和未鑄造的符文覆飾胸甲都交給冬泉谷的羅拉克斯。"}},
[5128]={"熊怪酋長的話",{"將潦草的日誌交給費伍德森林南部的科雷克·望天。"}},
[5141]={"龍鱗制皮",{"將2套硬化蠍殼胸甲、2套硬化蠍殼手套和10片龍鱗交給艾薩拉的彼得·加林。","","完成這項任務之後，妳就可以學到龍鱗制皮技術了。","","同時，妳也將永遠無法學習元素制皮技術和部族制皮技術，在決定之前先考慮清楚。"}},
[5142]={"小帕米拉",{"找到帕米拉·雷德帕斯。"}},
[5143]={"部族制皮",{"將1件蠻皮外衣和1件蠻皮頭盔交給菲拉斯的凱雷希亞·獵月。","","完成這項任務之後，妳就可以學到部族制皮技術了。","","同時，妳也將永遠無法學習元素制皮技術和龍鱗制皮技術，在決定之前先考慮清楚。"}},
[5144]={"元素制皮",{"將2個火焰之心、2個純水之球、2個大地之核和2個風之氣息交給灼熱峽谷的薩拉·坦尼。","","壹旦妳完成這項任務，就可以開始學習元素制皮技藝了。","","同時，妳也就無法再學習龍鱗制皮和部落制皮了，在妳決定之前要考慮清楚。"}},
[5145]={"龍鱗制皮",{"將2套硬化蠍殼胸甲、2套硬化蠍殼手套和10片龍鱗交給荒蕪之地的索卡夫·龍眼。","","完成這項任務之後，妳就可以學到龍鱗制皮技術了。","","同時，妳也將永遠無法學習元素制皮技術和部族制皮技術，在決定之前先考慮清楚。"}},
[5146]={"元素制皮",{"將2個火焰之心、2個純水之球、2個大地之核和2個風之氣息交給阿拉希山脈的布魯姆·白蹄。","","壹旦妳完成這項任務，就可以開始學習元素制皮技藝了。","","同時，妳也就無法再學習龍鱗制皮和部落制皮了，在妳決定之前要考慮清楚。"}},
[5147]={"通緝：阿納克·恐怖圖騰",{"殺死阿納克·恐怖圖騰，並向亂風崗的峭壁衛兵圖林·長角出示證據。"}},
[5148]={"部族制皮",{"將1件蠻皮外衣和1件蠻皮頭盔交給荊棘谷的瑟伊布。","","完成這項任務之後，妳就可以學到部族制皮技術了。","","同時，妳也將永遠無法學習元素制皮技術和龍鱗制皮技術，在決定之前先考慮清楚。"}},
