[5151]={"超適應齒輪",{"殺了那頭野獸，把超適應齒輪和鑰匙交給維茲羅。"}},
[5152]={"瑪萊恩姑媽",{"與安多哈爾廢墟南邊的瑪萊恩談壹談。"}},
[5153]={"古怪的歷史學家",{"把約瑟夫的結婚戒指交給安多哈爾的克羅米。"}},
[5154]={"達隆郡的歷史",{"把《達隆郡的歷史》交給安多哈爾的克羅米。"}},
[5155]={"加德納爾的勢力",{"到加德納爾去殺掉4個加德納爾惡犬、4個加德納爾守護者、6個加德納爾精兵和6個加德納爾祭司，然後向費伍德森林的格雷塔·苔蹄復命。"}},
[5156]={"驗證腐蝕",{"殺掉2個熱能野獸和2個熱能恐獸，並探索碎痕谷。然後查看凹坑中是否仍然充滿了墮落的惡臭之水，完成這些任務之後，向費伍德森林中的塔諾恩·紅羽復命。"}},
[5157]={"收集墮落之水",{"把空壺拿到加德納爾中心的月亮井去，裝滿井水之後再回到費伍德森林的格雷塔·苔蹄那裏。"}},
[5158]={"水之魂的幫助",{"把腐化的月亮井水交給貧瘠之地的水之先知伊斯倫。"}},
[5159]={"凈化過的水",{"把凈化過的月亮井水交給費伍德森林的格雷塔·苔蹄。"}},
[5160]={"監護者",{"到冬泉谷去找到哈爾琳，把奧比的鱗片交給她。"}},
[5161]={"藍龍之怒",{"要是妳想繼續的話，就與哈爾琳談壹談。"}},
[5162]={"藍龍之怒",{"與瘟疫之地的耶茲巴交談。他居住在安多哈爾。"}},
[5163]={"雪怪計劃！",{"帶著烏米的機械雪人去嚇唬她的朋友：","","永望鎮的萊加奇（冬泉谷）、加基森的斯普琳科（塔納利斯），還有馬紹爾營地的奎克希爾（安戈洛環形山）。","","當妳完成任務之後，把機械雪人還給烏米。"}},
