[5166]={"多彩巨龍胸甲",{"為了鑄造多彩巨龍胸甲，妳必須把以下材料交給雕刻者耶茲巴：","","1塊多彩龍鱗。","","10塊閃亮的彩色龍鱗。","","10份英雄之血。","","10塊磨損的憎惡縫合線。"}},
