[5203]={"逃出加德納爾",{"護送亞科納琳到萊弗治和她的裝備所在的地方，然後保護她逃離暗影堡。之後，在費伍德森林找傑希爾·月弓，並告訴她剛才發生的事情。"}},
[5204]={"光明的懲戒",{"回到加德納爾殺了魅魔拉凱雅，然後找到特雷·萊弗治的殘骸。"}},
[5206]={"達隆郡的掠奪者",{"把5個共鳴顱骨和神秘水晶交給東瘟疫之地的卡林·雷德帕斯。"}},
