[5231]={"目標：達爾松之淚",{"到西瘟疫之地的達爾松之淚去，找到並擊敗那裏的護鍋者，用它的鑰匙打開瘟疫之鍋。妳必須隨身攜帶達爾松之淚的空瓶來采集瘟疫之鍋中的毒藥樣本。"}},
