[5233]={"目標：嚎哭鬼屋",{"到西瘟疫之地的嚎哭鬼屋去，找到並擊敗那裏的護鍋者，用它的鑰匙打開瘟疫之鍋。妳必須隨身攜帶嚎哭鬼屋的空瓶來采集瘟疫之鍋中的毒藥樣本。"}},
[5234]={"返回亡靈壁壘",{"把嚎哭鬼屋的樣本瓶交給西瘟疫之地亡靈壁壘的暗影牧師範蒂絲。"}},
[5235]={"目標：蓋羅恩農場",{"到西瘟疫之地的蓋羅恩農場去，找到並擊敗那裏的護鍋者，用它的鑰匙打開瘟疫之鍋。妳必須隨身攜帶蓋羅恩農場的空瓶來采集瘟疫之鍋中的毒藥樣本。"}},
[5236]={"返回亡靈壁壘",{"把蓋羅恩農場的樣本瓶交給西瘟疫之地亡靈壁壘的暗影牧師範蒂絲。"}},
[5237]={"任務完成！",nil},
[5238]={"任務完成！",nil},
[5241]={"卡林叔叔",{"找到卡林·瑞德巴思。"}},
[5242]={"最終壹擊",{"殺掉米萊恩和薩莉亞，並把暗影領主費爾丹的頭顱交給費伍德森林的格雷塔·苔蹄。"}},
[5243]={"神聖之屋",{"到北方的斯坦索姆去，尋找散落在城市中的補給箱，並收集5瓶斯坦索姆聖水。當妳找到足夠的聖水之後就回去向萊尼德·巴薩羅梅復命。"}},
[5244]={"凱斯利爾廢墟",{"與墜星村的加隆·石矛談壹談。"}},
[5245]={"凱斯利爾的怨靈",{"使用加隆的鎬來尋找四塊上層精靈遺物的碎片，把它們交給東瘟疫之地的奧蘿拉。"}},
[5246]={"歷史的殘片",{"在艾薩拉的辛瑪洛神殿裏找到神聖的上層精靈筆跡，並將它帶給位於東瘟疫之地的北地哨塔附近的奧蘿拉。"}},
[5247]={"歷史的殘片",{"給東瘟疫之地的奧蘿拉帶去壹塊魔化瑟銀錠、5塊恢復水晶，以及壹小瓶恐怖之水。"}},
[5248]={"記憶的折磨",{"把辛瑪洛水晶帶回冬泉谷的凱斯利爾湖，在那裏尋找壹個會與妳講話的上層精靈。"}},
[5249]={"前往冬泉谷！",{"找到冬泉谷的墜星村，在那裏與維恩德·夜風談壹談。"}},
[5250]={"墜星村",{"找到冬泉谷的墜星村，在那裏與維恩德·夜風談壹談。"}},
[5251]={"檔案管理員",{"在斯坦索姆城中找到血色十字軍的檔案管理員加爾福特，殺掉他，然後燒毀血色十字軍檔案。"}},
[5252]={"悔恨的上層精靈",{"和墜星村的維恩德·夜風談壹談，了解到辛瑪洛水晶所在的位置。"}},
[5253]={"辛瑪洛水晶",{"將辛瑪洛水晶送到達納蘇斯的大德魯伊範達爾·鹿盔那裏。"}},
[5261]={"伊根·派特斯金納",{"與伊根·派特斯金納談壹談。"}},
[5262]={"可怕的真相",{"將巴納紮爾的頭顱交給東瘟疫之地的尼古拉斯·瑟倫霍夫公爵。"}},
[5263]={"超越",{"到斯坦索姆去殺掉瑞文戴爾男爵，把他的頭顱交給尼古拉斯·瑟倫霍夫公爵。"}},
[5264]={"瑪克斯韋爾·泰羅索斯男爵",{"和瑪克斯韋爾·泰羅索斯男爵談壹談。他就在教堂裏面。"}},
[5265]={"銀色黎明寶箱",{"打開銀色黎明寶箱，拿取妳應得的獎勵。"}},
[5281]={"永不安息的靈魂",{"找到埃根。妳只知道他在斯坦索姆附近。"}},
[5282]={"永不安息的靈魂",{"對斯坦索姆城中的鬼魂使用埃根的沖擊器。當那些永不安息的靈魂掙脫他們的外殼時，再次使用埃根的沖擊器——他們就可以獲得自由了！","","解放15個永不安息的靈魂，然後回到埃根那裏去。"}},
[5283]={"鑄造護甲的藝術",{"要想成為壹名護甲鑄造師的話，妳必須將下列物品交給格魯努斯：4頂精制秘銀頭盔、2雙精制秘銀戰靴和1副精制秘銀胸甲。"}},
[5284]={"武器鑄造師之道",{"要想成為壹名武器鑄造師的話，妳必須將下列物品交給埃隆努斯·冷鋼：4把月鋼寬劍、4把巨型鐵斧、2把秘銀重斧和2把巨型黑色錘。"}},
[5301]={"鑄造護甲的藝術",{"要想成為壹名護甲鑄造師的話，妳必須將下列物品交給奧克索斯：4頂精制秘銀頭盔、2雙精制秘銀戰靴和1副精制秘銀胸甲。"}},
[5302]={"武器鑄造師之道",{"要想成為壹名武器鑄造師的話，妳必須將下列物品交給伯古什：4把月鋼寬劍、4把巨型鐵斧、2把秘銀重斧和2把巨型黑色錘。"}},
[5305]={"甜美的平靜",{"到斯坦索姆去殺死紅衣鑄錘師。將紅衣鑄錘師的圍裙交給莉莉絲。"}},
[5306]={"沃什加斯的菊石",{"到黑石塔去殺死暗影獵手沃什加斯，將沃什加斯的菊石交給基爾拉姆。"}},
[5307]={"腐蝕",{"在斯坦索姆找到黑衣守衛鑄劍師，然後殺死他。將黑色衛士徽記交給亡靈殺手瑟裏爾。"}},
[5321]={"昏昏欲睡",{"護送克羅尼亞·恒影到灰谷邁斯特拉崗哨的利拉迪斯·月河那裏去。"}},
[5341]={"巴羅夫家族的寶藏",{"到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到阿萊克斯·巴羅夫那兒去。"}},
[5342]={"巴羅夫的繼承人",{"到冰風崗——聯盟的領地——去暗殺維爾頓·巴羅夫。把他的腦袋交給阿萊克斯·巴羅夫。","","要多加小心，聯盟也許對維爾頓實施了嚴密的保護。"}},
[5343]={"巴羅夫家族的寶藏",{"到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到維爾頓·巴羅夫那兒去。"}},
[5344]={"巴羅夫的繼承人",{"去亡靈壁壘——部落的領地——去暗殺阿萊克斯·巴羅夫。把他的腦袋交給維爾頓·巴羅夫。","","要小心，部落也許對阿萊克斯實施了嚴密的保護。"}},
[5361]={"兄弟",{"將峭壁衛兵圖林·長角的報告交給淒涼之地幽靈崗哨的納塔卡·長角。"}},
[5381]={"埃魯索斯之手",{"在雷斧堡壘中找到惡魔之盒，把它和惡魔之鋤壹起交給葬影村的泰迦·慧鬃。"}},
[5382]={"瑟爾林·卡斯迪諾夫教授",{"在通靈學院中找到瑟爾林·卡斯迪諾夫教授。殺死他，並燒毀艾瓦·薩克霍夫和盧森·薩克霍夫的遺體。任務完成後就回到艾瓦·薩克霍夫那兒。"}},
[5384]={"傳令官基爾圖諾斯",{"帶著無辜者之血回到通靈學院，將它放在門廊的火盆下面，基爾圖諾斯會前來吞噬妳的靈魂。","","勇敢地戰鬥吧，不要退縮！殺死基爾圖諾斯，然後回到艾瓦·薩克霍夫那兒。"}},
[5385]={"特雷·萊弗治的殘骸",{"將特雷·萊弗治的殘骸交給費伍德森林的傑希爾·月弓。"}},
[5386]={"食魚度日",{"與葬影村的吉納澤林談話，然後將2條血肚魚交給納塔卡·長角。"}},
