[5515]={"卡斯迪諾夫的恐懼之袋",{"在通靈學院找到詹迪斯·巴羅夫並打敗她。從她的屍體上找到卡斯迪諾夫的恐懼之袋，然後將其交給艾瓦·薩克霍夫。"}},
[5517]={"多彩黎明襯肩",{"把25個銀色黎明勇氣勛章交給東瘟疫之地聖光之願禮拜堂的銀色黎明軍需官米蘭達·布利洛克。"}},
[5518]={"戈多克食人魔裝",{"把4份符文布卷、8塊硬甲皮、2卷符文線和壹份食人魔鞣酸交給諾特·希姆加克。他現在被拴在厄運之槌的戈多克食人魔那邊。"}},
