[5522]={"萊尼德·巴薩羅梅",{"把冰凍的龍蛋交給東瘟疫之地的萊尼德·巴薩羅梅。"}},
[5524]={"多彩黎明襯肩",{"把25個銀色黎明勇氣勛章交給西瘟疫之地亡靈壁壘的銀色黎明軍銀色黎明軍需官哈薩娜。"}},
[5525]={"逃出生天！",nil},
[5526]={"魔藤碎片",{"在厄運之槌中找到魔藤，然後從它上面采集壹塊碎片。只有幹掉了奧茲恩之後，妳才能進行采集工作。使用凈化之匣安全地封印碎片，然後將其交給月光林地永夜港的拉比恩·薩圖納。"}},
[5527]={"凈化之匣",{"到希利蘇斯的南風村去尋找凈化之匣。然後將其交給月光林地永夜港的拉比恩·薩圖納。"}},
[5528]={"戈多克好酒",nil},
[5529]={"瘟疫之龍",{"殺掉20只瘟疫龍崽，然後向聖光之願禮拜堂的貝蒂娜·比格辛克復命。"}},
[5531]={"貝蒂娜·比格辛克",{"將冰凍的龍蛋交給貝蒂娜·比格辛克。"}},
[5533]={"通靈學院",{"和西瘟疫之地冰風崗的化學家阿爾比頓談壹談。"}},
[5534]={"基姆加爾“丟失”的裝備",{"尋找埃達拉斯廢墟中的納迦攜帶的那些符石，然後把它們交給艾薩拉的基姆加爾。"}},
[5535]={"永不安息的靈魂",{"殺掉6個上層精靈的幻影和6個上層精靈鬼巫，然後向艾薩拉的羅哈圖復命。"}},
[5536]={"充滿仇恨的土地",{"殺掉6個哈達爾薩特、2個哈達爾欺詐者和2個哈達爾魔仆，然後向灰谷與艾薩拉交界處的羅哈圖復命。"}},
[5537]={"骸骨碎片",{"將15塊骷髏碎片交給西瘟疫之地冰風崗的化學家阿爾比頓。"}},
[5538]={"昂貴的模具",{"把灌魔的骸骨碎片和15枚金幣交給加基森的克林科·古德斯迪爾。"}},
[5541]={"海格納的彈藥",{"把海格納的彈藥交給丹莫羅的海格納·重槍。"}},
[5542]={"惡魔之犬",{"殺掉20條瘟疫幼犬、5條瘟疫犬和5條狂怒的瘟疫犬。任務完成之後向提裏奧·弗丁復命。"}},
[5543]={"血染的天空",{"殺死30只瘟疫蝙蝠，然後向提裏奧·弗丁復命。"}},
[5544]={"腐肉蟲",{"在東瘟疫之地搜索腐肉蟲和腐肉吞噬者。殺了它們並收集它們的肉。當妳收集到15塊食腐蟲肉塊之後，就回到提裏奧·弗丁那裏。"}},
[5545]={"木材危機",{"收集8捆木材，把它們交給東谷伐木場的管理員萊琳。"}},
[5561]={"誘捕科多獸",{"將科多獸誘引器和5頭被馴服的科多獸交給瑟卡布斯庫的營地中的斯米德·瑟卡布斯庫。"}},
[5581]={"燃燒軍團的傳送門",{"放逐6個瑪諾洛克集會所的傳送門，然後回到葬影村的泰迦·慧鬃那裏。"}},
[5582]={"健康的龍鱗",{"把健康的龍鱗交給東瘟疫之地聖光之願禮拜堂中的貝蒂娜·比格辛克。"}},
[5601]={"小妹妹帕米拉",{"在達隆郡裏找到帕米拉·雷德帕斯。"}},
[5621]={"月光之衣",{"找到哨兵莎恩雅並使用次級治療術（等級 2）來治療她。然後對她施放真言術：韌，最後向多蘭納爾的勞爾娜·晨光復命。"}},
[5622]={"月神的恩賜",{"與泰達希爾的勞爾娜·晨光談壹談。"}},
