[5721]={"達隆郡的戰鬥",{"將遺物包裹放在達隆郡的廣場中。","","在霍古斯死亡之前，達維必須存活。","","在雷德帕斯隊長墮落之前保證他存活。","","擊敗墮落的雷德帕斯。","","當約瑟夫·雷德帕斯出現在廣場中時，與他的靈魂進行交談，然後回到帕米拉的家中去找帕米拉。"}},
[5722]={"尋找背包",{"在怒焰裂谷搜尋瑪爾·恐怖圖騰的屍體以及他留下的東西。"}},
[5723]={"試探敵人",{"在奧格瑞瑪找到怒焰裂谷，殺掉8個怒焰穴居人和8個怒焰薩滿祭司，然後向雷霆崖的拉哈羅復命。"}},
[5724]={"歸還背包",{"將恐怖圖騰背包交給雷霆崖的拉哈羅。"}},
[5725]={"毀滅之力",{"將《暗影法術研究》和《扭曲虛空的魔法》這兩本書交給幽暗城的瓦裏瑪薩斯。"}},
[5726]={"隱藏的敵人",{"將軍官的徽章交給奧格瑞瑪的薩爾。"}},
[5727]={"隱藏的敵人",{"將軍官的徽章交給尼爾魯·火刃並與他談壹談，看看他是否相信妳是火刃氏族中的壹員，然後回到奧格瑞瑪的薩爾那裏。"}},
[5728]={"隱藏的敵人",{"殺死巴紮蘭和祈求者耶戈什，然後回到奧格瑞瑪的薩爾那裏。"}},
[5729]={"隱藏的敵人",{"與奧格瑞瑪的尼爾魯·火刃談壹談。"}},
[5730]={"隱藏的敵人",{"與奧格瑞瑪的薩爾談壹談，告訴他妳了解到的東西。"}},
[5741]={"聖光節杖",{"拿到聖光節杖，並將它交給艾瑟雷索塔裏的阿佐爾·奧達蒙特。"}},
[5742]={"救贖",{"聽聽提裏奧·弗丁要說什麽。"}},
[5761]={"饑餓者塔拉加曼",{"進入怒焰裂谷，殺死饑餓者塔拉加曼，然後把他的心臟交給奧格瑞瑪的尼爾魯·火刃。"}},
[5762]={"赫米特·奈辛瓦裏",{"將克拉維爾的箱子送到荊棘谷的赫米特·奈辛瓦裏那裏。"}},
[5763]={"荊棘谷狩獵",{"將魯恩的科多獸角送到荊棘谷的赫米特·奈辛瓦裏那裏。"}},
[5781]={"遺忘的記憶",{"到東瘟疫之地最南端的墓室去找回泰蘭之錘。完成目標之後，返回提裏奧·弗丁那裏。"}},
[5801]={"火羽山",{"把骷髏鑰匙模具和2塊瑟銀錠帶到安戈洛爾環形山地區的火羽山頂部。在熔巖湖旁使用骷髏鑰匙模具，鑄造出壹把未完工的骷髏鑰匙。","","把未完工的骷髏鑰匙交給西瘟疫之地冰風崗的化學家阿爾比頓。"}},
[5802]={"火羽山",{"把骷髏鑰匙模具和2塊瑟銀錠帶到安戈洛爾環形山地區的火羽山頂部。在熔巖湖旁使用骷髏鑰匙模具，鑄造出壹把未完工的骷髏鑰匙。","","把未完工的骷髏鑰匙交給西瘟疫之地亡靈壁壘的藥劑師迪瑟斯。"}},
[5803]={"阿拉基的聖甲蟲",{"殺掉召喚者阿拉基，並將阿拉基的聖甲蟲交給西瘟疫之地冰風崗的化學家阿爾比頓。"}},
[5804]={"阿拉基的聖甲蟲",{"殺掉召喚者阿拉基，並將阿拉基的聖甲蟲交給西瘟疫之地亡靈壁壘的藥劑師迪瑟斯。"}},
[5821]={"雇傭保鏢",{"護送基澤爾頓商隊通過科卡爾半人馬村，然後與瑟卡布斯庫的營地中的斯米德談話以領取妳的獎賞。"}},
[5845]={"失落的榮耀",{"到東瘟疫之地東北部的北谷去，找到失落榮耀的象征。完成目標之後向提裏奧·弗丁復命。"}},
[5846]={"愛與家庭",{"到凱爾達隆島去，尋找關於那副畫的線索。凱爾達隆島在瘟疫之地南部的湖中央。"}},
[5848]={"愛與家庭",{"到瘟疫之地北部的斯坦索姆去。妳可以在血色十字軍堡壘中找到“愛與家庭”這幅畫，它被隱藏在另壹幅描繪兩個月亮的畫之後。","","把這幅畫還給提裏奧·弗丁。"}},
[5861]={"尋找麥蘭達",{"到瘟疫之地南部的烏瑟爾之墓去，將提裏奧的禮物交給巫女麥蘭達。"}},
[5862]={"血色幻象",{"和巫女麥蘭達交談以獲得血色幻象的效果。在血色幻象的掩護下深入壁爐谷，將提裏奧的禮物交給大領主泰蘭·弗丁。","","壁爐谷在北方，泰蘭應該在瑪登霍爾德城堡裏面。"}},
[5863]={"砂槌食人魔",{"加基森的安迪·利恩想要妳攻入砂槌營地，殺死10個砂槌蠻兵、10個砂槌執行者，以及掠奪者格瑪洛克。"}},
