[5943]={"基澤爾頓車隊",{"護送基澤爾頓車隊通過瑪諾洛克集會所，然後與瑟卡布斯庫的營地的斯米德談壹談，領取妳的獎勵。"}},
[5944]={"在夢中",{"護送泰蘭·弗丁走出壁爐谷。"}},
[5961]={"女妖之王的勇士",{"與東瘟疫之地的納薩諾斯·雕零者談壹談。據說他居住在瑪瑞斯農場。"}},
[5981]={"狂暴的巨人",{"雷沃·霜翼要妳去殺死4個霜槌巨人和4個霜槌保衛者。"}},
[6001]={"身心之力",{"使用奧伯丁的月夜梟獸之石上面的塞納裏奧月塵引出月爪梟獸，然後擊敗月爪梟獸並吸取它所擁有的身心之力。","","任務完成之後，與達納蘇斯的瑪斯雷·馭熊者談壹談。"}},
[6002]={"身心之力",{"使用莫高雷與貧瘠之地交界處的月夜梟獸之石上面的塞納裏奧月塵引出月爪梟獸，然後擊敗月爪梟獸並吸取它所擁有的身心之力。","","任務完成之後，與雷霆崖的圖拉克·符文圖騰談壹談。"}},
[6004]={"未竟的事業",{"殺死2個血色醫護員、2個血色獵人、2個血色魔法師和2個血色騎士，然後回到西瘟疫之地的科爾斯塔·迪普沙東那兒。"}},
[6021]={"流亡者塞達爾",{"將塞達爾的頭顱交給聖光之願禮拜堂的護理者奧林。"}},
[6022]={"殺戮的理由",{"到東邊的考林路口去屠殺鎮裏的亡靈天災。在10分鐘內收集7塊生命腐質，使用研缽和搗杵將其研磨成凝固腐質。"}},
[6023]={"未完的任務",{"殺掉獵人萊德雷和騎士杜爾根，然後向西瘟疫之地的科爾斯塔·迪普沙東復命。"}},
[6024]={"哈米亞的請求",{"殺了滲透者哈米亞，用他的鑰匙開啟墓室後的壹堆泥土。"}},
[6025]={"未完的任務",{"進入壁爐谷並找壹處高地，妳可以在那裏觀察整個城鎮並估算血色十字軍的兵力，然後向西瘟疫之地的科爾斯塔·迪普沙東回報。"}},
[6026]={"獅子大開口",{"煙鬼拉魯恩要妳拿來2塊瑟銀錠、1根金棒、8顆高爆炸彈和8個不牢固的扳機。","","妳需要找鐵匠和工程學技師幫忙制作這些東西。"}},
[6027]={"上古之書",{"拿到上古之書，將其交給艾瑟雷索塔中的阿佐爾·奧達蒙特。"}},
[6028]={"永望鎮報告",{"把永望鎮報告送給西瘟疫地冰風崗的銀色黎明軍官普爾哈特。"}},
[6029]={"永望鎮報告",{"把永望鎮報告送給西瘟疫地亡靈壁壘的銀色黎明軍官加魯什。"}},
[6030]={"尼古拉斯·瑟倫霍夫公爵",{"將《靈語研究》這本書交給東瘟疫之地聖光之願禮拜堂的尼古拉斯·瑟倫霍夫公爵。"}},
