[6041]={"煙鬼的炸藥",{"到聖光之願禮拜堂西北方的病木林去。在那些有爆炸標記的建築物中對爆炸標記使用煙鬼的特殊混合物，以此來摧毀8座亡靈天災建築。煙鬼已經給通靈塔和屠宰房做上了標記。","","壹旦妳放置好炸彈，就離那些建築物遠壹些，然後盡情欣賞妳的傑作吧。","","順便說壹句，煙鬼的特殊混合物相當不穩定……"}},
