[6128]={"收集解藥",{"收集5個地根草和5個科多獸角，把它們交給十字路口的圖加·符文圖騰，這樣他就可以制作解藥了。"}},
[6129]={"消除疾病",{"對貧瘠之地北部的10只生病的瞪羚使用動物醫療藥膏，以此來治療它們。在穿過十字路口的那條東西走向的大路北面到處都是生病的蹬羚。"}},
