[6146]={"納薩諾斯的計謀",{"到瑪瑞斯農場東南方的提爾之手去，抵達那裏之後就咬壹口爛蘋果。在血色十字軍偽裝的掩護下，把大十字軍的命令交給十字軍領主瓦德瑪爾。"}},
