[6148]={"血色十字軍聖者，德米提雅",{"血色十字軍正在從提爾之手到斯坦索姆的路上巡邏，妳可以在巡邏隊中找到聖者德米提雅和她的隨從，找到並殺死她。如果妳成功了，就回到納薩諾斯·雕零者那裏去復命。"}},
