[6481]={"土靈的覺醒",{"使用魔化共鳴水晶打開共鳴桶，然後殺死高戈羅克。將這個消息告訴摩羅加爾，並把魔化共鳴水晶還給他。"}},
[6482]={"魯爾的自由",{"護送魯爾，然後與慰藉之林的雅瑪·雪蹄談壹談。"}},
[6501]={"巨龍之眼",{"妳必須尋遍世界以找到壹種能恢復龍眼碎片的能量的生物。妳對這種生物的唯壹了解就是：他們確實存在。"}},
[6502]={"龍火護符",{"妳必須從達基薩斯將軍身上取回黑龍勇士之血，妳可以在黑石塔的晉升大廳後面的房間裏找到他。"}},
[6503]={"灰谷先驅者",{"殺掉9個灰谷先驅者，然後回到碎木哨崗的庫萊比那裏。"}},
[6504]={"丟失的書頁",{"找到丟失的12頁伐木機操作指南，把它們合並為第1、2、3章。然後帶著這些書頁回到碎木崗哨去找古爾達·怒痕。"}},
[6521]={"邪惡的盟友",{"把瑪克林大使的頭顱交給幽暗城的瓦裏瑪薩斯。"}},
[6522]={"邪惡的盟友",{"把小卷軸交給幽暗城的瓦裏瑪薩斯。"}},
[6523]={"保護卡雅",{"護送卡雅·扁蹄回到阿帕拉耶營地，然後到石爪山東南邊界附近的瑪卡巴·扁蹄那裏去復命。"}},
[6541]={"向卡德拉克報到",{"到貧瘠之地北部的卡德拉克那裏報到。"}},
[6542]={"向卡德拉克報到",{"到貧瘠之地北部的卡德拉克那裏報到。"}},
[6543]={"戰歌報告",{"打開報告集，把戰歌報告交給戰歌斥候、戰歌信使和戰歌偵查騎兵。把他們的最新報告交給貧瘠之地北部哨塔上的卡德拉克。"}},
[6544]={"托雷克的突襲",{"保護在銀翼哨站與杜瑞爾·月火作戰的托雷克，然後向慰籍之林的埃爾托格·怒齒匯報勝利的消息。"}},
[6545]={"戰歌信使的報告",nil},
[6546]={"戰歌侍從的報告",nil},
[6547]={"戰歌斥候的報告",nil},
[6548]={"為我的村莊復仇",{"殺掉8個恐怖圖騰惡徒和6個恐怖圖騰傭兵，然後向石爪山脈東南邊界處的瑪卡巴·扁蹄復命。"}},
[6561]={"黑暗深淵中的邪惡",{"把夢遊者克爾裏斯的頭顱交給雷霆崖的巴珊娜·符文圖騰。"}},
[6562]={"幫助耶努薩克雷",{"與灰谷的耶努薩克雷談壹談。"}},
[6563]={"阿庫麥爾水晶",{"收集20顆阿庫麥爾藍寶石，把它們交給灰谷的耶努薩克雷。"}},
[6564]={"上古之神的仆從",{"把潮濕的便箋交給灰谷的耶努薩克雷。"}},
[6565]={"上古之神的仆從",{"殺掉黑暗深淵裏的洛古斯·傑特，然後向灰谷的耶努薩克雷復命。"}},
[6566]={"風吹來的消息",{"聽薩爾講話。"}},
[6567]={"部落的勇士",{"按照酋長的指示找到雷克薩。他在石爪山和菲拉斯之間的淒涼之地遊蕩。"}},
[6568]={"雷克薩的證明",{"把雷克薩的證明交給西瘟疫之地的巫女麥蘭達。"}},
[6569]={"黑龍幻象",{"到黑石塔去收集20顆黑色龍人的眼球，完成任務之後回到巫女麥蘭達那裏。"}},
[6570]={"埃博斯塔夫",{"到塵泥沼澤中的巨龍沼澤去，找到埃博斯塔夫的洞穴。進入洞穴之後戴上龍形護符，然後跟埃博斯塔夫交談。"}},
[6571]={"戰歌氏族的補給品",{"收集戰歌氏族的補給品：戰歌鋸條、伐木繩、戰歌之油，還有壹箱戰歌之斧。"}},
[6581]={"戰歌鋸條",nil},
[6582]={"龍骨試煉，斯克利爾",{"找到藍龍斯克利爾並殺掉他。從他的身上取下他的顱骨，然後將其交給埃博斯塔夫。","","妳可以在冬泉谷找到斯克利爾。"}},
[6583]={"龍骨試煉，索姆努斯",{"殺掉綠龍索姆努斯，把他的顱骨交給埃博斯塔夫。"}},
[6584]={"龍骨試煉，克魯納裏斯",{"諾茲多姆的孩子克魯納裏斯在塔納利斯沙漠守衛著時光之穴。殺了他，把他的顱骨交給埃博斯塔夫。"}},
[6585]={"龍骨試煉，埃克托茲",{"到格瑞姆巴托去殺掉紅龍埃克托茲，把他的顱骨交給埃博斯塔夫。"}},
[6601]={"晉升……",{"看來這場假面舞會就要結束了。妳知道麥蘭達為妳制作的龍形護符在黑石塔裏面不會發揮作用，也許妳應該去找雷克薩，將妳的困境告訴他。把黯淡的龍火護符給他看看，也許他知道下壹步該怎麽做。"}},
[6602]={"黑龍勇士之血",{"到黑石塔去殺掉達基薩斯將軍，把它的血交給雷克薩。"}},
[6603]={"冬泉谷的麻煩！",{"到冬泉谷的溫泉附近去找到多諾瓦·雪山。"}},
[6604]={"被激怒的梟獸",{"與墜星村的加隆·石矛談壹談。"}},
[6605]={"奇怪的家夥",{"與費伍德森林的溫娜·哈薩德談壹談。"}},
[6607]={"釣魚專家納特·帕格",{"納特·帕格要妳釣到以下幾種魚：","","悲傷沼澤蘆葦海岸的蘆葦海岸大馬哈魚。","","淒涼之地薩瑟裏斯海岸的薩瑟裏斯虎魚。","","菲拉斯沃丹提斯河的菲拉斯草魚。","","荊棘谷野人海岸的野人海岸藍色叉牙魚。","","當妳釣到這些魚之後，就可以回到納特·帕格那裏去了！"}},
[6608]={"妳真棒！",{"妳認為魯瑪克想要告訴妳，他已經不能幫妳提高釣魚的技能了。也許妳應該去找到他的朋友納特·帕格，他居住在塞拉摩以南的某個島嶼上，他是壹名人類漁夫（至少妳認為魯瑪克是這麽說的）。"}},
[6609]={"青出於藍！",{"到卡利姆多大陸的塞拉摩去。從那裏向南方出發，找到壹座島嶼。納特·帕格就在島上等待著妳的到來！"}},
[6610]={"蚌肉大餐",{"迪爾格·奎克裏弗想要妳收集這些原料：","","12只巨蛋。妳可以在塔納利斯的大鵬或是其它大型鳥類那裏獲得這種蛋。","","10塊美味的蚌肉。妳可以從任何蚌類身上獲得這種原料！","","20塊奧特蘭克冷酪。去買就是了！","","收集好所有原料，然後把它們交給迪爾格。"}},
[6611]={"加基森之旅！",{"到塔納利斯沙漠的加基森去，與迪爾格·奎克裏弗談談妳的廚師生涯。"}},
[6612]={"我認識壹個家夥…",{"到塔納利斯沙漠的加基森去，與迪爾格·奎克裏弗談談妳的廚師生涯。"}},
[6621]={"汙林熊怪之王",{"把卡拉恩的旗子插到汙林圖騰堆中。不要讓熊怪摧毀這面旗子。擊敗穆戈特酋長，將穆戈特的圖騰交給佐拉姆加的卡拉恩·阿瑪卡。"}},
[6622]={"救死扶傷",{"使用急救繃帶來治療病人。妳必須在6個病人死亡之前拯救15個病人。","","壹定要牢記治療的順序！受致命傷的病人會很快死亡，其次是重傷病人，受普通傷的病人死亡得最慢。所以妳最好在治療那些受致命傷和重傷的病人之後再去治療受普通傷的病人。"}},
[6623]={"部落醫療隊",{"到阿拉希高地的落錘鎮去，與格裏高利·維克托醫生談壹談關於加入部落外科醫療隊的事宜。"}},
[6624]={"救死扶傷",{"使用急救繃帶來治療病人。妳必須在6個病人死亡之前拯救15個病人。","","壹定要牢記治療的順序！受致命傷的病人會很快死亡，其次是重傷病人，受普通傷的病人死亡得最慢。所以妳最好在治療那些受致命傷和重傷的病人之後再去治療受普通傷的病人。"}},
[6625]={"聯盟醫療隊",{"到塵泥沼澤的塞拉摩去，與古斯塔夫·範沃森醫生談壹談關於加入聯盟外科醫療隊的事宜。"}},
[6626]={"邪惡之地",{"殺掉8個剃刀沼澤護衛者、8個剃刀沼澤織棘者和8個亡首教徒，然後向剃刀高地入口處的麥雷姆·月歌復命。"}},
[6627]={"知識試煉",{"成功回答布勞格·幽魂的問題，然後和他再次對話。他會壹直在石爪山等妳回答問題。"}},
[6628]={"知識試煉",{"成功回答帕科瓦·芬塔拉斯的問題，然後再次和他對話。他會壹直在幽暗城等妳回答問題。"}},
[6629]={"殺死格魯迪格·暗雲",{"殺掉格魯迪格·暗雲和6個恐怖圖騰蠻兵，然後向石爪山東南面的瑪卡巴·扁蹄復命。"}},
[6641]={"鞭笞者沃爾沙",{"在穆格拉什尋找火盆的過程中保證他的安全。幫助他撲滅火盆，然後在與納迦作戰時保護他。","","如果妳成功了，就回到佐拉姆加前哨站去，把鞭笞者沃爾沙的死訊通知給戰歌信使。"}},
