[6661]={"捕捉礦道老鼠",{"使用捕鼠者之笛捕獲5只礦道老鼠，把它們引到蒙提那兒去。別忘了退還笛子。"}},
[6662]={"我的兄弟，尼普希",{"把裝著神秘肉品的紙箱交給暴風城礦道地鐵倉庫的尼普希。"}},
[6681]={"拉文霍德莊園",{"把拉文霍德徽記交給拉文霍德莊園的法拉德，莊園就坐落在希爾斯布萊德的群山之中。","","妳的智慧將在這次旅途中得到考驗。做好準備吧。"}},
