[6741]={"取之於敵",nil},
[6761]={"新的邊疆",{"與達納蘇斯的塞納裏奧區的瑪斯雷·馭熊者談壹談。"}},
[6762]={"拉比恩·薩圖納",{"與月光林地永夜港的拉比恩·薩圖納談壹談。月光林地在費伍德森林和冬泉谷之間，可以從木喉要塞中的壹條通道抵達那裏。"}},
