[6981]={"發光的碎片",{"尋找更多有關這塊噩夢碎片的信息。"}},
[6982]={"冷齒礦洞的補給",{"把10份冷齒礦洞補給品交給丹巴達爾的聯盟軍需官。"}},
[6985]={"深鐵礦洞的補給",{"把10份深鐵礦洞補給品交給霜狼要塞的部落軍需官。"}},
[7001]={"補充坐騎",{"找到奧特蘭克山谷中的霜狼。使用霜狼口套來馴服它們。被馴服的霜狼會跟隨妳回到獸欄管理員那裏，然後與獸欄管理員談話以獲得妳的獎勵。"}},
[7002]={"羊皮坐具",nil},
[7003]={"被縮小的巨人",{"使用索爾賓的超級壓縮器來縮小菲拉斯的任意種類的巨人，將他們縮小到更容易控制的體積。從縮小過的巨人身上收集15份微縮殘渣，把它們交給菲拉斯被遺忘的海岸碼頭的索爾賓·範達瑟。"}},
[7026]={"山羊坐具",nil},
[7027]={"補充坐騎",{"找到奧特蘭克山谷中的山羊。使用雷矛訓練頸圈來馴服它們。被馴服的山羊會跟隨妳回到獸欄管理員那裏，然後與獸欄管理員談話以獲得妳的獎勵。"}},
[7028]={"扭曲的邪惡",{"為淒涼之地的維洛收集25個瑟萊德絲水晶雕像。"}},
[7029]={"維利塔恩的汙染",{"在瑪拉頓裏用天藍水瓶在橙色水晶池中裝滿水。","","在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。","","治療8株植物並殺死那些諾克賽恩幼體，然後向葬影村的瓦克·戰痕復命。"}},
[7041]={"維利塔恩的汙染",{"在瑪拉頓裏用天藍水瓶在橙色水晶池中裝滿水。","","在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。","","治療8株植物並殺死那些諾克賽恩幼體，然後向尼耶爾前哨站的塔琳德莉亞復命。"}},
[7044]={"瑪拉頓的傳說",{"找回塞雷布拉斯節杖的兩個部分：塞雷布拉斯魔棒和塞雷布拉斯鉆石。","","然後設法和塞雷布拉斯對話。"}},
[7046]={"塞雷布拉斯節杖",{"幫助贖罪的塞雷布拉斯制作塞雷布拉斯節杖。","","當儀式完成之後再和他談談。"}},
[7064]={"大地的汙染",{"殺死瑟萊德絲公主，然後回到淒涼之地葬影村附近的瑟琳德拉那裏復命。"}},
[7065]={"大地的汙染",{"殺死瑟萊德絲公主，然後回到淒涼之地尼耶爾前哨站的守護者瑪蘭迪斯那裏復命。"}},
[7066]={"生命之種",{"到月光林地去找到雷姆洛斯，將生命之種交給他。"}},
[7067]={"賤民的指引",{"閱讀賤民的指引，然後從瑪拉頓得到聯合墜飾，將其交給淒涼之地南部的半人馬賤民。"}},
[7068]={"暗影殘片",{"從瑪拉頓收集10塊暗影殘片，然後把它們交給奧格瑞瑪的尤塞爾奈。"}},
[7070]={"暗影殘片",{"從瑪拉頓收集10塊暗影殘片，然後把它們交給塵泥沼澤塞拉摩島上的大法師特沃什。"}},
[7081]={"奧特蘭克山谷的墓地",{"占領壹座墓地，然後向丹巴達爾的諾雷格·雷矛中尉復命。"}},
[7082]={"奧特蘭克的墓地",{"占領壹座墓地，然後向霜狼村的亞斯拉復命。"}},
[7101]={"哨塔和碉堡",{"占領敵方的某座哨塔，然後向霜狼村的提卡·血牙復命。"}},
[7102]={"哨塔和碉堡",{"摧毀敵方的某座哨塔或者碉堡中的旗幟，然後向丹巴達爾的杜爾根·雷矛復命。"}},
[7121]={"軍需官",{"與雷矛軍需管談壹談。"}},
[7122]={"占領礦洞",{"占領壹座還沒有被雷矛部族控制的礦洞，然後向丹巴達爾的雷矛軍需官復命。"}},
[7123]={"霜狼軍需官",{"與霜狼軍需官談壹談。"}},
[7124]={"占領礦洞",{"占領壹座礦洞，然後向霜狼村的霜狼軍需官報告。"}},
[7141]={"奧特蘭克的戰鬥",{"進入奧特蘭克山谷，擊敗部落將軍德雷克塔爾。然後回到勘查員塔雷·石鎬那裏。"}},
[7142]={"為奧特蘭克而戰",{"進入奧特蘭克山谷，擊敗矮人將軍範達爾·雷矛。然後回到沃加·死爪那裏。"}},
[7161]={"試煉場",{"到主基地東南邊的蠻爪洞穴中去找到霜狼軍旗，然後把它交給拉格隆德。"}},
[7162]={"試煉場",{"到主基地東南邊的冰翼洞穴中去找到雷矛軍旗，然後把它交給哈格丁中尉。"}},
