[7181]={"科爾拉克的傳說",{"血怒者科爾拉克躲在冰斧洞穴的深處。據說只有在第1001個冰斧巨魔被幹掉的時候，這個強大的冰斧巨魔領袖才會出現。","","到冰斧洞穴中去，殺掉所有擋在妳面前的巨魔，直到科爾拉克出現為止。殺掉科爾拉克，然後向拉格隆德復命。"}},
[7201]={"最後的元素",{"到黑石深淵去取得10份元素精華。妳應該在那些作戰傀儡和傀儡制造者身上找找，另外，薇薇安·拉格雷也提到了壹些有關元素生物的話題……"}},
[7202]={"血怒者科爾拉克",{"血怒者科爾拉克躲在冰斧洞穴的深處。據說只有在第1001個冰斧巨魔被幹掉的時候，這個強大的冰斧巨魔領袖才會出現。","","到冰斧洞穴中去，殺掉所有擋在妳面前的巨魔，直到科爾拉克出現為止。殺掉科爾拉克，然後向哈格丁中尉復命。"}},
[7223]={"護甲碎片",{"給丹巴達爾的莫高特·深爐帶去20塊護甲碎片。"}},
[7224]={"敵人的物資",{"給霜狼村的鐵匠雷格薩帶去20塊護甲碎片。"}},
[7241]={"保衛霜狼氏族",{"到希爾斯布萊德丘陵地區的奧特蘭克山谷去。找到拉格隆德並和他談談，然後成為霜狼氏族的士兵。"}},
[7261]={"國王的命令",{"到希爾斯布萊德丘陵地區的奧特蘭克山谷去。到那裏之後，和哈格丁中尉談談。","","為了銅須的榮耀！"}},
[7321]={"海龜湯",{"給塔倫米爾的克裏斯托弗·傑弗寇特帶去10塊海龜肉和壹些舒心草。"}},
[7341]={"公平交易",nil},
[7342]={"膽小鬼才用弓箭！",nil},
[7366]={"大主教的仁慈",{"妳被指派去殺死奧特蘭克山谷中的被遺忘者玩家。","","殺死壹個被遺忘者，然後把壹枚被遺忘者的精華交給指揮官卡爾·菲利普（他壹般在伐木場和礦井之間徘徊）。"}},
[7381]={"科爾拉克歸來",{"如果科爾拉克重新出現在奧特蘭克山谷的冰斧山洞中，就找到並幹掉他。","","將科爾拉克的徽記交給霜狼要塞的拉格隆德。"}},
[7382]={"永生的科爾拉克",{"如果科爾拉克重新出現在奧特蘭克山谷的冰斧山洞中，就找到並幹掉他。","","將科爾拉克的徽記交給丹巴達爾的哈格丁中尉。"}},
[7383]={"大地之冠",{"用月亮井的水裝滿紫水晶瓶，然後把它交給多蘭納爾的科瑞薩斯·月怒。"}},
[7385]={"聯盟之血",nil},
[7386]={"水晶簇",nil},
[7429]={"逃出生天！",nil},
[7441]={"普希林和埃斯托爾迪",{"到厄運之槌去找到小鬼普希林。妳可以使用任何手段從小鬼那裏得到埃斯托爾迪的咒術之書。","","找到咒術之書後，回到拉瑞斯小亭的埃斯托爾迪那裏。"}},
[7461]={"伊莫塔爾的瘋狂",{"妳必須幹掉5座水晶塔周圍的守衛，那5座水晶塔維持著關押伊莫塔爾的監獄。壹旦水晶塔的能量被削弱，伊莫塔爾周圍的能量力場就會消散。","","進入伊莫塔爾的監獄，幹掉站在中間的那個惡魔。最後，在圖書館挑戰托塞德林王子。","","當任務完成之後，到庭院中去找辛德拉古靈。"}},
[7463]={"久違的法師",{"到厄運之槌的扭木廣場去殺掉水元素海多斯博恩。把海多斯博恩精華交給圖書館的博學者萊德羅斯。"}},
[7481]={"精靈的傳說",{"到厄運之槌去尋找卡裏爾·溫薩魯斯。向莫沙徹營地的先知科魯拉克報告妳所找到的信息。"}},
[7482]={"精靈的傳說",{"到厄運之槌去尋找卡裏爾·溫薩魯斯。向羽月要塞的學者盧索恩·紋角報告妳所找到的信息。"}},
[7483]={"急速聖典",{"將急速聖典、1塊原始黑鉆石、2份大塊魔光碎片和2份英雄之血交給厄運之槌的博學者萊德羅斯，以換取壹份急速秘藥。"}},
[7484]={"專註聖典",{"將專註聖典、1塊原始黑鉆石、4份大塊魔光碎片和2張暗影之皮交給厄運之槌的博學者萊德羅斯，以換取壹份專註秘藥。"}},
[7485]={"防護聖典",{"將防護聖典、1塊原始黑鉆石、2份大塊魔光碎片和1份磨損的憎惡縫合線交給厄運之槌的博學者萊德羅斯，以換取壹份防護秘藥。"}},
[7486]={"英雄的獎賞",{"從海達克西斯的箱子拿取妳的獎勵。"}},
[7488]={"蕾瑟塔蒂絲的網",{"把蕾瑟塔蒂絲的網交給菲拉斯羽月要塞的拉托尼庫斯·月矛。"}},
[7489]={"蕾瑟塔蒂絲的網",{"把蕾瑟塔蒂絲的網交給非拉斯莫沙徹營地的塔羅·刺蹄。"}},
[7490]={"部落的勝利",{"將奧妮克希亞的頭顱交給奧格瑞瑪的薩爾。"}},
[7491]={"萬眾敬仰",{"在力量谷找到倫薩克。"}},
[7492]={"莫沙徹營地",{"和菲拉斯莫沙徹營地的塔羅·刺蹄談壹談。"}},
[7493]={"壹切才剛剛開始",nil},
[7494]={"羽月要塞",{"和菲拉斯羽月要塞的拉托尼庫斯·月矛談壹談。"}},
[7495]={"聯盟的勝利",{"將奧妮克希亞的頭顱交給暴風城的伯瓦爾·弗塔根公爵。"}},
[7496]={"英雄慶典",{"在英雄谷找到瑪丁雷少校。"}},
