[7506]={"翡翠夢境……",{"將這本典籍交給它的主人。"}},
[7507]={"弗洛爾的屠龍技術綱要",{"將《弗洛爾的屠龍技術綱要》還回圖書館。"}},
[7508]={"鑄造奎爾塞拉",{"把黯淡的精靈劍交給博學者萊德羅斯。"}},
[7509]={"鑄造奎爾塞拉",{"妳必須設法讓奧妮克希亞對這把未淬火的的上古之刃噴射火焰。完成之後，撿起加熱過的上古之刃。妳要註意的是，加熱過的上古之刃不會壹直保持被加熱的狀態，時間非常緊迫。","","在把它給我拿回來之前的最後壹步是殺掉那條龍，並將加熱過的上古之刃插入她的屍體中。","","完成這些之後，奎爾塞拉就是妳的了。"}},
[7541]={"為部落效力",nil},
[7562]={"莫蘇爾·召血者",{"與燃燒平原的莫蘇爾·召血者談壹談。"}},
[7563]={"血之狂暴",{"把30瓶狂暴野獸的血交給燃燒平原的莫蘇爾·召血者。"}},
[7564]={"戈瑟奇·邪眼",{"把血箱交給燃燒平原的戈瑟奇·邪眼。"}},
[7581]={"監牢之鏈",{"到菲拉斯的厄運之槌去，從扭木廣場的荒野薩特身上找到15份薩特之血，然後把它們交給腐爛之痕的戴奧。"}},
[7582]={"監牢之壁",{"到冬泉谷的暗語峽谷去，從盤踞在峽谷中的赫達琳惡魔身上找到5塊赫達琳之淚。完成任務之後回到腐爛之痕的戴奧那裏。"}},
[7583]={"壓制",{"在腐爛之痕中找到壹個末日守衛指揮官。","","對其使用光芒水晶監牢。妳要做好承受瘋狂攻擊的準備，那個惡魔會拼命掙紮試圖逃脫。","","如果妳成功了，就把被囚禁的末日守衛交給腐爛之痕的戴奧。"}},
[7601]={"尼比的助手",{"與費伍德森林的伊普斯談壹談。"}},
[7602]={"無暇的惡魔精華",{"費伍德的伊普斯要求妳從三個不同的地區收集三塊無暇的惡魔精華，然後把它們交給他。","","艾薩拉的雷加斯薩特、費伍德森林的加德納爾軍團士兵和詛咒之地的地獄衛士斥候分別擁有壹種無暇的惡魔精華。"}},
[7603]={"克羅蘇斯的惡魔之核",{"在費伍德森林的碎痕谷中搜尋克羅蘇斯的屍體。當妳找到屍體後，在他身上使用魔火，並等待克羅蘇斯復生。當這個地獄火被喚醒之後，幹掉他，從他的身上拿取克羅蘇斯的惡魔之核。","","把克羅蘇斯的惡魔之核交給費伍德森林的尼比。"}},
[7604]={"瑟銀兄弟會契約",{"如果妳願意接受薩弗隆的設計圖，請將瑟銀兄弟會契約交給羅克圖斯·暗契。"}},
[7621]={"警示",nil},
[7622]={"光與影的平衡",{"在總計有15個農夫被殺死之前拯救50個農夫。完成任務之後與艾瑞斯·哈文法談談。","","妳可以通過瀏覽死亡布告來了解自己拯救了多少農夫。"}},
[7623]={"魔王貝恩霍勒",{"從燃燒平原的戈瑟奇那裏購買暗影藥水。","","使用這種藥劑進入加德納爾，然後與魔王貝恩霍勒談壹談。"}},
[7624]={"背叛者烏拉泰克",{"找到並殺死烏拉泰克，然後把叛徒之心交給加德納爾的魔王貝恩霍勒。"}},
[7625]={"克索諾斯星塵",{"從烏爾丹那裏購買克索諾斯星塵，把它交給燃燒平原的戈瑟奇·邪眼。"}},
[7626]={"達斯莫拉之鈴",{"把10瓶暗影之力藥劑交給燃燒平原的戈瑟奇·邪眼。"}},
[7627]={"黑暗戰車之輪",{"把6份大塊魔光碎片和25塊黑鐵礦石交給燃燒平原的戈瑟奇·邪眼。"}},
[7628]={"末日蠟燭",{"把35塊黑龍鱗片交給燃燒平原的戈瑟奇·邪眼。"}},
[7629]={"瓶中的小鬼",{"把瓶中的小鬼帶到通靈學院的煉金實驗室中。在小鬼制造出羊皮紙之後，把瓶子還給戈瑟奇·邪眼。"}},
[7630]={"奧金錠",{"把3塊奧金錠交給燃燒平原的戈瑟奇·邪眼。"}},
[7631]={"克索諾斯恐懼戰馬",{"閱讀莫蘇爾的指南，並召喚出壹匹克索諾斯恐懼戰馬，擊敗它，然後控制它的靈魂。"}},
[7632]={"遠古石葉",{"找到遠古石葉的主人。祝妳好運，<name>。這個世界是很大的。"}},
[7633]={"介紹",nil},
[7634]={"龍筋箭袋",{"費伍德森林的古樹哈斯塔特要求妳帶回壹塊成年藍龍的肌腱。"}},
[7635]={"合適的弓弦",{"費伍德森林的古樹斯托瑪要求妳帶給他壹塊成年黑龍的肌腱。"}},
[7636]={"古樹的手杖",{"妳必須找到並幹掉下列4個惡魔：","","迷人的西蒙妮。","","瘋狂的克林弗蘭。","","S屠殺者索倫諾爾。","","摧毀者阿托留斯。","","殺掉這些惡魔，然後回到費伍德森林的古樹瓦特魯斯那裏去。","","根據妳背包中的石化樹皮來找到它們所在位置的線索。","","妳必須獨自完成這個任務。"}},
[7637]={"犧牲精神",{"到鐵爐堡去找高階牧師洛漢，從他那裏拿到驅魔香爐。妳需要捐贈150金幣來獲得它。"}},
[7638]={"格雷森·沙東布瑞克公爵",{"與暴風城教堂區的格雷森·沙東布瑞克公爵談壹談。"}},
[7639]={"聖騎士的審判",{"把驅魔香爐交給暴風城教堂區的格雷森·沙東布瑞克公爵。"}},
[7640]={"恐懼谷的靈魂",{"使用驅魔香爐召喚恐懼谷中的靈魂。當妳殺掉25個恐懼谷的靈魂之後，回到暴風城教堂區的格雷森·沙東布瑞克公爵那裏復命。"}},
[7641]={"格瑞曼德·艾爾默",{"與暴風城矮人區的格瑞曼德·艾爾默談壹談。"}},
[7642]={"收集材料",{"把40塊符文布、6塊奧金錠、10棵阿爾薩斯之淚、5瓶斯坦索姆聖水和150枚金幣交給暴風城矮人區的格瑞曼德·艾爾默。"}},
[7643]={"上古聖馬之魂",{"妳需要特殊的飼料來餵養靈魂馬。南海鎮的梅麗德絲·卡爾森可以為妳提供這樣的糧草。","","到菲拉斯的厄運之槌去，殺掉特迪斯·扭木，釋放上古聖馬之魂。用特殊的糧草餵養它，這樣可以安撫它的靈魂。最後，把奧金馬鎧交給它就可以完成祝福。"}},
[7644]={"被祝福的奧金馬鎧",{"將被祝福的奧金馬鎧交給暴風城教堂區的格雷森·沙東布瑞克公爵。"}},
[7645]={"魔法糧草",{"把制作魔法糧草所需要的重要材料：20塊可口的魔法點心帶給希爾斯布萊德丘陵的梅麗德絲·卡爾森。據說銀色黎明會出售這種餅幹。","","妳還需要給她50金幣來對她進行安撫。"}},
[7646]={"預言水晶球",{"把壹塊艾澤拉斯鉆石和壹塊原始黑鉆石交給暴風城教堂區的格雷森·沙東布瑞克公爵。"}},
[7647]={"審判和救贖",{"在通靈學院屍骨儲藏所地下室的中心使用預言水晶球。將妳要審判的靈魂引領出來。將這些靈魂擊敗然後死亡騎士達克雷爾就將被召喚出來。將其擊敗然後獲得墮落戰馬的靈魂。","","把贖罪的戰馬之魂和被祝福的奧金馬鎧壹起附在達克雷爾的墮落戰馬身上。"}},
[7648]={"艾爾默的手藝",{"把奧金馬鎧交給暴風城教堂區的格雷森·沙東布瑞克公爵。"}},
[7649]={"魔化瑟銀板甲：第壹卷",{"將這本典籍交給它的主人。"}},
[7650]={"魔化瑟銀板甲：第二卷",{"將這本典籍交給它的主人。"}},
