[7670]={"格雷森·沙東布瑞克公爵",{"與暴風城教堂區的格雷森·沙東布瑞克公爵談壹談。"}},
[7701]={"懸賞：工頭瑪托留斯",{"那個叫做工頭瑪托留斯的黑鐵矮人叛徒就藏在大熔爐的熔渣之池深處。","","殺死工頭瑪托留斯，將他的頭顱交給灼熱峽谷的偵查隊長洛洛爾以換取妳的獎勵。"}},
[7703]={"戈多克食人魔的事務",{"找到戈多克力量護手，並將它交給厄運之槌的克羅卡斯。","","根據克羅卡斯所說的，“傳說”自稱是王子的精靈托塞德林從壹名戈多克食人魔手中偷走了那件神器。"}},
[7721]={"壓縮器的動力",{"從菲拉斯被遺忘的海岸那裏的海元素和巨型海元素身上獲取10塊水元素核心，把它們交給碼頭附近的索爾賓·範達瑟。"}},
[7722]={"絕密配方！",{"在大熔爐的熔渣之池中的某個地方，妳可以找到工頭瑪托留斯偷走的秘密設計圖：熾熱助熔劑。找到這些設計圖，把它們還給灼熱峽谷的大鐵匠博恩奈特。"}},
[7723]={"該死的手指頭！",{"漢瑟爾·重拳讓妳殺掉20個重型作戰傀儡。","","重型作戰傀儡就在灼熱峽谷的大熔爐附近。當妳殺死足夠多的傀儡後，就回去找漢瑟爾·重拳。"}},
[7724]={"熔巖蜘蛛的威脅！",{"漢瑟爾·重拳要妳殺死灼熱峽谷中的20只巨型熔巖蜘蛛。妳可以在灼熱峽谷的高地和熔巖池裏找到巨型熔巖蜘蛛。","","當妳殺死足夠的巨型熔巖蜘蛛之後，回到漢瑟爾·重拳那裏復命。"}},
[7725]={"更多被縮小的巨人！",{"使用索爾賓的超級壓縮器來縮小菲拉斯的任意種類的巨人，將他們縮小到更容易控制的體積。從縮小過的巨人身上收集10份微縮殘渣，把它們交給菲拉斯被遺忘的海岸碼頭的索爾賓·範達瑟。"}},
[7726]={"補充動力",{"從菲拉斯被遺忘的海岸那裏的海元素和巨型海元素身上獲取6塊水元素核心，把它們交給碼頭附近的索爾賓·範達瑟。"}},
[7727]={"熏火龍",{"漢瑟爾·重拳讓妳去殺掉20個熏火龍。","","熏火龍侵占了熔渣之池中的那些巖漿池。熔渣之池就在灼熱峽谷的大熔爐中。","","當妳殺死足夠數量的熏火龍後，就回去找漢瑟爾·重拳。"}},
[7728]={"被盜：鼓風機和望遠鏡",{"找到冶煉鼓風機和偵查員的望遠鏡，把它們還給灼熱峽谷的監工斯克蘭格。","","妳所知道的關於這些物品的惟壹信息是：它們肯定是被黑鐵矮人偷走的。冶煉鼓風機是鐵匠用的鍛造工具，偵查員的望遠鏡是偵查員所需的偵查工具。"}},
[7729]={"工作機會：肅清競爭對手",{"殺死15個黑鐵工頭和15個黑鐵奴隸販子。完成任務之後就回去找監工斯克蘭格。"}},
[7730]={"祖卡什的入侵",{"把20塊祖卡什蟲殼交給菲拉斯莫沙徹營地的哈杜肯·迅蹄。"}},
[7731]={"毒刺鞭笞者",{"擊敗痛苦深淵中的毒刺鞭笞者，把它的腺體交給菲拉斯莫沙徹營地的哈杜肯·迅蹄。"}},
[7732]={"祖卡什報告",{"把莫沙徹營地祖卡什報告交給奧格瑞瑪暗巷區的基爾茲賓·鼓眼。"}},
[7733]={"更高的品質",{"把10塊怒痕雪人的毛皮交給菲拉斯羽月要塞的普拉特·馬克格魯比。"}},
[7734]={"更高的品質",{"把10塊怒痕雪人的毛皮交給菲拉斯莫沙徹營地的杉多爾·迅蹄。"}},
[7735]={"原始雪人毛皮",{"把原始雪人毛皮交給菲拉斯羽月要塞的普拉特·馬克格魯比。"}},
[7736]={"熾熱助熔劑的補給：皇血草",nil},
[7737]={"獲得信任",nil},
[7738]={"完美的雪人毛皮",{"把完美的雪人毛皮交給菲拉斯莫沙徹營地的杉多爾·迅蹄。"}},
[7761]={"黑手的命令",{"真是個愚蠢的獸人。看來妳需要找到那枚烙印並獲得達基薩斯徽記才可以使用命令寶珠。","","妳從信中獲知，達基薩斯將軍守衛著烙印。也許妳應該就此進行更深入的調查。"}},
[7781]={"黑石之王",{"將奈法利安的頭顱交給暴風城的伯瓦爾·弗塔根公爵。"}},
[7782]={"黑石之王",{"回到暴風城的英雄谷，與艾法希比元帥談壹談。"}},
[7783]={"黑石之王",{"將奈法利安的頭顱交給奧格瑞瑪的薩爾。"}},
[7784]={"黑石之王",{"和奧格瑞瑪的薩魯法爾大王談談。他在力量谷等妳。"}},
[7785]={"復生之瓶",{"查看復生之瓶，然後回到德米提恩那裏去。"}},
[7786]={"逐風者桑德蘭",{"如果妳想要把逐風者桑德蘭從監牢裏釋放出來，妳就必須找到左右兩塊逐風者禁錮之顱，10塊源質錠，以及火焰之王的精華，把它們交給德米提恩。"}},
[7787]={"覺醒吧，雷霆之怒！",{"把風吻之刃交給德米提恩。"}},
