[7816]={"加莫裏塔！",{"辛特蘭惡齒村的釣魚者卡圖姆要妳去殺掉加莫裏塔，並從它的屍體上找到卡圖姆的超級魚餌。","","卡圖姆說加莫裏塔和其它海龜都在海岸附近活動。"}},
