[7828]={"銀鬃捕獵者",{"辛特蘭惡齒村的獵戶馬克霍爾要求妳去殺掉15頭銀鬃捕獵者和15頭銀鬃嗥狼。完成任務之後就回到他那裏復命。","","馬克霍爾說過那些狼都躲在辛特蘭的野外。"}},
[7829]={"野蠻的梟獸",{"辛特蘭惡齒村的獵戶馬克霍爾要求妳去殺掉20頭野蠻的梟獸。完成任務之後就回到他那裏復命。","","馬克霍爾說過那些野蠻的梟獸都躲在辛特蘭的野外。"}},
[7830]={"死者的復仇",{"辛特蘭惡齒村的獵戶馬克霍爾要求妳殺掉壹頭翺翔的鋒喙獅鷲，並將它的獅鷲長羽拿回去交給他。","","馬克霍爾說過那些翺翔的鋒喙獅鷲就躲在辛特蘭的野外。"}},
