[7839]={"邪枝竊賊",{"辛特蘭惡齒村的鐵匠斯拉提要妳去找到斯拉提的工具。完成任務之後就回到他那裏去。","","妳記得鐵匠斯拉提說過，妳可以在辛特蘭東北部的某個邪枝巨魔神廟中找到它，要不然就是在隱匿石那邊。"}},
[7840]={"拉爾德的午餐",{"辛特蘭惡齒村的拉爾德要求妳去找到拉爾德的午餐。完成任務之後就回到他那裏去。","","拉爾德說他把午餐留在了北面的島上。當心邪枝巨魔。"}},
[7841]={"給蠻錘部族的警告",{"辛特蘭惡齒村的奧索·莫吉克要妳去殺掉15個高原前鋒、15個高原斥候、15個高原神射手和15個高原遊俠。任務完成之後回到他那裏去復命。","","妳可以在辛特蘭西北部的奎爾丹尼小屋找到那些高原精靈。"}},
[7842]={"又壹個給蠻錘部族的警告",{"辛特蘭惡齒村的奧索·莫吉克要妳從辛特蘭的獅鷲身上收集10根細長的獅鷲羽毛。任務完成之後回到他那裏去復命。","","在辛特蘭各處都有獅鷲出沒。"}},
[7843]={"給蠻錘部族的最後警告",{"辛特蘭惡齒村的奧索·莫吉克要妳去辛特蘭西部的鷹巢山，把給蠻錘部族的警告插在城鎮中心的水井旁邊。任務完成之後回到他那裏去復命。","","當心那些憤怒的蠻錘矮人以及野蠻的聯盟成員。"}},
[7844]={"野蠻的親戚",{"辛特蘭惡齒村的秘法師雅爾金要妳去殺掉30個邪枝割顱者和15個邪枝占蔔者。任務完成之後回到他那裏去復命。","","秘法師雅爾金說過，妳可以在辛特蘭東北部的沙爾瓦薩和亞戈瓦薩神廟附近找到那些巨魔。"}},
[7845]={"被綁架的斷齒長者！",{"辛特蘭惡齒村的斷齒族長要求妳到辛薩羅去拯救她的愛人，斷齒長者。","","妳聽說他被關在辛薩羅頂部，辛薩羅位於辛特蘭的南部地區，那裏是邪枝巨魔的主城。"}},
[7846]={"找回鑰匙！",{"辛薩羅的斷齒長者要求妳殺掉守護者希坦亞，並用她身上的鐐銬鑰匙打開他的鐐銬。當妳找到鑰匙之後就回到他那裏去。"}},
[7847]={"向斷齒族長復命",{"辛薩羅的斷齒長者要求妳將他已經被營救的消息帶給惡齒村的斷齒族長。"}},
[7848]={"熔火之心的傳送門",{"進入黑石深淵，在通往熔火之心的傳送門附近找到壹塊熔火碎片，然後回到黑石山脈的洛索斯·天痕那裏。"}},
[7849]={"分離的痛苦",{"辛特蘭惡齒村的獵戶馬克霍爾要妳去找回他的雙胞胎兄弟的屍體。找到它，然後把獵戶莫克霍爾的頭顱和獵戶莫克霍爾的骨頭交給獵戶馬克霍爾。","","馬克霍爾說過，他兄弟的屍體被軟泥怪和邪枝巨魔的狼群分食。他還提到在辛薩羅有個大坑，裏面全都是軟泥怪，那裏還有個狼穴。這兩個地方都在靠近辛薩羅神廟頂部的區域。"}},
[7850]={"黑暗之瓶",{"辛特蘭惡齒村的斷齒族長要妳在辛薩羅找到10瓶腐化之血。任務完成之後就回到斷齒族長那裏。"}},
[7861]={"通緝：邪惡祭司海克斯和她的爪牙",{"妳必須殺掉邪惡祭司海克斯和20名邪枝精英守衛。任務完成之後回到辛特蘭的惡齒村，向斷齒族長報告。","","妳可以在辛特蘭的邪枝巨魔城市辛薩羅的頂部找到他們。"}},
[7862]={"職位空缺：惡齒村衛兵隊長",{"妳必須消滅20個邪枝狂戰士、20個邪枝暗影獵手、20個邪枝飲血者和20個邪枝噬魂者。","","完成任務之後向辛特蘭惡齒村的斷齒族長復命。"}},
