[8278]={"諾格的最後壹線希望",{"希利蘇斯塞納裏奧要塞的比提克斯·斯巴格要求妳給他帶去3個石鞭巨鉗蠍之刺、3個石鞭掠奪者之刺和3個石行蜘蛛的牙齒。"}},
