[8286]={"明天的希望",{"前往塔納利斯的時光之穴尋找諾茲多姆的子嗣，阿納克洛斯。","","完成任務後回到希利蘇斯塞納裏奧要塞的流沙守望者巴裏斯托爾斯那兒。"}},
[8287]={"擺脫困境",{"把解密石板碑文交給指揮官瑪爾利斯。"}},
[8288]={"唯壹的領袖",{"到黑石山中的奈法利安巢穴去，殺死勒什雷爾，並帶回它的徽記。","","將勒什雷爾的徽記交給希利蘇斯塞納裏奧要塞的流沙守望者巴裏斯托爾斯。"}},
[8301]={"正義之路",{"希利蘇斯塞納裏奧要塞的流沙守望者巴裏斯托爾斯想要妳殺死亞什蟲巢、佐拉蟲巢和雷戈蟲巢中的異種蟲類。從死去的蟲子屍體上收集異種蠍殼碎片。當妳收集到200塊異種蠍殼碎片時，回到巴裏斯托爾斯那兒去。","","作為壹名諾茲多姆的特使，只有妳和妳的副官可以從異種蟲類的屍體上拾取異種蠍殼碎片。請註意保持妳的包裹空間足夠多。"}},
[8302]={"正義之手",{"為流沙守望者巴里斯托爾斯收集200塊異種蠍殼碎片。"}},
[8303]={"阿納克洛斯",{"到塔納利斯的時光之穴去尋找阿納克洛斯。"}},
[8304]={"親愛的納塔莉亞",{"希利蘇斯塞納裏奧要塞的指揮官瑪爾利斯想要妳詢問銅須營地的矮人。妳可以在塞納裏奧要塞以南找到銅須營地。","","壹旦妳收集到有用的信息，就回到指揮官瑪爾利斯那兒。"}},
[8305]={"久遠的記憶",{"希利蘇斯時光之穴的阿納克洛斯想要妳前往位於希利蘇斯南部沙漠的甲蟲之臺。","","當妳學習完畢後再回到他那兒去。"}},
[8306]={"深入瘋狂之口",{"希利蘇斯塞納裏奧要塞的指揮官瑪爾利斯想要妳找到他心愛的納塔莉亞。妳收集到的信息表明納塔莉亞·瑪爾利斯可能在南面的雷戈蟲巢。","","在妳趕往蟲巢之前，記得去銅須營地拜訪壹下那兒的矮人，他們或許會給妳提些建議。","","<name>，記住指揮官的話：做妳應該做的……"}},
[8307]={"沙漠食譜",{"前往塞納裏奧要塞以西的暮光之錘營地，調查沙蟲的烹飪方法。"}},
[8308]={"布萊恩·銅須的信",{"將布萊恩·銅須的信件帶往希利蘇斯南部的銅須營地。"}},
[8309]={"追查雕文",{"希利蘇斯銅須營地的魯特加爾·雕石想要妳前往亞什蟲巢、佐拉蟲巢和雷戈蟲巢，從蟲巢中的雕文水晶上取下拓文。","","使用地質學家的抄錄工具包獲取古老雕文的摹本。完成任務後回到魯特加爾·雕石那兒。"}},
[8310]={"破譯密碼",{"希利蘇斯銅須營地的弗蘭卡·石橋想讓妳取回壹個亞什異種蟲腦、壹個佐拉異種蟲腦和壹個雷戈異種蟲腦。完成任務後回到弗蘭卡那兒。"}},
[8313]={"分享知識",{"將破碎的食譜交給塞納裏奧要塞旅店中的卡蘭德拉斯。"}},
[8314]={"揭開秘密",{"銅須營地的魯特加爾·雕石想讓妳將雕文水晶棱柱交給希利蘇斯塞納裏奧要塞的地質學家拉克斯班。"}},
[8315]={"召喚",{"希利蘇斯塞納裏奧要塞的地質學家拉克斯班想讓妳從其拉蟲人使者那裏取回水晶分解裝置。","","妳已經奉命將召喚雕文帶往塞納裏奧要塞以南的格拉卡洛之骨處，將它們從沙中引出。壹旦其拉蟲人使者露面，就殺死它，獲得水晶分解裝置。成功之後回到地質學家拉克斯班那兒去。","","妳必須召集壹支強大的軍隊來完成這項任務，<name>！"}},
