[8497]={"沙漠生存包",{"把4份純水之球、4份特效抗毒藥劑和4份沙漠肉丸子交給希利蘇斯塞納裏奧要塞的卡蘭德拉斯。妳還必須隨身帶著後勤任務簡報 I才能完成這個任務。"}},
