[8507]={"戰地任務",{"向佐拉蟲巢外的鐵爐堡軍團報到，從布萊卡維爾上尉那裏拿到簽過字的戰地任務文件，把它交給希利蘇斯塞納裏奧要塞的喚風者卡爾東。","","註意：給鐵爐堡軍團的士兵治療或者施放增益法術會打開妳的PvP標誌。"}},
