[8994]={"最後的準備",{"收集40個黑石護腕和1份超級能量精鍊藥劑。把它們帶給黑石山上的布德利。"}},
[8995]={"認錯，瓦薩拉克領主",{"用召喚火盆召喚出瓦薩拉克領主。殺了他，在他的屍體上使用瓦薩拉克的護符。然後，將瓦薩拉克領主護符還給瓦薩拉克領主之靈。"}},
[8996]={"回到布德利那裡",{"回到黑石山的布德利那裡並將召喚火盆交給他。"}},
