[9015]={"挑戰",{"前往黑石深淵競技場並在你被裁決者格里斯通宣判時將挑釁旌旗放在它的中央。殺死瑟爾倫和他的戰士們，再帶著第一塊瓦薩拉克領主護符回到東瘟疫之地的安希恩·哈莫那裡。"}},
[9018]={"安希恩的離別感言",{"帶著博學者長靴，博學者護腿和博學者披肩回到奧格瑪的莫克瓦那裡。"}},
