[9033]={"戰爭的回響",{"東瘟疫之地聖光之願禮拜堂的指揮官埃裏戈爾·黎明使者要妳殺死5個畸形妖、5只巖膚石像鬼、8個死亡騎士隊長和3只毒性捕獵者。"}},
