[9229]={"拉瑪蘭迪的命運",{"進入納克薩瑪斯的宮殿，找到拉瑪蘭迪的下落。"}},
[9230]={"拉瑪蘭迪的寒冰之握",{"東瘟疫之地聖光之願禮拜堂的科爾法克斯要1個冰凍符文、1塊藍寶石和1塊奧金錠。"}},
[9232]={"我只會唱這壹首歌……",{"將2個冰凍符文、2個水之精華、2塊藍寶石和30金幣交給東瘟疫之地聖光之願禮拜堂的工匠威爾海姆。"}},
[9233]={"奧瑪裏恩的手冊",{"將奧瑪裏恩的手冊交給東瘟疫之地聖光之願禮拜堂的工匠威爾海姆。"}},
[9234]={"冰剋護手",{"東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他5個冰凍符文，12個瑟銀錠，2個奧金錠，2個水之精華，還有200金。"}},
[9235]={"冰剋護腕",{"東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他4個冰凍符文，12個瑟銀錠，2個奧金錠，2個水之精華，還有200金。"}},
[9236]={"冰剋胸甲",{"東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他8個冰凍符文，16個瑟銀錠，2個奧金錠，4個水之精華，還有300金。同時你必須在銀色黎明達到崇拜聲望值，才能完成這項任務。"}},
[9237]={"冰川披風",{"東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他5個冰凍符文，4份符文布卷，2個水之精華，4份鐵網蛛絲，還有200金。同時你必須在銀色黎明達到崇拜聲望值，才能完成這項任務。"}},
[9238]={"冰川腕帶",{"東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他4個冰凍符文，2份符文布卷，2個水之精華，2份鐵網蛛絲，還有200金。"}},
[9239]={"冰川手套",{"東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要5個冰凍符文，4份符文布卷，4個水之精華，2份鐵網蛛絲，還有200金。"}},
[9240]={"冰川外衣",{"東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他8個冰凍符文，8份符文布卷，6個水之精華，4份鐵網蛛絲，還有300金。同時你必須在銀色黎明達到崇拜聲望值，才能完成這項任務。"}},
[9241]={"極地護腕",{"東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他4個冰凍符文，12塊附魔皮，3個水之精華，3塊熟化毛皮，還有200金。"}},
[9242]={"極地手套",{"東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他5個冰凍符文，12塊附魔皮，3個水之精華，3塊熟化毛皮，還有200金。"}},
[9243]={"極地外套",{"東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他8個冰凍符文，16塊附魔皮，5個水之精華，5塊熟化毛皮，還有300金。同時你必須在銀色黎明達到崇拜聲望值，才能完成這項任務。"}},
[9244]={"冰鱗護腕",{"東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他4個冰凍符文，16個厚蠍鱗，5個水之精華，3塊熟化毛皮，還有200金。"}},
[9245]={"冰鱗護手",{"東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他5個冰凍符文，16個厚蠍鱗，5個水之精華 ，3塊熟化毛皮，還有200金。"}},
[9246]={"冰鱗胸甲",{"東瘟疫之地聖光之願禮拜堂的工匠維爾海姆需要你帶給他8個冰凍符文，24個厚蠍鱗，7個水之精華 ，5塊熟化毛皮，還有300金。同時你必須在銀色黎明達到崇拜聲望值，才能完成這項任務。"}},
[9248]={"謙卑的饋贈",{"將壹根深淵節杖交給希利蘇斯塞納裏奧要塞的奧蕾爾·金葉。妳在塞納裏奧議會的聲望必須達到尊敬。"}},
[9250]={"埃提耶什之杖",{"看看有誰能幫妳找到法杖的最後兩個部分，並且凈化邪惡的力量。"}},
[9251]={"埃提耶什，被玷汙的傳說之杖",{"塔納利斯時光之穴的阿納克洛斯要妳找到埃提耶什的法杖頂部和埃提耶什的杖柄末端。"}},
[9257]={"阿泰絲,守護者之杖",{"塔納利斯時光之穴的安納克羅斯要你帶著阿泰絲,守護者之杖前往斯坦索姆，在聖化之地上使用它。擊敗從法杖內被驅除的生物再回去找他。"}},
