[9272]={"適宜的服裝",nil},
[9338]={"塞納裏奧議會的盟友",nil},
[9362]={"軍閥克雷利安",{"為大法師克希雷姆奪回虹彩貝殼。大法師克希雷姆就居住在艾薩拉北部懸崖上的壹座塔中。"}},
[9364]={"魔法的碎片",{"對艾薩拉的惡鞭納迦使用變形術，然後殺死幾秒鐘後出現的相似體。當妳殺了50個相似體後，回去向大法師克希雷姆復命。"}},
[9415]={"向布魯沃爾元帥報告",{"與佐拉蟲巢附近聯盟營地的布魯沃爾元帥談壹談。"}},
[9416]={"向吉裏卡將軍報到",{"與雷戈蟲巢附近部落營地的吉裏卡將軍談壹談。"}},
[9419]={"橫掃沙漠",{"找到壹份水晶塵，將其送到水晶塵萃取器那裏，然後向佐拉蟲巢外聯盟營地的布魯沃爾元帥復命。"}},
[9422]={"橫掃沙漠",{"找到壹份水晶塵，將其送到水晶塵萃取器那裏，然後向雷戈蟲巢外部落營地的吉裏卡將軍復命。"}},
[9664]={"建立新據點",{"奪取東瘟疫之地的皇冠哨塔、東墻哨塔、北地哨塔和病木林哨塔，然後向聖光之願禮拜堂的白須大使復命。"}},
[9665]={"加強防禦",{"奪取東瘟疫之地的皇冠哨塔、東墻哨塔、北地哨塔和病木林哨塔，然後向聖光之願禮拜堂的高莫克大使復命。"}},
[65593]={"戀人的心臟",{"把艾芙琳娜‧莉蕾和艾薩克‧佩爾森的心臟交給詛咒神殿的凱倫丁。"}},
[65597]={"誓縛",{"使用這對戀人的心臟，把夢魔召喚出來然後加以制伏，再把戀人的心臟送去給幽暗城魔法區的凱倫丁·哈加爾。"}},
[65601]={"痛心的愛",{"和奧格瑪的瑪加爾交談。"}},
[65602]={"愛為何物?",{"取回木雕刻像，然後交給暴風城法師區的『黑暗縛靈師』加金。"}},
[65603]={"誓縛",{"使用木雕刻像來召喚夢魔並加以制伏，然後將木雕刻像還給已宰的羔羊旅店的『黑暗縛靈師』加金。"}},
[65604]={"誓縛",{"使用乾癟的圍巾來召喚夢魔，然後加以制伏，再把乾癟的圍巾交給奧格瑪的甘盧爾·血眼。"}},
[65610]={"真希望你也在這裡",{"調查梣谷的墜星湖，然後向奧格瑪的甘盧爾·血眼回報。"}},
}]=])())
