MUI_EncounterJournalDB:Localize(loadstring([=[return {
instances={[226]={name="怒焰裂谷",desc="怒焰裂谷延伸在奧格瑪的地底深處。野蠻的穴居怪與奸險的灼刃信徒們曾一度盤據在這火山洞窟內，但現在有一個新的威脅浮現了：黑暗薩滿。雖然大酋長卡爾洛斯‧地獄吼最近號召了一些薩滿來運用元素為武器對抗聯盟，但目前裂谷內的居民似乎是一群叛徒。已經有報告指出這些難以捉摸的人們正在聚集一支強大的軍隊，足以對奧格瑪造成極嚴重的破壞。"},[240]={name="哀嚎洞穴",desc="數年前，知名的德魯伊納拉雷克斯與他的跟隨者們進入了幽暗的哀嚎洞穴。這個洞穴的名字源自於蒸氣穿過洞穴中裂隙時所發出，類似悲傷哀嚎的聲音。納拉雷克斯原本計畫利用地下的泉水使不毛的貧瘠之地恢復生氣，但就在他進入翡翠夢境時，他的夢想轉變成一場夢魘，從那時開始就一直困擾著哀嚎洞穴。"},[63]={name="死亡礦坑",desc="據說死亡礦坑的黃金礦藏曾使暴風城積聚的財富增加三分之一。在第一次獸人戰爭之中，礦坑遭到廢棄，還曾經冒出鬧鬼的傳說，導致該處一直荒廢。直到近來，才有一群落草為寇的勞動群眾組成迪菲亞兄弟會，前來佔據這座迷宮，作為他們對暴風城展開破壞行動的根據地。"},[64]={name="影牙城堡",desc="影牙城堡位於銀松森林南部的懸崖之上，遠眺焚木村，遮蔽出一片與其歷史同樣黑暗的陰影。各種兇惡勢力佔據這片廢墟，先前是被隸屬瘋狂大法師阿魯高的狼人所佔據，現在席瓦萊恩男爵受詛咒的靈魂依然迴盪在堡壘之內，而高佛雷領主和他那些昔日貴族的叛黨也在城堡內計畫著同時對付生者和不死生物的陰謀。"},[227]={name="黑澗深淵",desc="黑澗深淵曾經是奉獻給夜精靈女神伊露恩的聖地，人們都以為它在大崩裂中被摧毀、消失在海洋之下。數千年後，暮光之錘的教徒被傳聞與邪惡的夢想吸引來到了這個神殿。在獻祭了難以計數的無辜生命後，這些教徒被賦予了一項新任務：保護上古之神最珍愛的生物之一，一隻在能對世界展現黑暗力量之前仍需要受到照顧與培育的上古之神寵物。"},[231]={name="諾姆瑞根",desc="諾姆瑞根這座建築在丹莫洛山脈深處的奇妙城市，是地精智慧與工業結晶的最好證明。但在首都被穴居怪入侵時，地精大工匠被他的顧問希科‧瑟瑪普拉格所背叛。結果造成諾姆瑞根被輻射線污染，大部分的居民被殺死。存活下來的地精們逃了出來，並誓言有一天要回來將他們的家園奪回來。"},[238]={name="監獄",desc="暴風城監獄是個建造在暴風城運河下，被緊密看守著的監牢。典獄官塞爾沃特負責監督監獄與其中極度危險的囚犯們。就在最近囚犯們展開了暴動，打倒了守衛並使監牢陷入如地獄般的狀態。"},[234]={name="剃刀沼澤",desc="傳說中半神阿迦瑪甘死去的地方長滿荊棘藤蔓。許多野豬人定居在遍地荊棘的剃刀之地，並將此地視為阿迦瑪甘的安息之地。"},[316]={name="血色修道院",desc="血色十字軍狂熱的領導者們在修道院中心的血色大教堂發號施令，帶領著他們的跟隨者們。這個被嚴密防守的地點是血色十字軍的總部，而一些最狂熱且偏執的十字軍成員都待在這個一度極為神聖的地方。"},[239]={name="奧達曼",desc="奧達曼是個被埋在地下深處的古老泰坦寶庫。據說泰坦將一個失敗的實驗封存在那裡後，就轉而進行另一個和矮人創生有關的新計畫。隱藏有偉大知識寶藏的故事誘使許多尋寶者進入奧達曼挖掘，但這座失落城市中的石頭守衛、野蠻的穴巨怪、黑鐵入侵者與其他潛伏的危險讓這項工作格外危險。"},[233]={name="剃刀高地",desc="傳說中半神阿迦瑪甘死去的地方長滿荊棘藤蔓。最近的偵察報告指出，有不死生物在該地出沒。這令人害怕，或許恐怖的天譴軍團即將襲捲整個卡林多。"},[232]={name="瑪拉頓",desc="根據傳說，塞納留斯之子札爾塔與土元素瑟萊德絲公主生下了野蠻的半人馬族。在半人馬誕生不久之後，那些殘忍的生物謀殺了自己的父親。據說哀傷不堪的瑟萊德絲將她愛人的靈魂困在瑪拉頓之內，使整個區域受到腐化。如今，兇惡的半人馬鬼魂與扭曲的元素爪牙遍布這錯綜複雜洞穴的每一個角落。"},[241]={name="祖爾法拉克",desc="祖爾法拉克曾經是塔納利斯閃亮的珍寶，它被狡詐的沙怒部族所嚴守著。儘管食人妖擁有無比韌性，許久以來這群與世隔絕的人們仍被迫放棄其許多領地。如今祖爾法拉克的居民似乎正在創造一支恐怖得不死食人妖大軍，準備要征服附近地區。除此之外還有一個令人不安的傳言指出，在城市中沉睡著一個古老的生物，一但讓他甦醒，會為整個塔納利斯帶來無數死亡與破壞。"},[246]={name="通靈學院",desc="所有尋求專精不死力量的人都熟知通靈學院，這是位於凱爾達隆底下黑暗地穴的一個惡名遠播的死靈法術學校。近年來有數名講師的變動，但這個學校仍在黑暗院長加丁的掌控之下。他是一個特別殘酷成性且陰險的死靈法師。"},[228]={name="黑石深淵",desc="熾熱的黑石深淵是黑鐵矮人與其大帝達格蘭‧索瑞森的居住地。就像他的前任者一樣，他是『炎魔』拉格納羅斯鐵腕統治之下的奴僕。殘酷的拉格納羅斯是在幾世紀以前被召喚到這個世界來，混沌元素的出現吸引暮光之錘邪教徒到來。他們和拉格納羅斯的僕從一起將矮人們推向了毀滅之途，不久之後整個艾澤拉斯可能也難逃此劫。"},[237]={name="阿塔哈卡神廟",desc="數千年以前，古拉巴什帝國因為一群被稱為阿塔萊的強大祭司而陷入一場內戰，他們想將血神哈卡奪魂者的化身召喚到艾澤拉斯。古拉巴什的人們將阿塔萊流放到悲傷沼澤，而他們在那裡建造了阿塔哈卡神廟。綠龍軍團的守護巨龍伊瑟拉將神廟沉入了沼澤之中，並指派了看守者確保永遠不會有人再度進行召喚的儀式。"},[229]={name="黑石塔下層",desc="這是座被建構在黑石山熾烈的核心中，幾世紀以來代表著黑石部族力量的莊嚴堡壘。在最近，黑龍奈法利安和他的爪牙奪下了堡壘的上層尖塔，並和矮人點燃了戰火。龍族軍隊從那時起就與大酋長雷德‧黑手的虛假部落結成了同盟。這股勢力雄踞著尖塔，進行著恐怖的實驗以強化他們的軍力，並謀劃著要消滅愛管閒事的黑鐵矮人們。"},[230]={name="厄運之槌 - 中心花園",desc="這座在數千年前建造完成，被用來存放卡多雷秘法奧秘的偉大埃德薩拉斯城市如今只剩下一堆廢墟，其中充滿著扭曲變形的力量。曾經為了爭奪控制厄運之槌腐化力量的集團之間現在訂下了不安定的休戰協議，不再想繼續戰鬥奪下整個厄運之槌，而只想能好好利用自己領地內的力量。"},[1276]={name="厄運之槌 - 扭木廣場",desc="這座在數千年前建造完成，被用來存放卡多雷秘法奧秘的偉大埃德薩拉斯城市如今只剩下一堆廢墟，其中充滿著扭曲變形的力量。曾經為了爭奪控制厄運之槌腐化力量的集團之間現在訂下了不安定的休戰協議，不再想繼續戰鬥奪下整個厄運之槌，而只想能好好利用自己領地內的力量。"},[236]={name="斯坦索姆 - 主門",desc="斯坦索姆曾經是北部羅德隆的一枚珠寶，但今天人們只記得它悲慘的壞滅過程。阿薩斯王子就是在此地背棄崇高的聖騎士烏瑟‧光明使者，並屠殺了無數被認為染有不死瘟疫的居民。從那時開始，被詛咒的斯坦索姆就被死亡、背叛與絕望所玷污。"},[1277]={name="厄運之槌 - 戈多克平民區",desc="這座在數千年前建造完成，被用來存放卡多雷秘法奧秘的偉大埃德薩拉斯城市如今只剩下一堆廢墟，其中充滿著扭曲變形的力量。曾經為了爭奪控制厄運之槌腐化力量的集團之間現在訂下了不安定的休戰協議，不再想繼續戰鬥奪下整個厄運之槌，而只想能好好利用自己領地內的力量。"},[1292]={name="斯坦索姆 - 僕從入口",desc="斯坦索姆曾經是北部羅德隆的一枚珠寶，但今天人們只記得它悲慘的壞滅過程。阿薩斯王子就是在此地背棄崇高的聖騎士烏瑟‧光明使者，並屠殺了無數被認為染有不死瘟疫的居民。從那時開始，被詛咒的斯坦索姆就被死亡、背叛與絕望所玷污。"},[741]={name="熔火之心",desc="熔火之心位於黑石深淵的最底層。這裡是黑石山的心臟，也正是很久以前索瑞森大帝為了扭轉矮人內戰的頹勢，孤注一擲地將元素炎魔拉格納羅斯召喚到這個世界的地點。雖然炎魔無法遠離熾熱的核心，但據信他的元素爪牙正指揮著黑鐵矮人，而黑鐵矮人正以活化的岩石打造軍隊。拉格納羅斯沉睡的燃燒之湖就像一道通往火焰位面的裂隙，讓邪惡的元素生物得以穿越。拉格納羅斯的手下以管理者埃克索圖斯為首，因為這個狡猾的元素生物是唯一能將炎魔從沉睡中喚醒的人。"},[760]={name="奧妮克希亞的巢穴",desc="奧妮克希亞是強大的巨龍死亡之翼的女兒，也是心機深沉的黑石塔之王奈法利安的妹妹。據說奧妮克希亞以干涉凡人種族的政治事務、使他們墮落為樂。為此，人們相信她會化身為各種人形，以她的魅力與力量影響各種族之間的微妙事務。有些人甚至相信，奧妮克希亞冒用了她父親曾經使用過的化名——普瑞斯托皇族的頭銜。在沒有插手凡人事務的時候，奧妮克希亞便居住在黑龍谷下方的一處火焰洞穴中，黑龍谷是塵泥沼澤裡的一片陰森沼澤。她在那裡受到同族——陰險的黑龍軍團殘存成員——的守護。"},[742]={name="黑翼之巢",desc="黑翼之巢位於黑石塔的最高處。奈法利安就在山峰幽暗的深處展開他計畫的最後階段，打算一舉消滅拉格納羅斯，並率領他的大軍取得凌駕艾澤拉斯所有種族的絕對霸權。"},[76]={name="祖爾格拉布",desc="祖爾格拉布曾是古拉巴什叢林食人妖的首都，這支部族一度掌控了巨大的南部叢林。就是在這裡，『妖術師』金度將兇殘的奪魂者哈卡召喚進艾澤拉斯。最近，一個由渴望建立食人妖統一帝國的古拉巴什和贊達拉食人妖所結成的聯盟重新開始了這項行動。"},[743]={name="安其拉廢墟",desc="在流沙之戰的最後時刻，夜精靈與四大龍族軍團的聯軍將戰火推進到其拉帝國的核心——要塞城市安其拉。然而，卡林多的大軍在城門前遭遇了前所未見、數量更為龐大的異種蠍戰爭工蜂。最終，異種蠍與牠們的其拉主人並未被擊敗，只是被囚禁在一道魔法屏障之內，而這場戰爭也讓這座受詛咒的城市化為廢墟。自那天起已過了一千年，但其拉的軍隊並未閒著。一支可怕的新大軍已從蟲巢中孵化而出，安其拉的廢墟再次擠滿了成群的異種蠍與其拉蟲人。這股威脅必須剷除，否則整個艾澤拉斯都可能淪陷於其拉新大軍的恐怖力量之下。"},[744]={name="安其拉神廟",desc="安其拉的中心是一座古老的神廟建築群。這座神廟建於有史以前，它既是不可名狀之神的紀念碑，也是其拉大軍的巨大繁殖場。自從一千年前流沙之戰結束以來，其拉帝國的雙子帝王便被困在他們的神廟之中，勉強被青銅龍安納克羅斯與夜精靈豎立的魔法屏障所封鎖。如今流沙權杖已經重新組合，封印也已被打破，通往安其拉內殿的道路已然開啟。在蟲巢中蠕動的瘋狂之外，在安其拉神廟的地底下，大批其拉軍團正準備發動入侵。必須不惜一切代價阻止他們，以免他們再次對卡林多釋放貪婪的蟲族大軍，引發第二次流沙之戰！"},[754]={name="納克薩瑪斯",desc="名為納克薩瑪斯的大墓地漂浮在瘟疫之地上空，是巫妖王麾下最強大的軍官之一——令人畏懼的巫妖科爾蘇加德——的大本營。隨著巫妖王的僕從準備發動攻勢，過去的恐怖與尚未釋放的新威脅正在大墓地內聚集。天譴軍團很快就會再次進軍……"}},
encounters={[11517]={name="奧格弗林特",creatures={[1]="奧格弗林特"}},[11520]={name="『飢餓者』塔拉加曼",creatures={[1]="『飢餓者』塔拉加曼"}},[11518]={name="『塑能師』耶戈什",creatures={[1]="『塑能師』耶戈什"}},[11519]={name="巴札蘭",creatures={[1]="巴札蘭"}},[3671]={name="安娜科德拉女士",desc="紅葉是最先加入納拉雷克斯自己任命前往貧瘠之地任務的自願者。在她主人的夢魘粉碎她的心智後，這個年輕的學徒捨棄了她的名字，如今她期盼展望著艾澤拉斯能擁有一個充滿著邪惡爬蟲生物的未來。",creatures={[1]="安娜科德拉女士"}},[3670]={name="皮薩斯領主",desc="戰士艾林是納拉雷克斯童年的朋友，他在學習德魯伊之道上進步的非常快速。縱使他經過了訓練，他仍無法抵禦腐化讓他失去理智。艾林改名為皮薩斯，並結合他驚人的近戰與德魯伊的技巧來消滅敵人。",creatures={[1]="皮薩斯領主"}},[3669]={name="考布萊恩領主",desc="賈拉克斯拉操縱動物形態的技巧為他在塞納里奧議會的德魯伊之中博得名聲。然而哀嚎洞穴的腐敗扭曲了他獨特的能力。如今賈拉克斯拉讓致命的毒蛇形態達到完美境界，並將自己改名為考布萊恩，以代表他邪惡的新力量。",creatures={[1]="考布萊恩領主"}},[3653]={name="克雷什",desc="這隻巨龜是哀嚎洞穴一個古老的居民，他遊蕩在地下的洞穴中，其強韌的心智不受納拉雷克斯無情的夢魘所影響。千萬別被他溫和的性情所矇騙;克雷什曾經擊退許多想要搶奪他巨大甲殼的探險者。",creatures={[1]="克雷什"}},[3674]={name="斯卡姆",desc="斯卡姆起初是為了逃離貧瘠之地危險的環境而來到哀嚎洞穴。就像洞穴中許多其他居民一般，他很快地就屈服於腐敗之下。如今黑暗能量在他體內脈動著，並將他變形成一頭已無法被拯救，但強大且冷酷的野獸。",creatures={[1]="斯卡姆"}},[3673]={name="瑟芬迪斯領主",desc="尖牙德魯伊的領袖曾經是納拉雷克斯最棒的學生。他悲劇般的墮落起源於他想成為和納拉雷克斯一樣的尊師，或「被崇敬的導師」的渴望。隨著瘋狂在他心中扎根，瑟芬迪斯將他的同伴們聚集到他身邊，並組成了尖牙德魯伊。",creatures={[1]="瑟芬迪斯領主"}},[5775]={name="永生的沃爾丹",desc="有關此生物在納拉雷克斯來到哀嚎洞穴之前的事少為人知。一般認為它是洞穴原始的守護者，永生的沃爾丹也無法逃避使它家園墮落的腐敗。沃爾丹和瘋狂的德魯伊們結盟，並維持著對闖入它領域之人的高度警戒。",creatures={[1]="永生的沃爾丹"}},[3654]={name="『吞噬者』穆坦努斯",desc="從納拉雷克斯被扭曲心智最黑暗的角落，污染翡翠夢境的腐敗以德魯伊最恐怖的敵人:魚人的形態具現化。這個被稱為穆坦努斯的畸形怪物來到了清醒中的世界，吞食任何想要將納拉雷克斯從夢魘掌握中解放之人。",creatures={[1]="『吞噬者』穆坦努斯"}},[644]={name="拉克佐",desc="身為迪菲亞兄弟會在死亡礦坑的首席工頭，拉克佐負責監督和「激勵」工人。他的做法十分前衛，也非常有效。",creatures={[1]="拉克佐"}},[643]={name="斯尼德",desc="斯尼德因其高超的效率而被雇為伐木大師。他的目標很簡單：用最便宜的價格建造重型船艦。利用伐木機，他創造了令人望塵莫及的產能，並以驚人的速度交出成果。",creatures={[1]="斯尼德"}},[1763]={name="吉尼德",desc="在迪菲亞兄弟會中，吉尼德擔任專業工程師和首席冶煉工。他負責確保重型船艦上裝載著足夠的火砲和彈藥，而且在完成工作之前，絕不會休息。",creatures={[1]="吉尼德"}},[646]={name="重拳先生",desc="身為綠皮船長的大副，重拳的任務是讓船員保持警覺。重拳是個高明的武器大師，受過各式各樣的訓練，像是斬切、毆打，以及偶爾的穿透射擊。",creatures={[1]="重拳先生"}},[647]={name="綠皮船長",desc="綠皮是建造中的重型船艦的船長，他來自藏寶海灣，原先帶領著一支海盜船艦隊。",creatures={[1]="綠皮船長"}},[639]={name="艾德溫‧范克里夫",desc="范克里夫原先是石匠公會的會長，因為與貴族發生糾紛而離開暴風城，並成立了迪菲亞兄弟會。范克里夫隨即佔領死亡礦坑作為行動基地，開始建造重型船艦，準備展開他的報復。",creatures={[1]="艾德溫‧范克里夫"}},[645]={name="餅乾",desc="除了艾德溫‧范克里夫，沒人知道餅乾是如何或為何被推選為船上的大廚。不過，對於海盜來說，有得吃就好了。",creatures={[1]="餅乾"}},[3914]={name="雷希戈爾",creatures={[1]="雷希戈爾"}},[3886]={name="屠夫拉佐克勞",creatures={[1]="屠夫拉佐克勞"}},[3887]={name="席瓦萊恩男爵",creatures={[1]="席瓦萊恩男爵"}},[4278]={name="指揮官斯普林瓦爾",creatures={[1]="指揮官斯普林瓦爾"}},[4279]={name="『盲眼守衛』奧杜",creatures={[1]="『盲眼守衛』奧杜"}},[4274]={name="『吞噬者』芬魯斯",creatures={[1]="『吞噬者』芬魯斯"}},[3927]={name="狼王南杜斯",creatures={[1]="狼王南杜斯"}},[4275]={name="大法師阿魯高",creatures={[1]="大法師阿魯高"}},[4887]={name="加摩拉",creatures={[1]="加摩拉"}},[4831]={name="薩利維絲女士",creatures={[1]="薩利維絲女士"}},[6243]={name="格里哈斯特",creatures={[1]="格里哈斯特"}},[4832]={name="暮光領主克爾里斯",creatures={[1]="暮光領主克爾里斯"}},[4830]={name="瑟拉吉斯",creatures={[1]="瑟拉吉斯"}},[4829]={name="阿庫麥爾",creatures={[1]="阿庫麥爾"}},[7361]={name="格魯比斯",desc="氾濫在城市之中的放射性氣體被用來激怒穴居怪與殺死地精，瑟瑪普拉格的計畫不只殘忍而且有效。然而有一個穴居怪對放射性物質產生了奇怪的反應:格魯比斯不斷地成長。這是一個希科始料未及的副作用，但他並不是一個會浪費珍貴（與危險）資源的人。這個巨大的穴居怪如今在諾姆瑞根的隧道中巡邏著。他忠實的蜥蜴寵物咀嚼者幫助格魯比斯聞出哪裡有氣體外洩、好吃的真菌與更好吃的入侵者。",creatures={[1]="格魯比斯"}},[7079]={name="黏性輻射塵",desc="諾姆瑞根複雜的水道以前堅固且高雅，如今卻變得一團糟，充滿著放射線與劇毒的軟泥。一個原本居住在地精地下蓄水層的孤單水元素生物被困在污染之中，它純淨的形體受到污染所腐化。如今它憤怒且痛苦地遊蕩在諾姆瑞根中，可說是瑟瑪普拉格背叛的邪惡之毒的實體化身。",creatures={[1]="黏性輻射塵"}},[6235]={name="電刑器6000型",desc="機電師瑟瑪普拉格不是個有耐心的地精。他不會對他的發明進行一連串的測試來確認其安全性與效率，而是草率地將它們投入實用然後就繼續進行下一項企劃。電刑器6000型就是他第一次嘗試以超載的機械坦克操控電力來當作武器。『嘶嘶褲』湯姆‧彎曲中尉是唯一在駕駛電刑器中存活下來的士兵，如今他就像痲瘋地精中的英雄一般。",creatures={[1]="電刑器6000型"}},[6229]={name="群體打擊者9-60",desc="在諾姆瑞根的全盛期，發明家們會將他們創造的東西擺在一起彼此對抗，以競爭更高的地位。機電師奧格索普‧奧布諾提斯打造了一個不敗的機器人，並以此獲得大工匠的尊敬。希科‧瑟瑪普拉格竊取了奧布諾提斯的藍圖並製造了一個更巨大的版本。他將這個贗品放出而造成的恐怖結果驅使管理議會放逐無辜的奧布諾提斯。群體打擊者9-60至今仍是瑟瑪普拉格最愛的（偷來的）發明之一。",creatures={[1]="群體打擊者9-60"}},[7800]={name="機電師瑟瑪普拉格",desc="殺人兇手、背叛者、並自稱是地精之王，機電師希科‧瑟瑪普拉格以一個故障的鐵拳支配著充滿放射線的諾姆瑞根。他擁有無數兇惡的下屬，瘋狂到會為了捍衛其發瘋的國王而和任何地上世界的入侵者對抗。讓瑟瑪普拉格如此危險的主因就是他的瘋狂;他擁有能枉顧自己生命，不計一切摧毀身邊所有事物的狡詐智慧。這也是為什麼連諾姆瑞根中的怪物都畏懼它的原因。",creatures={[1]="機電師瑟瑪普拉格"}},[1696]={name="可怕的塔高爾",creatures={[1]="可怕的塔高爾"}},[1666]={name="卡姆·深怒",creatures={[1]="卡姆·深怒"}},[1717]={name="哈姆霍克",creatures={[1]="哈姆霍克"}},[1716]={name="巴基爾·斯瑞德",creatures={[1]="巴基爾·斯瑞德"}},[1663]={name="迪克斯特·瓦德",creatures={[1]="迪克斯特·瓦德"}},[1720]={name="布魯戈·艾爾克納寇",creatures={[1]="布魯戈·艾爾克納寇"}},[6168]={name="魯古格",creatures={[1]="魯古格"}},[4424]={name="阿葛金‧棘咒",creatures={[1]="阿葛金‧棘咒"}},[4428]={name="亡語者賈格巴",creatures={[1]="亡語者賈格巴"}},[4420]={name="拉姆塔斯主宰",creatures={[1]="拉姆塔斯主宰"}},[4422]={name="暴怒的阿迦賽羅斯",creatures={[1]="暴怒的阿迦賽羅斯"}},[4421]={name="卡爾加‧刺肋",creatures={[1]="卡爾加‧刺肋"}},[3983]={name="審訊員韋沙斯",creatures={[1]="審訊員韋沙斯"}},[4543]={name="血法師薩爾諾斯",creatures={[1]="血法師薩爾諾斯"}},[3974]={name="馴犬者洛克希",creatures={[1]="馴犬者洛克希"}},[6487]={name="秘法師杜安",creatures={[1]="秘法師杜安"}},[3975]={name="赫洛德",creatures={[1]="赫洛德"}},[3976]={name="血色十字軍指揮官莫格萊尼",creatures={[1]="血色十字軍指揮官莫格萊尼"}},[3977]={name="高階審判官懷特邁恩",creatures={[1]="高階審判官懷特邁恩"}},[4542]={name="高等審判官法爾班克斯",creatures={[1]="高等審判官法爾班克斯"}},[6910]={name="魯維羅什",desc="鐵爐堡有名望的探險者協會中的一些傑出人物提出了一項理論，他們說矮人和穴居怪的祖先也許有些關連，證據就是穴居怪和矮人一樣會收藏泰坦的神器。如果這屬實，那名為魯維羅什的穴居怪就相當於穴居怪的考古學家，不過任何遭遇過他，且帶有歷史觀點的探險家大概都會偏向稱他為小偷。",creatures={[1]="魯維羅什"}},[6906]={name="失落的矮人",desc="為了尋求名聲，或更重要的，尋求財富，艾瑞克、奧拉夫與貝洛格三兄弟接受了一個探險者協會的合約，要深入奧達曼大廳中為一群研究者清出一條路徑。很不幸地對這三個矮人來說，伴隨著「清出一條路徑」的是「絕望地迷失在一座古代迷宮之中」。但他們到死都要當一名驕傲的矮人，為了不讓奧達曼與探險者協會的秘密落入部落手中而不停奮戰著。",creatures={[1]="失落的矮人"}},[7228]={name="艾隆納亞",desc="泰坦們並沒有直接地建造奧達曼，而是運用許多僕從來打造這個以巨石建成的大廳。泰坦們委託看守者艾隆納亞監督奧達曼的建造與維護，但隨著時間消逝，這曾經一度令人驚嘆的寶庫化為一堆廢墟。艾隆納亞在地圖室內停滯了千年之久，她全心分析著卡茲格羅斯當初所繪製的藍圖，打算找出方法讓奧達曼的設施恢復最初的正常機能。",creatures={[1]="艾隆納亞"}},[7206]={name="上古石之守衛者",desc="上古石之守衛者是讓泰坦偉大寶庫得以運作的魔像成員之一，他也是負責操控設施的看守者與其他許多僕從之間的中間人之一。隨著黑曜石哨兵的墮落，上古石之守衛者是他族類中碩果僅存的一員，直到他無法避免地停止運作之前，他都會竭盡全力地執行他保護泰坦們秘密的職責。",creatures={[1]="上古石之守衛者"}},[7291]={name="加加恩‧火錘",desc="為了對銅鬚矮人發現奧達曼做出反應，黑鐵部族對寶庫發動侵略以阻止他們長久以來的敵人得到其中強大的神器。加加恩‧火錘是一名影爐城的議員，他被指派負責監督奧達曼的挖掘，以確保大帝能運用神器毀滅性的潛力摧毀黑鐵部族的敵人。",creatures={[1]="加加恩‧火錘"}},[4854]={name="格瑞姆洛克",desc="在穴居怪的社會中，體型最大、最強壯、最兇猛的穴居怪能藉由展示力量來成為酋長。相較於其他穴居怪來說，格瑞姆洛克可算是一個天才，他利用威嚇與粗陋的心理戰來維持他對石窟穴居怪的控制。格瑞姆洛訓練了一隻致命的蜥蜴，用其石化的威脅來嚇阻可能想推翻他的人。",creatures={[1]="格瑞姆洛克"}},[2748]={name="阿札達斯",desc="在奧達曼深處的一間密室中藏有一個由諾甘農親自打造的最偉大泰坦寶藏之一。然而截至目前為止，沒有任何探險者能夠得到這項古物，因為任何想取走寶物的嘗試都會啟動巨大的看守者阿札達斯，他強大的攻擊與其堪稱是軍隊的僕從們能夠輕易地了結任何尋寶者。阿札達斯是用奧達曼地下最古老、最堅固的岩石所打造，他難纏的程度可和他古老的程度媲美。",creatures={[1]="阿札達斯"}},[7355]={name="圖特卡什",creatures={[1]="圖特卡什"}},[7357]={name="火眼莫德雷斯",creatures={[1]="火眼莫德雷斯"}},[8567]={name="暴食者",creatures={[1]="暴食者"}},[7356]={name="腐爛的普雷莫爾",creatures={[1]="腐爛的普雷莫爾"}},[7354]={name="拉戈斯諾特",creatures={[1]="拉戈斯諾特"}},[7358]={name="『寒冰使者』亞門納爾",creatures={[1]="『寒冰使者』亞門納爾"}},[13282]={name="諾克賽恩",desc="諾克賽恩是個活生生的腐敗化身。瑟萊德絲命令她的盟友維利塔恩領主製造這個腐臭的元素生物，以作為一個強大的僕人和紓解公主孤單寂寞的忠誠寵物。諾克賽恩將它的毒素散佈到瑪拉頓中還未因瑟萊德絲邪惡影響力而凋零的區域裡。",creatures={[1]="諾克賽恩"}},[12258]={name="銳刺鞭笞者",desc="銳刺鞭笞者是為了在瑪拉頓陪伴諾克賽恩而被製造出來。隨著時間過去，這個新創造成為公主最珍愛的僕從之一。銳刺鞭笞者時常和諾克賽恩一起遊蕩在洞穴之中，使用它長滿荊棘的觸手撕裂它發現的任何未被污染的植物。",creatures={[1]="銳刺鞭笞者"}},[13601]={name="技工吉茲洛克",desc="技工吉茲洛克和其他五名寶石獵人潛入瑪拉頓以開採其有著高度價值的水晶。他們的計畫出了可怕的大紕漏，薩特們屠殺了除了吉茲洛克之外的所有人。這個被困在洞穴中頻臨瘋狂邊緣的哥布林認為自己是這地下地區的新統治者。",creatures={[1]="技工吉茲洛克"}},[12236]={name="維利塔恩領主",desc="薩特領主維利塔恩在聽說瑪拉頓深處的腐化後前往那裡。一開始瑟萊德絲嚴防著這可能心懷不軌的惡魔，但維利塔恩藉由為公主製造一群邪惡的爪牙證明了他的價值，像是諾克賽恩和銳刺鞭笞者。",creatures={[1]="維利塔恩領主"}},[12225]={name="被詛咒的塞雷布拉斯",desc="在聽說他叔叔悲慘的命運後，高貴的塞雷布拉斯誓言要解放札爾塔的靈魂。但這個森林看守者並未對等待在瑪拉頓陰暗通道中的恐怖事物做好準備。充滿在那裡的黑暗能量很快地就壓倒了塞雷布拉斯，讓他的心中充滿了無法控制的怒氣。",creatures={[1]="被詛咒的塞雷布拉斯"}},[12203]={name="蘭斯利德",desc="多年來，名為蘭斯利德的古老山岳巨人培育著瑪拉頓中的美麗水晶花園，但瑟萊德絲在那裡居住下來時迷住了這個巨人。這個曾經一度恬淡寡欲的巨人現在活著只是為了要效忠他專制的新主人。",creatures={[1]="蘭斯利德"}},[13596]={name="洛特格里普",desc="據謠傳洛特格里普已經居住在瑪拉頓地下的水中長達千年之久。有名的矮人獵人赫米特‧奈辛瓦里曾一度宣稱沒有人能找到這野獸，而一群業餘的追蹤者接受了這項找出傳說中生物的挑戰，卻沒有任何人能活著回來。",creatures={[1]="洛特格里普"}},[12201]={name="瑟萊德絲公主",desc="土元素瑟萊德絲是石母瑟拉贊恩唯一的女兒，她居住在瑪拉頓內部的秘所內。因為受到上古諸神的影響，公主將她的家改造成一個腐敗與受難的巢穴。有些人相信她的邪惡力量和她死去的愛人札爾塔有關。如果真是這樣，解放這名墮落的森林看守者可能是淨化瑪拉頓的唯一希望。",creatures={[1]="瑟萊德絲公主"}},[7272]={name="『殉教者』塞卡",desc="在很久以前，『殉教者』塞卡在一場其拉與食人妖之間的殘酷戰爭中被殺死。祖爾法拉克也因為他英勇的犧牲而能夠存留下來。就算在死後，他仍高度警戒地守護著他深愛的城市，據說有許多當時殺死他的蟲人戰士如今被詛咒，變成他身邊許多無腦的甲蟲們。",creatures={[1]="『殉教者』塞卡"}},[7795]={name="水占師維蕾薩",desc="與大部分的沙怒食人妖不同，水占師維蕾薩曾遊歷世界，收集知識和神器來幫助自己控制祖爾法拉克的神聖之水。雖然這位水占師的行徑讓她樹立了很多異國的敵人，但她認為自己所掌握的驚人力量是她過往罪行的正當理由。",creatures={[1]="水占師維蕾薩"}},[8127]={name="安圖蘇爾",desc="安圖蘇爾喜歡將他的蘇薩斯蜥蜴養得既強壯又冷酷。他對待這些野獸如同家人一般，他會殺死敢傷害他珍貴小孩的任何人，連食人妖同胞也不例外。只要有人膽敢妨礙他，他不會讓敵人留下全屍，而會讓蜥蜴們好好飽餐一頓。",creatures={[1]="安圖蘇爾"}},[7271]={name="巫醫祖穆拉恩",desc="強大的神靈伯昂撒姆第看管著暗矛食人妖的靈魂，但許多沙怒部族死去的成員在死後並無受到如此保護。這些被折磨的靈魂聽命於一個殘忍的巫醫祖穆拉恩，他利用他的黑暗魔法來逼迫這城市的死者為他永無止境的效勞。",creatures={[1]="巫醫祖穆拉恩"}},[7273]={name="加茲瑞拉",desc="傳說加茲瑞拉曾是上古諸神寵愛的寵物，甚至她自己就是個半神。不管真相是什麼，沙怒食人妖已經膜拜這隻巨大多頭蛇有數千年之久。因為深怕此野獸的寒冰之怒，食人妖只會在有許多祭品能滿足她的胃口時喚醒她。",creatures={[1]="加茲瑞拉"}},[7796]={name="耐克倫&塞瑟斯",desc="耐克倫‧嚼腸者在他自然壽命結束後仍神奇地活得很好，而他逐漸腐爛的軀體仍強壯到可以協助塞瑟斯。他們兩人一起為沉睡在城市中心的神秘野獸加茲瑞拉收集到許多祭品。許多食人妖跟隨者熱切地等待這恐怖生物的甦醒，而他們會不計任何代價讓儀式能夠成功。",creatures={[1]="耐克倫&塞瑟斯"}},[7267]={name="烏克茲‧沙頂",desc="烏克茲‧沙頂著迷於為他的部族恢復過去的榮光。他在成長過程中聽過無數故事，是關於過去食人妖如何在沒有哥布林、地精、海盜、巨魔和其他妨礙者阻撓下統治這片土地。沙頂喚來他信任的同志盧茲魯，協助他一起為沙怒的歷史開啟全新的一章，而方法就是他們部族所知的唯一方法:迅速到讓人無法看清的猛烈攻擊。",creatures={[1]="烏克茲‧沙頂"}},[10506]={name="傳令官基爾圖諾斯",creatures={[1]="傳令官基爾圖諾斯"}},[10503]={name="詹迪斯‧巴羅夫",creatures={[1]="詹迪斯‧巴羅夫"}},[11622]={name="血骨傀儡",creatures={[1]="血骨傀儡"}},[10433]={name="馬杜克·布萊克波爾",creatures={[1]="馬杜克·布萊克波爾"}},[10432]={name="維克圖斯",creatures={[1]="維克圖斯"}},[10508]={name="萊斯·霜語",creatures={[1]="萊斯·霜語"}},[10505]={name="講師瑪麗希亞",creatures={[1]="講師瑪麗希亞"}},[11261]={name="瑟爾林·卡斯迪諾夫教授",creatures={[1]="瑟爾林·卡斯迪諾夫教授"}},[10901]={name="博學者普克爾特",creatures={[1]="博學者普克爾特"}},[10507]={name="拉文尼亞",creatures={[1]="拉文尼亞"}},[10504]={name="阿萊克斯·巴羅夫領主",creatures={[1]="阿萊克斯·巴羅夫領主"}},[10502]={name="伊露希亞·巴羅夫女士",creatures={[1]="伊露希亞·巴羅夫女士"}},[1853]={name="黑暗院長加丁",creatures={[1]="黑暗院長加丁"}},[9018]={name="高階審問者格斯塔恩",desc="暮光之錘邪教徒格斯塔恩總是沉迷於一些生活中美好的事物:奇特的美食、華貴的服飾，與鑲滿寶石的刑具。她的囚犯日以繼夜地發出令人膽寒的尖叫，迴盪在黑鐵部族惡名遠播的拘留區中。格斯塔恩驕傲地把這恐怖的噪音稱為她的尖叫交響曲，且總是熱切地想要在這合奏中加入另一個聲音。",creatures={[1]="高階審問者格斯塔恩"}},[9025]={name="洛考爾領主",desc="洛考爾領主厭惡他火元素同伴們的詭計與相互出賣。為了避免與他們一起在熔火之心效勞，這個強大的生物故意觸怒了炎魔。洛考爾這冒險的險著成功了:他被驅逐出熔火之心，並被迫在單獨守衛黑石深淵。",creatures={[1]="洛考爾領主"}},[9319]={name="馴犬者格雷布瑪爾",desc="格雷布瑪爾‧蚤鬍的獵犬們是他所知的唯一家人。在很久以前，這個矮人孤兒就開始飼育犬類來當作夥伴和守衛犬。當馴犬者沒有和他忠誠的野獸們在黑石深淵中巡邏時，他常會給牠們喝黑鐵酒吧中最好的黑鐵麥芽酒。",creatures={[1]="馴犬者格雷布瑪爾"}},[10096]={name="秩序競技場",desc="對黑鐵矮人犯下的罪行只有一種刑罰:死刑。古老的傳統會要求有罪之人付出血的代價，在秩序競技場中與從艾澤拉斯收集來的野蠻生物作戰。到今日，是否有人曾經在這殘酷的考驗中存活下來仍不得而知。",creatures={[1]="秩序競技場"}},[9024]={name="火占師羅格雷恩",desc="曾經身為陶土議會受人敬仰的成員，羅格雷恩加入暮光之錘邪教的原因對他的前盟友來說仍然是一個謎團。他後來前往黑石深淵，在那他突然對有名的黑鐵建築師弗蘭克羅恩‧鑄鐵感到興趣。他目前著迷的原由仍不明朗，但羅格雷恩依然忠誠於邪教，是他所有反對者的敵人。",creatures={[1]="火占師羅格雷恩"}},[9017]={name="伊森迪奧斯領主",desc="迦頓男爵教導伊森迪奧斯如何操控他毀滅性的力量，但男爵從未預料到他的門徒能成長到如此致命。因為越來越惟恐伊森迪奧斯有可能會推翻他，男爵將這個熾熱元素從熔火之心派出來防衛黑鐵矮人傳說中的黑鐵砧。",creatures={[1]="伊森迪奧斯領主"}},[9041]={name="護衛斯迪爾基斯",desc="狡詐的法師迪爾基斯在對索瑞森大帝的盡忠多年之後，被託付保衛他的部族在黑鐵寶庫中的財寶。這位忠誠矮人的摯友馴犬者格雷布瑪爾為了慶祝此事，從他兇猛的狗群中挑了一隻叫維雷克的惡犬，送給迪爾基斯。法師善用這隻野獸，把牠留在身邊以嚇跑對寶庫圖謀不軌的小偷。",creatures={[1]="護衛斯迪爾基斯"}},[9056]={name="弗諾斯‧達克維爾",desc="首席建築師弗諾斯‧達克維爾因為將其他更有天賦石匠的主意竊為己有而獲得他的稱號。他的自大與詭計從墓中招來了他的前任者弗蘭克羅恩‧鑄鐵的憤怒。上一任首席建築師的鬼魂想要將他不可思議強大的錘子，鐵膽之錘，在達克維爾能以它作惡之前從他手中取回。",creatures={[1]="弗諾斯‧達克維爾"}},[9016]={name="貝爾加",desc="黑鐵大道是矮人工程學在黑石深淵所創下的驚人成就，而巨大的熔火巨人貝爾加就在其上笨重地漫步著。拉格納羅斯從火源之界中將此巨人帶來守衛大道一端緊閉的巨大之門。根據傳說，只有炎魔與黑鐵部族最高階的成員知道此神秘之門另一端有些什麼。",creatures={[1]="貝爾加"}},[9033]={name="安格弗將軍",desc="經過一生的研究，安格弗將軍成為一名矮人軍隊歷史與戰術的專家。他最近因為寫了一篇關於他部族在過去戰爭中失敗的苛刻論文而觸怒了達格蘭‧索瑞森大帝。姑且不論他這在政治上的紕漏，安格弗是個十足的黑鐵矮人。他會為了保護他的同胞與他的大帝而流血，就算死亡也在所不惜。",creatures={[1]="安格弗將軍"}},[8983]={name="魔像領主阿格曼奇",desc="阿格曼奇一生對不老不死的著迷驅使他打造一個以他自己形象為基礎的魔法傀儡。據謠傳所言，他同時涉獵了某種黑魔法，使魔像領主在他的血肉身軀被摧毀後可以當作他靈魂的容器。",creatures={[1]="魔像領主阿格曼奇"}},[9537]={name="霍爾雷‧黑息",desc="說黑息是黑鐵酒吧的常客也不足以形容他。在十多年裡，這個古靈精怪的醉漢只離開過酒館一次，去偷取雷霆啤酒的最高機密配方。黑息偶爾能清醒到可以自己釀酒，他聲稱這給他帶來無法想像的力量與勇氣。",creatures={[1]="霍爾雷‧黑息"}},[9502]={name="法拉克斯",desc="直到最近，幾乎每天都有喝醉的酒客在黑鐵酒吧裡打鬥鬧事。酒保普拉格‧史帕齊林藉著使用強大的魔像保鏢，也就是法拉克斯，已經成功減少這些亂鬥發生的頻率。法拉克斯被設定用來維持酒管裡的秩序，並以極端的武力來排除滋事的酒客。",creatures={[1]="法拉克斯"}},[9499]={name="普拉格‧史帕齊林",desc="據說在黑鐵酒吧每個人都知道你的名字。這種同好間的友情是史帕齊林努力的成果。史帕齊林是個在諾姆瑞根失落後，希望能在黑石深淵找到新生活的痲瘋地精。儘管他曾經是個和邪惡打交道的術士，他以酒館酒保的工作為傲，並確保他酒客的酒杯中總是倒滿了酒。",creatures={[1]="普拉格‧史帕齊林"}},[9156]={name="弗萊拉斯大使",desc="因為他對拉格納羅斯堅定的效忠，弗萊拉斯躍昇成為與黑鐵部族往來的大使。這個墮落的生物起初鄙視他的矮人盟友們，但後來逐漸對他們喜好破壞的傾向產生敬意。為了展示與他們的團結合作，弗萊拉斯看守著魔法之廳，一個矮人們用來強化他們武裝的地方。",creatures={[1]="弗萊拉斯大使"}},[9039]={name="七賢",desc="幾世紀以前，巫士族長索瑞森和七名他最強大的黑鐵盟友意外地將拉格納羅斯召喚來到艾澤拉斯，而使他們整個部族被奴役。雖然七賢在儀式中喪生，他們無法安息的靈魂仍然逗留在黑石深淵中，被詛咒必須為他們的元素主人與目前的黑鐵統治者效勞。",creatures={[1]="七賢"}},[9938]={name="瑪格姆斯",desc="弗萊拉斯大使命令熔火巨人瑪格姆斯守衛達格蘭‧索瑞森大帝的王座室，但此舉仍無法使黑鐵統治者安心。因極度害怕刺客，大帝給予瑪格姆斯在他房間外一連串可以噴出火焰的雕像的控制權。",creatures={[1]="瑪格姆斯"}},[9019]={name="達格蘭‧索瑞森大帝",desc="達格蘭‧索瑞森大帝和敵對銅鬚部族的茉艾拉公主一起進行著統治。關於大帝是否迷惑了他的新娘還是她自願和大帝在一起的爭辯從未止息。不管真相是什麼，索瑞森的存在對他部族的未來並不是一件好事。只要他還活著，黑鐵矮人就只是拉格納羅斯的奴僕，也是對整個艾澤拉斯各王國的嚴重威脅。",creatures={[1]="達格蘭‧索瑞森大帝"}},[8443]={name="哈卡的化身",desc="哈卡因為要求其跟隨者必須獻上祭品而惡名昭彰。在數千年以前，他教導阿塔萊如何召喚他的化身，並以儀式吸取活生生的受害者之血來餵食他。阿塔萊祭司們如今想要以一個更改過的儀式版本，用犧牲綠龍們來培育哈卡的化身。如果阿塔萊成功了，哈卡化身的重現可能是艾澤拉斯的末日。",creatures={[1]="哈卡的化身"}},[5710]={name="『預言者』迦瑪蘭",desc="迦瑪蘭是阿塔萊目前的領袖，而阿塔萊是一群狂熱膜拜哈卡的祭司極端分子。在深層冥想中，迦瑪蘭接收到如何以哈卡的龍族敵人綠龍軍團之血，來讓哈卡復活的指示。迦瑪蘭與其不死保鏢可悲的奧戈姆隨時準備好和想阻止哈卡重返之人對抗。不過預言者的行動可能為艾澤拉斯帶來更為嚴重與恐怖的威脅:翡翠夢魘。",creatures={[1]="『預言者』迦瑪蘭"}},[5312]={name="夢境看守者",desc="有四頭極有潛力的年輕綠龍伴隨伊蘭尼庫斯進入阿塔哈卡神廟，迫切地想要以服侍一頭偉大且強大的巨龍來證明自己的價值。但牠們一個接著一個地被翡翠夢魘所捕捉及污染，如今牠們遊蕩在沉沒神廟的大廳之中，攻擊任何侵入牠們清醒夢境之人。",creatures={[1]="夢境看守者"}},[5709]={name="伊蘭尼庫斯之影",desc="伊蘭尼庫斯是夢境之龍伊瑟拉的前任配偶，他被指派前往守衛阿塔哈卡廢墟並阻止哈卡的出現。一進入神廟之中，他和他的隨扈就被那裡的黑暗力量所腐化，他還變成了一個影子，在翡翠夢境與實體世界之間被拉扯著。儘管他已經墮落，伊蘭尼庫斯仍然能夠使用他身為一頭綠龍的能力，對他的敵人噴出腐蝕性的酸液，或將其困在深沉的睡眠之中。",creatures={[1]="伊蘭尼庫斯之影"}},[9196]={name="歐莫克大王",desc="歐莫克大王以鐵腕支配著塔中的巨魔。有許多下屬曾經挑戰他進行一對一的戰鬥，希望能得到大王的頭銜，但都在未使出一招半式的情況下就落敗了。這種神秘的現象導致有黑暗魔法在保護歐莫克的謠言產生。",creatures={[1]="歐莫克大王"}},[9236]={name="暗影獵手沃許加斯",desc="沃許加斯因為她的美麗--還有其精神病的傾向--而在食人妖中聞名。她是暗影獵手技藝的大師，能操控強大的妖術、詛咒與治療魔法。",creatures={[1]="暗影獵手沃許加斯"}},[9237]={name="將領沃恩",desc="在第二次戰爭期間，沃恩率領了一支小型打擊部隊進入高等精靈領土核心進行大膽的任務。這個狡猾的食人妖因為想成為總軍師而加入了虛假的部落，而不是因為他相信黑手的思想體系。沃恩知道這個分裂的陣營處於劣勢，而他就是喜歡克服難以超越的障礙所帶來的成就感。",creatures={[1]="將領沃恩"}},[10596]={name="煙網蛛后",desc="幾世紀以前，黑鐵矮人挖掘到煙網蛛后的巢穴，讓這個巨大的蜘蛛進入塔中。她的幼蟲數量從那時開始就持續地壯大，多到甚至連黑手的部隊都不敢通過煙網的領域。",creatures={[1]="煙網蛛后"}},[10584]={name="烏洛克‧末日嚎",desc="末日嚎是塔中巨魔的真正領袖。這個邪惡的人物以陰險的魔法迷惑了他受到信任的幫手歐莫克大王，代替他控制末日嚎的爪牙們。他為了維持這個圈套不遺餘力，會無情地殺死任何挑戰大王權威的巨魔。",creatures={[1]="烏洛克‧末日嚎"}},[9736]={name="軍需官茲格雷斯",desc="在第一次戰爭後，獸人獵人茲格雷斯因其喜好追蹤暴風城難民，並將他們當作獵物殺害而惡名遠播。他厭惡黑石塔會讓人得到幽閉恐懼症的廳堂，但他確信有一天他能再度在開闊之地進行狩獵。",creatures={[1]="軍需官茲格雷斯"}},[10220]={name="哈雷肯",desc="哈雷肯來自於一條因其兇猛與忠誠而被繁殖的偉大座狼血脈。多年以來，這頭獸穴之后產下了數量驚人的子嗣。有一則謠言說她是燃燒軍團一名深淵領主送給雷德‧黑手的惡魔獵犬。",creatures={[1]="哈雷肯"}},[10268]={name="『奴役者』基茲盧爾",desc="黑暗部落很少人看過隱遁與難以預料的基茲盧爾。這頭野獸只會在他的配偶哈雷肯呼喚他時，從他陰暗的巢穴中出現。這兩頭巨獸生下了許多獸人有史以來最大、最兇猛的座狼。",creatures={[1]="『奴役者』基茲盧爾"}},[9568]={name="維姆薩拉克主宰",desc="黑龍裔維姆薩拉克監督著下層塔中的部隊，對攻擊矮人進行準備。他一點也不喜歡這虛假的部落和他們野蠻的成員，只要是為了保護它的主人奈法利安，要他犧牲多少黑手的爪牙都無所謂。",creatures={[1]="維姆薩拉克主宰"}},[11489]={name="特迪斯‧扭木",desc="特迪斯‧扭木曾經是個埃德薩拉斯的可靠守衛，他的心堅定地和這座城市的命運纏繞在一起。當大崩裂將大地撕裂時，他的決心也未動搖過。但在大崩裂發生後的10000年來，許多腐化的能量逐漸滲入城市廢墟之中，使這古樹之魂受到了腐化。",creatures={[1]="特迪斯‧扭木"}},[11488]={name="伊琳娜‧鴉橡",desc="伊琳娜‧鴉橡和她忠實的夥伴費拉，曾經是托塞德林王子最看重的獵人，直到她拒絕遵從她的領袖要她處決朋友的命令。他殺死了伊琳娜和她的熊作為懲罰，但使用惡魔力量將她們的靈魂束縛在她們的軀體內，迫使她們成為厄運之槌的不死保護者。",creatures={[1]="伊琳娜‧鴉橡"}},[11487]={name="博學者卡雷迪斯",desc="當托塞德林王子要求屠殺他大部分的臣民時，他最忠誠的部下們接下了執行其意志的任務。博學者卡雷迪斯毫不猶豫地殺死了許多不知大禍臨頭的辛德拉人，但其中一個將死的精靈在一場毀滅性的戰鬥中使他受到了致命傷。就算在死後卡雷迪斯的靈魂仍遊蕩在厄運之槌中，作為托塞德林統治的守衛。",creatures={[1]="博學者卡雷迪斯"}},[11496]={name="伊莫塔爾",desc="為了恢復在永恆之井被摧毀時失去的力量與不老不死能力的孤注一擲，辛德拉人將一個惡魔召喚到厄運之槌西翼，並以力場捕捉他，讓他們可以利用虛無恐獸的能量來施展自己的法術。在幾乎10000年無法反擊或甚至移動的折磨後，伊莫塔爾只能眼睜睜看著並等待有一天他能掙脫自由，將捕捉他的人撕成碎片。",creatures={[1]="伊莫塔爾"}},[11486]={name="托塞德林王子",desc="在永恆之井被毀滅後，托塞德林王子藉由將一個惡魔囚禁在埃德薩拉斯廢墟之中，並讓他的臣民吸收其力量來維持對存活辛德拉人的控制。暴露在惡魔力量之下扭曲了托塞德林的心智，使他在惡魔衰弱時下令將他的許多臣民殺死，這樣一來只有他和他最狂熱的跟隨者可以享用腐敗的能量。",creatures={[1]="托塞德林王子"}},[14327]={name="蕾瑟塔蒂絲",desc="厄運之槌的扭曲能量將蕾瑟塔蒂絲從遠方吸引而來，為滿足她對秘法魔法令人難以忍受的渴求帶來希望。她以獻祭受害者的肌腱與韌帶打造了一張能夠從厄運之槌東翼吸取腐敗能量的網子。讓她欣喜的是，她發現這個裝置能夠收集龐大壓倒性的力量，其威力足夠毀滅她的所有敵人。",creatures={[1]="蕾瑟塔蒂絲"}},[13280]={name="海多斯博恩",desc="當薩特瑟雷姆‧刺蹄尋求控制厄運之槌中的元素生物時，他把精力集中在平靜地居住在他祭壇之下的海多斯博恩身上。隨著他褻瀆的獻祭儀式進行，海多斯博恩變得越來越激動且不得安寧，並對刺蹄的惡魔爪牙們發動攻擊。經年累月，刺蹄利用他受害者們的能量讓海多斯博恩的憤怒達到無法抑制的地步，並一點一滴地使它受縛於薩特的命令之下。",creatures={[1]="海多斯博恩"}},[11490]={name="瑟雷姆‧刺蹄",desc="因迫切地想要對燃燒軍團展現他的價值，瑟雷姆‧刺蹄向他的主人們保證他能夠奴役仍漫遊在厄運之槌中的強大古樹。當他認知到他自己的力量不足以達成目標時，他轉向其他生物尋求更多能量，在他的獻祭壇上屠殺受害者，並在他們痛苦的最後一刻收割他們的精華。",creatures={[1]="瑟雷姆‧刺蹄"}},[11492]={name="『狂野變形者』奧茲恩",desc="『狂野變形者』奧茲恩一心只想要讓菲拉斯完全墮落腐敗，但直到他在厄運之槌裡發現艾德雷斯神殿前，他做的並不成功。藉助被他奴役而聽他號令的古樹力量，奧茲恩將周遭森林的活力匯集到他的巢穴之中，使他能自由地操控森林的力量。",creatures={[1]="『狂野變形者』奧茲恩"}},[10558]={name="爐邊歌手弗瑞斯坦",desc="斯坦索姆的抉擇使許多無法計數的人們喪生，而他們唯一的罪過就是當時留在那注定毀滅的城市中。有一個名為弗瑞斯坦的旅行歌手與短笛樂手就是其中一名受害者。他在死後仍持續遊蕩在城中，無法接受他悲慘的命運。",creatures={[1]="爐邊歌手弗瑞斯坦"}},[10516]={name="不可寬恕者",desc="莉莉亞對她的同胞來說曾經象徵著一把正義之劍。但在阿薩斯下令屠城時，她的理智在目睹自己殺死無數無辜之人後已蕩然無存。她揮劍自殺以逃避周遭的瘋狂之事，如今她變成了一個因為其暴行而永遠不會被寬恕的鬼靈。",creatures={[1]="不可寬恕者"}},[11143]={name="郵政局長瑪羅恩",desc="瑪羅恩可不是靠著對郵件不聞不問才當上郵政局長的。就算現在身居高位，他也將工作重心放在維護郵政系統的穩定性上。要是這個系統被擾亂到對穩定性造成威脅的程度，瑪羅恩可能就會親自出馬解決問題。",creatures={[1]="郵政局長瑪羅恩"}},[10808]={name="殘忍的提米",desc="提米森在戰場上的兇殘惡名遠播。有些人猜測他病態般的殘忍是源於他在孩提時期受到無盡的欺侮。如今他重生為一個天譴軍團的怪物，他的心智早已壞滅，卻仍被過往的記憶所折磨著，使他對這個曾一度極度厭惡的名字有反應:提米。",creatures={[1]="殘忍的提米"}},[11032]={name="指揮官瑪洛爾",desc="瑪洛爾和其他一些英勇的戰士們冒著失去所有的風險，保護血色十字軍堡壘免於不死生物的褻瀆。悲慘的是，他們失敗了。巴納札爾使這無懼的指揮官腐化成為他的一名僕從，將這狂熱者轉變成嘲笑過往自身的笑柄。",creatures={[1]="指揮官瑪洛爾"}},[10997]={name="威利‧希望破除者",desc="變成不死生物的火砲大師威利擁有毀滅性的能力，這讓巴納札爾操縱他得到許多樂趣，甚至給了這個他看重的爪牙希望破除者的稱號。能將威利與其他血色十字軍等生前厭惡不死生物的人們心智扭曲，成為他無知覺的棋子，讓驚懼領主巴納札爾不禁欣賞起自己的傑作。",creatures={[1]="威利‧希望破除者"}},[10811]={name="古卷管理者加爾福特",desc="加爾福特曾經以看管血色十字軍最珍貴的文件為傲。然而在他死時，他卻只能驚恐地看著他最重視的書籍在他身邊被燒毀。加爾福特活著時受到熾炎力量的蹂躪，如今巴納札爾利用這段痛苦的記憶，將這股力量注入他這位僕人的體內。",creatures={[1]="古卷管理者加爾福特"}},[10813]={name="巴納札爾",desc="巴納札爾從來沒有真正死亡過，但他曾經嚐過苦澀的失敗。在大災變撼動整個世界後，他將斯坦索姆中的血色十字軍屠殺殆盡，並將他們轉變成他們一度痛恨的不死生物。這個驚懼領主如今策劃陰謀要對整個艾澤拉斯進行復仇。",creatures={[1]="巴納札爾"}},[14326]={name="守衛摩爾達",desc="摩爾達是個狂熱且忠誠的戈多克巨魔守衛。他深信因為戈多克大王賜予他一雙附魔過的手套，他才能連續六年衛冕腕力冠軍。事實上，戈多克大王只是把那強大的護甲亂丟，而摩爾達最先發現它罷了。",creatures={[1]="守衛摩爾達"}},[14322]={name="踐踏者克雷格",desc="這發生過不只一次，鬼鬼祟祟的刺客們因為不小心打翻了克雷格的酒杯而斷送了他們的性命。雖然他常常在值勤時醉倒，沒有什麼事能比聽到他最珍貴的酒被濺灑在地板上的聲音讓這巨魔更加大發雷霆。",creatures={[1]="踐踏者克雷格"}},[14321]={name="守衛芬古斯",desc="自從『觀察者』克魯什告訴他注定在值勤時遇到他的伴侶後，芬古斯只要醒著就是在戈多克的領土內巡邏著。",creatures={[1]="守衛芬古斯"}},[14323]={name="守衛斯里基克",desc="有些人覺得斯里基克不只是謹慎，還很懶。他不直接挑戰戈多克大王，而只是修補一些陷阱和古老損壞的魔法裝置，希望能不費吹灰之力地給予致命一擊。",creatures={[1]="守衛斯里基克"}},[14325]={name="隊長克羅卡斯",desc="就算在巨魔之中，隊長克羅卡斯只要有人膽敢侮辱他或戈多克大王就會暴怒的脾氣也是惡名昭彰。他會殘酷地揍扁持異議的人，但持續散播關於許久以前他和一個豺狼人熱戀謠言的人讓他更加無法忍受。",creatures={[1]="隊長克羅卡斯"}},[14324]={name="『觀察者』克魯什",desc="克魯什通常不會選邊站，但當烏羅克崛起時，很明顯地沒有其他人可以挑戰他。大王很快地就指定克魯什作為他的首席顧問，確信他的兩顆頭讓他能比一般的巨魔聰明兩倍。",creatures={[1]="『觀察者』克魯什"}},[11501]={name="戈多克大王",desc="要統治戈多克巨魔很簡單，你只要聲稱自己為王...並消滅所有可能反對的人就行了。在無名小卒烏羅克成為戈多克大王前，他藉由說服同胞中數名最強壯的戰士同時挑戰大王來鞏固自己的權力。那場狂野的大亂鬥使多數的競爭者不是喪命就是受到重傷，而烏羅克的刀刃輕易地就解決了存活者和因戰鬥而疲憊不堪的大王。直到今天，戈多克巨魔也只敢小聲地講述關於「血腥之日」的事。",creatures={[1]="戈多克大王"}},[10436]={name="安娜絲塔麗男爵夫人",desc="當她還在世時，安娜絲塔麗會不計代價取得任何她想要的東西。死亡並無讓她有任何改變。她的靈魂被扯離她的軀體使她成為一個女妖，她不再喜愛物質飾品，而偏好更為邪惡的收藏品。",creatures={[1]="安娜絲塔麗男爵夫人"}},[10437]={name="奈幽布恩坎",desc="奈幽布恩坎曾經是蜘蛛之戰中令人畏懼的戰士。最終她的傷勢將她擊垮，而她也被天譴軍團復活成唯命是從的不死生物爪牙。如今這個奈幽如她生前兇猛地守護家園一般，守衛著斯坦索姆的一座通靈塔。",creatures={[1]="奈幽布恩坎"}},[10438]={name="蒼白的瑪勒基",desc="瑪勒基是最先加入詛咒神教的成員之一，他對操控墓地之寒有著驚人的天份。被對力量難以滿足的渴求所驅使，這個法師狂熱地琢磨自己使用黑暗魔法的技巧，對自己被轉化成一名巫妖做好準備。",creatures={[1]="蒼白的瑪勒基"}},[10435]={name="巴瑟拉斯鎮長",desc="巴瑟拉斯是在斯坦索姆的抉擇中，被阿薩斯與其軍隊屠殺的無辜受害者之一。巫妖王後來讓這個前任鎮長從墓中復活，並指揮一群龐大的不死怪物守衛他破滅的家園。",creatures={[1]="巴瑟拉斯鎮長"}},[10439]={name="『暴食者』拉姆斯登",desc="拉姆斯登是天譴軍團中最惡名昭彰的憎惡怪之一，他是用無數屍體縫在一起，並以無止境的飢渴強化的恐怖怪物。這個怪物在天譴軍團侵略斯坦索姆時犯下許多無法形容的暴行。",creatures={[1]="『暴食者』拉姆斯登"}},[10917]={name="奧里爾斯‧瑞文戴爾領主",desc="奧里爾斯的墮落非常急促。因為無法讓他腐化的父親瑞文戴爾男爵得到報應，這名前任聖騎士在死後也無法得到安息。他悲慘地重生為天譴軍團的工具，成為他生前誓言要擊敗的邪惡生物。",creatures={[1]="奧里爾斯‧瑞文戴爾領主"}},[12118]={name="魯西弗隆",creatures={[1]="魯西弗隆"}},[11982]={name="瑪格曼達",creatures={[1]="瑪格曼達"}},[12259]={name="基赫納斯",creatures={[1]="基赫納斯"}},[12057]={name="加爾",creatures={[1]="加爾"}},[12264]={name="沙斯拉爾",creatures={[1]="沙斯拉爾"}},[12056]={name="迦頓男爵",creatures={[1]="迦頓男爵"}},[12098]={name="薩弗隆先驅者",creatures={[1]="薩弗隆先驅者"}},[11988]={name="『焚化者』古雷曼格",creatures={[1]="『焚化者』古雷曼格"}},[12018]={name="管理者埃克索圖斯",creatures={[1]="管理者埃克索圖斯"}},[11502]={name="拉格納羅斯",creatures={[1]="拉格納羅斯"}},[10184]={name="奧妮克希亞",creatures={[1]="奧妮克希亞"}},[12435]={name="狂野的拉佐格爾",creatures={[1]="狂野的拉佐格爾"}},[13020]={name="墮落的瓦拉斯塔茲",creatures={[1]="墮落的瓦拉斯塔茲"}},[12017]={name="幼龍領主勒西雷爾",creatures={[1]="幼龍領主勒西雷爾"}},[11983]={name="費爾默",creatures={[1]="費爾默"}},[14601]={name="埃博諾克",creatures={[1]="埃博諾克"}},[11981]={name="弗萊格爾",creatures={[1]="弗萊格爾"}},[14020]={name="克洛瑪古斯",creatures={[1]="克洛瑪古斯"}},[11583]={name="奈法利安",creatures={[1]="奈法利安"}},[14507]={name="高階祭司溫諾希斯",creatures={[1]="高階祭司溫諾希斯"}},[14517]={name="高階祭司耶克里克",creatures={[1]="高階祭司耶克里克"}},[14510]={name="高階祭司瑪俐",creatures={[1]="高階祭司瑪俐"}},[11382]={name="血領主曼多基爾",creatures={[1]="血領主曼多基爾"}},[15114]={name="加茲蘭卡",creatures={[1]="加茲蘭卡"}},[14509]={name="高階祭司塞卡爾",creatures={[1]="高階祭司塞卡爾"}},[14515]={name="高階祭司阿洛克",creatures={[1]="高階祭司阿洛克"}},[11380]={name="『妖術師』金度",creatures={[1]="『妖術師』金度"}},[14834]={name="哈卡",creatures={[1]="哈卡"}},[15082]={name="格里雷克",creatures={[1]="格里雷克"}},[15083]={name="哈札拉爾",creatures={[1]="哈札拉爾"}},[15084]={name="雷納塔基",creatures={[1]="雷納塔基"}},[15085]={name="烏蘇雷",creatures={[1]="烏蘇雷"}},[15348]={name="庫林納克斯",creatures={[1]="庫林納克斯"}},[15341]={name="拉賈克斯將軍",creatures={[1]="拉賈克斯將軍"}},[15340]={name="莫阿姆",creatures={[1]="莫阿姆"}},[15370]={name="『暴食者』布魯",creatures={[1]="『暴食者』布魯"}},[15369]={name="『狩獵者』阿亞米斯",creatures={[1]="『狩獵者』阿亞米斯"}},[15339]={name="『無疤者』奧斯里安",creatures={[1]="『無疤者』奧斯里安"}},[15263]={name="預言者斯克拉姆",creatures={[1]="預言者斯克拉姆"}},[15511]={name="異種蠍皇族",creatures={[1]="異種蠍皇族"}},[15516]={name="戰地衛士沙爾圖拉",creatures={[1]="戰地衛士沙爾圖拉"}},[15510]={name="不屈的范克里斯",creatures={[1]="不屈的范克里斯"}},[15299]={name="維希度斯",creatures={[1]="維希度斯"}},[15509]={name="哈霍蘭公主",creatures={[1]="哈霍蘭公主"}},[15276]={name="雙子帝王",creatures={[1]="雙子帝王"}},[15517]={name="奧羅",creatures={[1]="奧羅"}},[15727]={name="克蘇恩",creatures={[1]="克蘇恩"}},[15956]={name="阿努比瑞克漢",creatures={[1]="阿努比瑞克漢"}},[15953]={name="大寡婦費琳娜",creatures={[1]="大寡婦費琳娜"}},[15952]={name="梅克絲娜",creatures={[1]="梅克絲娜"}},[15954]={name="『瘟疫使者』諾斯",creatures={[1]="『瘟疫使者』諾斯"}},[15936]={name="『不潔者』海根",creatures={[1]="『不潔者』海根"}},[16011]={name="憎恨者",creatures={[1]="憎恨者"}},[16061]={name="講師拉祖維斯",creatures={[1]="講師拉祖維斯"}},[16060]={name="『收割者』高希",creatures={[1]="『收割者』高希"}},[16065]={name="四騎士",creatures={[1]="四騎士"}},[16028]={name="縫補者",desc="縫補者要跟你玩！",creatures={[1]="縫補者"}},[15931]={name="葛羅巴斯",creatures={[1]="葛羅巴斯"}},[15932]={name="古魯斯",creatures={[1]="古魯斯"}},[15928]={name="泰迪斯",creatures={[1]="泰迪斯"}},[15989]={name="薩菲隆",creatures={[1]="薩菲隆"}},[15990]={name="科爾蘇加德",creatures={[1]="科爾蘇加德"}}},
sections={[11517001]={title="順劈斬",text="奧格弗林特揮舞武器劃出一道大弧線，對面前所有敵人造成額外的物理傷害。"},[11520002]={title="上鉤拳",text="塔拉加曼使出兇殘的上勾拳，造成大量物理傷害並將目標擊退。"},[11520001]={title="火焰新星",text="塔拉加曼爆發出火焰新星，對附近所有敵人造成火焰傷害。"},[11518002]={title="虛弱詛咒",text="耶戈什以虛弱詛咒目標，降低其造成的物理傷害。"},[11518001]={title="獻祭",text="耶戈什以火焰吞噬一名敵人，立即造成火焰傷害，並在一段時間內造成額外的火焰傷害。"},[11519002]={title="毒藥",text="巴札蘭的刀刃塗有毒藥，會對被他擊中的目標造成持續性的自然傷害。"},[11519001]={title="邪惡攻擊",text="巴札蘭使出邪惡攻擊，造成額外的物理傷害。"},[4957]={title="治療之觸",text="安娜科德拉女士治療一名盟友。"},[4956]={title="荊棘光環",text="安娜科德拉女士的荊棘對任何近戰攻擊她的玩家造成自然傷害。"},[4955]={title="德魯伊的睡眠",text="安娜科德拉女士催眠一名玩家，持續15秒。任何敵對的行動將喚醒目標。"},[4954]={title="閃電箭",text="安娜科德拉女士對目前目標丟出一支閃電箭，造成自然傷害。"},[4968]={title="雷霆一擊",text="皮薩斯領主對10碼範圍內的所有玩家造成自然傷害，並使其攻擊間隔時間延長43%，且移動速度降低，持續10秒。"},[4967]={title="治療之觸",text="皮薩斯領主治療一名盟友。"},[4966]={title="德魯伊的睡眠",text="皮薩斯領主將一名玩家催眠15秒。任何敵對的行動將喚醒目標。"},[4965]={title="閃電箭",text="皮薩斯領主對目前目標丟出一支閃電箭，造成自然傷害。"},[4962]={title="考布萊恩領主:毒蛇",text="當考布萊恩領主的生命力上限剩下45%，他會變形成一條毒蛇。"},[4964]={title="放毒",text="考布萊恩領主對一名玩家放毒，每3秒造成自然傷害，持續30秒。"},[4963]={title="毒蛇形態",text="考布萊恩領主變形成一條毒蛇，使近戰傷害提高50點，但攻擊間隔時間延長43%。"},[4958]={title="考布萊恩領主:毒牙之王",text="考布萊恩領主以他的夜精靈形態與敵人進入戰鬥，在戰鬥中測試他們的力量。"},[4961]={title="治療之觸",text="考布萊恩領主治療一名盟友。"},[4960]={title="德魯伊的睡眠",text="考布萊恩領主將一名玩家催眠15秒。任何敵對的行動將喚醒目標。"},[4959]={title="閃電箭",text="考布萊恩領主對目前目標丟出一支閃電箭，造成自然傷害。"},[4969]={title="粉碎猛咬",text="克雷什猛咬目前目標，使其護甲值降低。"},[4970]={title="閃鏈箭",text="斯卡姆以一支會彈跳到其他附近玩家身上的閃電箭攻擊一名玩家，造成自然傷害。閃鏈箭可影響最多3碼。"},[4973]={title="治療之觸",text="瑟芬迪斯領主治療一名盟友。"},[4972]={title="德魯伊的睡眠",text="瑟芬迪斯領主讓一名玩家陷入昏睡，持續15秒。任何對目標有敵意的行為都會喚醒它。"},[4971]={title="閃電箭",text="瑟芬迪斯領主對目前目標丟出一支閃電箭，造成自然傷害。"},[4974]={title="纏繞之藤",text="永生的沃爾丹以藤蔓纏住10碼範圍內的所有玩家，造成物理傷害，並將其擊倒與定身10秒。"},[4977]={title="雷霆震裂",text="『吞噬者』穆坦努斯對10碼範圍內的所有玩家造成自然傷害，並使其昏迷2.5秒。"},[4976]={title="恐嚇",text="『吞噬者』穆坦努斯恐嚇一名玩家，使其因恐懼而逃跑，持續4秒。"},[4975]={title="納拉雷克斯的夢魘",text="『吞噬者』穆坦努斯讓一名玩家陷入昏睡，持續15秒。任何對目標有敵意的行為都會將之喚醒。"},[29777]={title="旋風斬",text="拉克佐憤怒地旋轉，在旋風中攻擊附近的敵人。陷入狂怒時，拉克佐會對附近敵人造成物理傷害，並將其擊退。"},[29112]={title="拉克佐猛擊",text="拉克佐野蠻地槌擊目前目標，造成64到86點物理傷害，並使其昏迷3秒。"},[29804]={title="斯尼德",text="一旦斯尼德的伐木機被摧毀，他就會決定親自出手。"},[29805]={title="繳械",text="斯尼德使目標繳械，強迫其停止揮舞武器，持續6秒。"},[29778]={title="斯尼德的伐木機",text="斯尼德駕駛著致命的削木機。"},[29802]={title="順劈斬",text="斯尼德用其伐木機在廣大的弧形範圍內劈砍，對面前的目標造成物理傷害。"},[29803]={title="擾亂之痛",text="斯尼德朝一個目標發射利刃，造成物理傷害，並使其加速降低35%，持續15秒。"},[29801]={title="恐嚇",text="斯尼德恐嚇一個敵人，使其因恐懼而逃跑，持續4秒。"},[29809]={title="召喚遙控魔像",text="吉尼德叫出工人魔像，隨機攻擊一個目標。"},[29812]={title="遙控魔像",text="這個魔像會隨機攻擊一個目標，並無視嘲諷。"},[29808]={title="熔化礦石",text="吉尼德以熔火礦石覆蓋附近的敵人，每1秒造成7點火焰傷害，並使其移動速度降低40%，持續20秒。此效果可堆疊。"},[29807]={title="熔解的金屬",text="吉尼德投擲熔解的金屬，每3秒對一個敵人造成火焰傷害，使其攻擊間隔時間延長54%，移動速度降低50%，持續15秒。"},[29813]={title="我生氣了",text="生命力達到35%時，重拳先生會踏地，使所有玩家昏迷，並裝備自己的巨錘，提高其造成的傷害，但攻擊速度降低50%。"},[29825]={title="手槍射擊",text="重拳先生朝一個遠方的目標開槍，造成物理傷害。"},[29827]={title="重拳猛擊",text="重拳先生朝當前目標砸下他的巨錘，造成50點物理傷害，並使該目標昏迷3秒。"},[29823]={title="即興表演",text="生命力達到70%時，重拳先生會踏地，使所有玩家昏迷。他隨即雙手各裝備一把掠刃，提高其造成的傷害，並獲得額外的攻擊次數。"},[29826]={title="手槍射擊",text="重拳先生朝一個遠方的目標開槍，造成物理傷害。"},[29818]={title="來決鬥吧",text="重拳先生裝備其盜賊之刃，準備與入侵者決鬥。"},[29822]={title="手槍射擊",text="重拳先生朝一個遠方的目標開槍，造成物理傷害。"},[29821]={title="迅捷反射",text="進入近身戰時，重拳先生有一定機率使其招架機率提高75%，持續8秒。"},[29830]={title="手槍射擊",text="綠皮朝一個遠方的目標開槍，造成物理傷害。"},[29829]={title="順劈斬",text="綠皮對面前的敵人造成物理傷害。"},[29828]={title="毒性魚叉",text="綠皮朝目標投擲淬毒魚叉，造成自然傷害，並在1分鐘內持續造成傷害。"},[29834]={title="范克里夫的盟友",text="生命力達到50%時，范克里夫會向附近躲在暗處的手下求援。"},[29835]={title="迪菲亞黑衣衛",text="范克里夫的手下結夥對付兄弟會的敵人。"},[29831]={title="割裂",text="黑衣衛刺擊目標，每2秒造成15點物理傷害，持續10秒。"},[29832]={title="暗影閃現",text="范克里夫潛入暗影，隨機在一個敵人後方現身，從背後進行刺擊。范克里夫會鎖定其目標。"},[29836]={title="割裂",text="范克里夫刺擊目標，每2秒造成15點物理傷害，持續10秒。"},[29839]={title="酸液濺射",text="餅乾向目標投擲毒藥瓶，每5秒造成自然傷害，持續30秒。"},[29837]={title="餅乾的料理",text="餅乾嚐一口昨天的湯，恢復部分生命力。"},[3914001]={title="靈魂消耗",text="雷希戈爾吸取目前目標的靈魂，削弱其生命力並使其定身，持續10秒。"},[3886001]={title="屠夫吸取",text="拉佐克勞以兇殘的攻擊屠戮敵人，吸取他們的活力，並為自己治療其造成傷害的一部分。"},[3887001]={title="暗影迷霧",text="席瓦萊恩男爵以暗影帷幕籠罩一名玩家，使其受到的所有治療效果降低75%，持續15秒。"},[4278002]={title="制裁之錘",text="指揮官斯普林瓦爾以正義的重量錘擊目前目標，使其昏迷4秒。"},[4278001]={title="聖光術",text="指揮官斯普林瓦爾引導聖光，為自己或一名受傷的盟友恢復大量生命力。"},[4279001]={title="嚎叫之怒",text="當奧杜受傷時——在生命力為75%、50%和25%時——他會陷入嚎叫之怒，體型變大並提高其造成的傷害。每到一個門檻，狂暴都會更加劇烈。"},[4274001]={title="毒性唾液",text="芬魯斯將毒性唾液塗滿一名玩家全身，每6秒造成自然傷害，持續2分鐘。"},[3927001]={title="狼群的呼喚",text="狼王南杜斯召喚他的狼群前來助陣，先後喚出荒狼、被奴役的座狼，最後是暗牙恐狼，以擊潰入侵者。"},[4275004]={title="暗影傳送",text="在整場戰鬥中，阿魯高會在暗影漩渦中消失，並在房間中另一個有利位置重新出現，調整位置後再繼續攻擊。"},[4275003]={title="雷霆震盪",text="阿魯高在自身周圍釋放自然能量震擊，造成自然傷害、擊退附近的玩家，並使其昏迷5秒。"},[4275002]={title="阿魯高的詛咒",text="阿魯高詛咒一名玩家，將其變成受他控制的影牙暴食者，持續10秒。"},[4275001]={title="虛空箭",text="阿魯高朝目標擲出一道虛空能量箭，造成大量暗影傷害。"},[4887001]={title="踐踏",text="加摩拉踐踏周圍的敵人，對附近所有目標造成物理傷害。"},[4831003]={title="減速術",text="薩利維絲女士使一名敵人減速，降低其攻擊速度與移動速度。"},[4831002]={title="冰霜新星",text="薩利維絲女士以冰霜衝擊附近的敵人，使其短時間內凍結在原地。"},[4831001]={title="叉狀閃電",text="薩利維絲女士擲出叉狀閃電，對她面前錐形範圍內的敵人造成自然傷害。"},[6243001]={title="投網",text="格里哈斯特以網捕捉一名敵人，使其定身並無法逃脫。"},[4832002]={title="心靈震爆",text="克爾里斯攻擊一名玩家的心靈，造成暗影傷害。"},[4832001]={title="催眠術",text="暮光領主克爾里斯使附近的敵人陷入沉睡，使其無法行動，直到受到傷害而醒來。"},[4830001]={title="吸血脈衝",text="瑟拉吉斯脈動著吸血能量，吸取附近敵人的生命力來治療自己。"},[4829002]={title="狂暴怒氣",text="阿庫麥爾陷入狂暴的怒火，提高其攻擊速度與造成的傷害。"},[4829001]={title="毒雲術",text="阿庫麥爾噴出一團毒雲，對困在其中的所有敵人造成持續性的自然傷害。"},[6476]={title="咀嚼者",text="咀嚼者與格魯比斯一起戰鬥。"},[4690]={title="打擊",text="格魯比斯對目前目標造成物理傷害。"},[4691]={title="毒性箭雨",text="黏性輻射塵釋放一陣有毒的箭雨，對45碼範圍內的所有玩家造成56點自然傷害，並每3秒造成7點自然傷害，持續15秒。"},[4694]={title="閃鏈箭",text="電刑器6000型以閃電箭攻擊目前目標，並彈跳到3個附近目標身上，對每個目標造成自然傷害。"},[4693]={title="震擊",text="電刑器6000型對目前目標投擲一支閃電箭，造成自然傷害。"},[4692]={title="百萬伏特",text="電刑器6000型對面前所有玩家造成自然傷害。"},[4672]={title="踐踏",text="群體打擊者9-60踐踏10碼範圍內的玩家，造成物理傷害。"},[4671]={title="群體打擊",text="群體打擊者9-60打擊10碼範圍內的玩家，造成物理傷害並中斷施法，持續5秒。"},[4670]={title="圓弧斬",text="群體打擊者9-60劃出一道邪惡的弧光，對在它面前的玩家造成物理傷害。"},[4700]={title="步行炸彈",text="機電師瑟瑪普拉格啟動在附近的炸彈裝置，使其週期性地放出步行炸彈來攻擊隨機玩家。步行炸彈會持續出現，直到有人啟動炸彈裝置側面的紅色開關。"},[4701]={title="引爆",text="步行炸彈在接觸目標時引爆，對10碼範圍內的所有玩家造成200到300點火焰傷害。"},[4704]={title="焊接光束",text="機電師瑟瑪普拉格以焊接光束攻擊目前目標，造成250點自然傷害。"},[4703]={title="猛擊",text="機電師瑟瑪普拉格猛擊目前目標，造成物理傷害並使其暈眩。"},[4702]={title="蒸汽衝擊",text="機電師瑟瑪普拉格用蒸汽衝擊目前目標，造成火焰傷害，並將其擊退。"},[1696002]={title="狂怒",text="生命力降至30%以下時，塔高爾會陷入狂怒，大幅提高其造成的傷害。"},[1696001]={title="痛擊",text="塔高爾瘋狂痛擊，獲得額外的近戰攻擊次數。"},[1666001]={title="盾牌猛擊",text="卡姆·深怒以盾牌猛擊目標，造成物理傷害並使其短暫昏迷。"},[1717002]={title="嗜血術",text="哈姆霍克進入嗜血狀態，提高其攻擊速度。"},[1717001]={title="閃電鏈",text="哈姆霍克釋放一道在附近敵人之間彈跳的閃電，造成自然傷害。"},[1716002]={title="戰鬥怒吼",text="巴基爾·斯瑞德發出戰鬥怒吼，提高附近盟友的攻擊強度。"},[1716001]={title="煙霧彈",text="巴基爾·斯瑞德投擲煙霧彈，使附近的敵人在嗆人的煙霧中昏迷。"},[1663002]={title="破膽怒吼",text="迪克斯特·瓦德發出破膽怒吼，使附近的玩家恐懼逃跑。"},[1663001]={title="打擊",text="迪克斯特·瓦德使出強力打擊，造成額外的物理傷害。"},[6168002]={title="召喚地行者",text="魯古格召喚一個地行者在身旁作戰。"},[6168001]={title="閃電箭",text="魯古格朝目標擲出一道閃電箭，造成自然傷害。"},[4424003]={title="戰鬥怒吼",text="阿葛金‧棘咒以戰鬥怒吼鼓舞盟友，提高他們的攻擊強度。"},[4424002]={title="召喚野豬之魂",text="阿葛金‧棘咒召喚一隻野豬之魂協助他戰鬥。"},[4424001]={title="治療鍊",text="阿葛金‧棘咒召喚自然之力治療自己與附近的盟友，治療能量會在目標之間跳躍。"},[4428002]={title="暗影箭",text="亡語者賈格巴擲出一道暗影箭，造成暗影傷害。"},[4428001]={title="統禦意志",text="亡語者賈格巴支配一名玩家的心智，控制該玩家並使其轉而攻擊盟友。"},[4420002]={title="戰鬥怒吼",text="拉姆塔斯主宰以戰鬥怒吼號召他的戰隊，提高他們的攻擊強度。"},[4420001]={title="雷霆一擊",text="拉姆塔斯主宰重擊地面，對附近的敵人造成自然傷害並降低其攻擊速度。"},[4422003]={title="狂怒",text="阿迦賽羅斯陷入狂怒，提高其造成的傷害。"},[4422002]={title="暴跳如雷",text="阿迦賽羅斯橫衝直撞，以一連串沉重的物理攻擊痛擊目標。"},[4422001]={title="急速衝鋒",text="阿迦賽羅斯衝向一名遠方的敵人，衝撞造成物理傷害。"},[4421003]={title="法力之矛",text="當法力不足時，卡爾加會朝一名玩家釋放能量之矛，造成神聖傷害。"},[4421002]={title="恢復",text="卡爾加對自己或一名受傷的盟友施放恢復，在一段時間內恢復生命力。"},[4421001]={title="閃電鏈",text="卡爾加釋放一道在附近敵人之間彈跳的閃電，造成自然傷害。"},[3983001]={title="獻祭",text="審訊員韋沙斯以獻祭灼燒受害者，以火焰吞噬他們，造成持續性的火焰傷害。"},[4543002]={title="烈焰尖刺",text="血法師薩爾諾斯召喚烈焰尖刺，灼燒範圍內的所有敵人，造成火焰傷害。"},[4543001]={title="暗影箭雨",text="血法師薩爾諾斯釋放暗影箭雨，對附近所有敵人造成暗影傷害。"},[3974002]={title="戰鬥怒吼",text="馴犬者洛克希以戰鬥怒吼激勵他的犬群，提高牠們的攻擊強度。"},[3974001]={title="嗜血術",text="馴犬者洛克希激發獵犬的嗜血狂性，提高牠們的攻擊速度。"},[6487004]={title="魔爆術",text="秘法師杜安釋放秘法能量爆發，對附近所有敵人造成秘法傷害。"},[6487003]={title="沉默",text="秘法師杜安使附近的施法者沉默，使其數秒內無法施法。"},[6487002]={title="變形術",text="秘法師杜安將一名玩家變形為無害的生物，使其無法參與戰鬥，直到效果被打破為止。"},[6487001]={title="自爆",text="秘法師杜安以秘法護罩包圍自己，引導一場席捲整個房間的巨大爆炸，對所有人造成大量秘法傷害。躲到柱子後方才能存活。"},[3975004]={title="狂暴",text="負傷的赫洛德陷入狂暴，大幅提高其攻擊速度。"},[3975003]={title="順劈斬",text="赫洛德對面前所有敵人使出順劈斬，造成大量物理傷害。"},[3975002]={title="急速衝鋒",text="赫洛德衝向一個遠方的目標，拉近距離並對其造成物理傷害。"},[3975001]={title="旋風斬",text="赫洛德捲起致命的旋風，對附近所有敵人造成大量物理傷害。"},[3976002]={title="制裁之錘",text="莫格萊尼以正義的重量錘擊目標，使其短時間昏迷。"},[3976001]={title="十字軍打擊",text="莫格萊尼以強力的十字軍打擊重擊目標，造成大量神聖與物理傷害。"},[3977004]={title="聖光懲擊",text="懷特邁恩以聖光之力懲擊一名敵人，造成神聖傷害。"},[3977003]={title="治療術",text="懷特邁恩引導強力的治療，為自己或莫格萊尼恢復生命力。"},[3977002]={title="深度睡眠",text="懷特邁恩使整個隊伍陷入深度睡眠，趁他們無法行動時復活她倒下的指揮官。"},[3977001]={title="血色復活",text="當血色十字軍指揮官莫格萊尼倒下時，懷特邁恩會復活他，讓她的指揮官重返戰鬥再度發動攻擊。"},[4542005]={title="真言術：盾",text="生命力低於25%時，法爾班克斯會以聖光護盾保護自己，吸收部分受到的傷害。"},[4542004]={title="治療術",text="生命力低於30%時，法爾班克斯會引導強力的治療來恢復自己的生命力。"},[4542003]={title="恐懼術",text="法爾班克斯使附近的玩家心生恐懼，恐懼逃跑。"},[4542002]={title="催眠術",text="法爾班克斯使一名敵人陷入沉睡，使其無法行動，直到受到傷害為止。"},[4542001]={title="血之詛咒",text="法爾班克斯詛咒一名玩家的血液，使其受到的物理傷害提高。"},[4821]={title="閃電箭",text="魯維羅什以閃電衝擊目前目標，造成自然傷害。"},[4820]={title="閃電鏈",text="魯維羅什以一支會彈跳到附近玩家身上的閃電箭攻擊目標，對3個目標造成自然傷害。"},[4872]={title="奧拉夫",text="奧拉夫喜歡防禦，以他的盾牌格擋。"},[4873]={title="盾牌猛擊",text="奧拉夫猛擊目標，造成物理傷害並使其昏迷，持續2秒。"},[4874]={title="迅捷的艾瑞克",text="艾利克偏好速度，會頭在前衝入戰鬥。"},[4875]={title="急速衝鋒",text="迅捷的艾瑞克向一名玩家衝鋒，使他下一次攻擊的傷害提高。"},[4869]={title="貝洛格",text="貝洛格喜歡戰鬥，以他的劍與弓攻擊。"},[4871]={title="射擊",text="貝洛格射擊一名玩家，造成物理傷害。"},[4870]={title="打擊",text="貝洛格攻擊目前目標，造成物理傷害。"},[4878]={title="戰爭踐踏",text="艾隆納亞踐踏地面，對5碼範圍內的所有敵人造成物理傷害，並使其昏迷5秒。"},[4877]={title="擊退",text="艾隆納亞對目前目標造成物理傷害，並將其擊退。"},[4876]={title="圓弧斬",text="艾隆納亞劃出一道邪惡的弧光，對在她面前的所有玩家造成物理傷害。"},[4879]={title="沙塵風暴",text="上古石之守衛者召喚一個會向玩家移動的沙塵風暴，對5碼範圍內地所有玩家造成物理傷害，並使其移動速度降低。"},[4883]={title="影爐地質學家",text="影爐地質學家防衛加加恩‧火錘並在戰鬥中協助他。"},[4885]={title="烈焰鞭笞",text="影爐地質學家燃燒一名玩家，造成火焰傷害並使其火焰抗性降低，持續45秒。此效果最多可堆疊3次。"},[4884]={title="烈焰尖刺",text="影爐地質學家喚來一根火柱，對目標區域5碼範圍內的所有玩家造成火焰傷害，且每3秒造成額外火焰傷害，持續9秒。"},[4882]={title="火焰增效",text="加加恩‧火錘使目前目標從火焰受到的傷害提高，持續30秒。"},[4881]={title="烈焰鞭笞",text="加加恩‧火錘燃燒一名玩家，造成火焰傷害，並使其火焰抗性降低45秒。此效果可堆疊最多3次。"},[4880]={title="火焰新星",text="加加恩‧火錘對10碼範圍內的所有玩家造成火焰傷害。"},[4891]={title="玉脊蜥蜴",text="格瑞姆洛克在他的寵物玉脊蜥蜴協助下進行戰鬥。"},[4893]={title="結晶沉睡",text="玉脊蜥蜴對一名玩家造成秘法傷害，使其昏迷15秒。"},[4892]={title="反射",text="玉脊蜥蜴的皮膚發光，使它有一定機率將有害的法術反射回施法者，持續5秒。"},[4889]={title="縮小術",text="格瑞姆洛克使5碼範圍內的所有玩家縮小，使其力量和耐力降低，持續2分鐘。"},[4888]={title="嗜血術",text="格瑞姆洛克使他的一個盟友攻擊速度提高30%，持續30秒。"},[4887]={title="閃電箭",text="格瑞姆洛克以閃電衝擊目前目標，造成自然傷害。"},[4886]={title="閃鏈箭",text="格瑞姆洛克以一支會彈跳到附近玩家身上的閃電箭攻擊目標，對3個目標造成自然傷害。"},[4902]={title="地面震顫",text="阿札達斯撼動地面，使20碼範圍內的所有敵人昏迷。"},[4899]={title="喚醒寶庫護衛",text="當阿札達斯剩下33%生命力時，他會喚醒2個寶庫護衛。"},[4900]={title="寶庫護衛"},[4901]={title="踐踏",text="寶庫護衛對10碼範圍內的所有敵人造成物理傷害。"},[4896]={title="喚醒土靈守護者",text="當阿札達斯剩下66%生命力時，他會喚醒6個土靈管理者。"},[4897]={title="土靈守護者"},[4898]={title="旋風斬",text="土靈守護者做出旋風斬，造成物理傷害對所有敵人x8碼範圍內的"},[4894]={title="喚醒土靈矮人",text="阿札達斯每10秒喚醒一個土靈管理者協助他戰鬥。"},[4895]={title="土靈管理者",text="土靈管理者協助阿札達斯戰鬥。"},[7355003]={title="惡性毒藥",text="圖特卡什的撕咬帶有惡性毒藥，造成持續性的自然傷害。"},[7355002]={title="撒網",text="圖特卡什對附近的敵人噴灑蛛網，使其定身。"},[7355001]={title="圖特卡什的詛咒",text="圖特卡什詛咒一名玩家，降低其受到的治療效果。"},[7357002]={title="火焰新星",text="莫德雷斯爆發出火焰新星，對附近所有敵人造成火焰傷害。"},[7357001]={title="火球術",text="莫德雷斯朝目標擲出火球，造成火焰傷害。"},[8567003]={title="狂暴",text="生命力低於15%時，暴食者會陷入狂暴，攻擊速度大幅提高。"},[8567002]={title="痛擊",text="暴食者痛擊，獲得額外的近戰攻擊次數。"},[8567001]={title="疾病之雲",text="暴食者散發出疾病之雲，對附近的敵人造成持續性的自然傷害。"},[7356002]={title="枯萎之觸",text="普雷莫爾的觸碰會使受害者枯萎，吸取他們的法力。"},[7356001]={title="腐爛惡臭",text="普雷莫爾散發出腐爛惡臭，以腐爛的疾病削弱附近的敵人。"},[7354004]={title="治療術",text="拉戈斯諾特引導治療術，治癒自己或一名盟友的傷勢。"},[7354003]={title="暗言術：痛",text="拉戈斯諾特使一名玩家承受灼熱的痛苦，造成持續性的暗影傷害。"},[7354002]={title="暗影箭",text="拉戈斯諾特擲出一道暗影箭，造成暗影傷害。"},[7354001]={title="統禦意志",text="拉戈斯諾特支配一名玩家的心智，控制其一段時間。"},[7358003]={title="霜甲術",text="亞門納爾以霜甲術環繞自身，使近戰攻擊他的敵人受到冰凍並減速。"},[7358002]={title="召喚冰霜亡魂",text="生命力達到66%時，亞門納爾會召喚一對冰霜幽靈攻擊敵人。"},[7358001]={title="亞門納爾之怒",text="亞門納爾對一名敵人釋放怒火，造成冰霜傷害。"},[4711]={title="召喚諾克賽恩產物",text="諾克賽恩的身體分裂成5個諾克賽恩產物，使他無法戰鬥最多20秒。一旦所有5個諾克賽恩產物被殺死，諾克賽恩將回到原來的形態。"},[4712]={title="召喚諾克賽恩產物",text="諾克賽恩產物從諾克賽恩的主體中分裂出來。"},[4710]={title="上鉤拳",text="諾克賽恩對目前目標使用上鉤拳，造成物理傷害並將其擊退。"},[4709]={title="毒性箭雨",text="諾克賽恩射出毒性箭雨，立即對45碼範圍內的所有玩家造成自然傷害，同時每3秒造成額外自然傷害，持續15秒。"},[4715]={title="順劈斬",text="銳刺鞭笞者使出順劈斬，對目前目標與其最靠近的盟友造成物理傷害。"},[4714]={title="痛擊",text="銳刺鞭笞者痛擊目前目標，造成兩次額外攻擊。"},[4713]={title="突刺",text="銳刺鞭笞者突刺當前目標，每2秒造成物理傷害，持續10秒。"},[4724]={title="射擊",text="技工吉茲洛克射擊一名隨機玩家，造成物理傷害。"},[4723]={title="閃光雷",text="技工吉茲洛克丟出閃光雷，使5碼範圍內的所有野獸逃跑。"},[4722]={title="哥布林龍槍",text="技工吉茲洛克發射他的哥布林龍槍，對他面前的鎖有玩家造成140點火焰傷害，持續8秒。"},[4721]={title="轟炸",text="技工吉茲洛克對一名玩家投擲炸彈，對5碼範圍內的所有玩家造成火焰傷害。"},[4733]={title="煙霧彈",text="維利塔恩領主投擲一顆煙霧彈，使5碼範圍內的所有玩家昏迷。"},[4732]={title="閃現術",text="維利塔恩領主往前傳送20碼。"},[4731]={title="多重射擊",text="維利塔恩領主對一名隨機玩家發射一陣箭雨，對其與附近盟友造成秘法傷害，影響最多5個目標。"},[4730]={title="射擊",text="維利塔恩領主射擊一名隨機玩家，造成物理傷害。"},[4748]={title="糾纏根鬚",text="被詛咒的塞雷布拉斯綁住目前目標，使其定身並每3秒造成自然傷害，持續10秒。"},[4747]={title="憤怒",text="被詛咒的塞雷布拉斯對目前目標丟出一支能量箭，造成自然傷害。"},[4746]={title="扭曲寧靜",text="被詛咒的塞雷布拉斯對45碼範圍內的所有玩家造成自然傷害，並使其移動速度降低70%，且攻擊間隔時間延長300%。"},[4745]={title="墮落的自然之力",text="被詛咒的塞雷布拉斯召喚3個墮落的自然之力協助他戰鬥，持續1分鐘。"},[6459]={title="墮落的自然之力",text="墮落的自然之力為保衛被詛咒的塞雷布拉斯而戰。"},[4750]={title="崩石流土",text="崩石流土使100碼範圍內的所有玩家昏迷，持續8秒，並每2秒召喚出一個瑟萊德絲裂石者。"},[6460]={title="瑟萊德絲裂石者"},[6461]={title="打擊",text="瑟萊德絲裂石者攻擊玩家，造成物理傷害。"},[4751]={title="踐踏",text="蘭斯利德踐踏10碼範圍內的所有玩家，造成物理傷害。"},[4749]={title="擊退",text="蘭斯利德對目前目標造成物理傷害，並將其擊退。"},[4758]={title="亡命刺痛",text="洛特格里普啃咬當前目標，造成物理傷害，並為其恢復等同於兩倍所造成傷害的生命力上限。"},[4757]={title="突刺",text="洛特格里普突刺目前目標，每2秒造成物理傷害，持續10秒。"},[4762]={title="灰塵力場",text="瑟萊德絲公主撼動地面，對20碼範圍內的所有玩家造成自然傷害，並將他們擊退。"},[4761]={title="投石",text="瑟萊德絲公主對一名隨機目標丟出巨石，造成物理傷害，並中斷施法與使其昏迷2秒。"},[4760]={title="憎恨怒視",text="瑟萊德絲公主凝視目前目標，並使8碼範圍內地所有玩家恐懼，持續8秒。"},[4759]={title="痛擊",text="瑟萊德絲公主使出痛擊，造成2次額外攻擊。"},[29864]={title="殉難者詛咒",text="塞卡隨機詛咒一個目標，將其變成一隻甲蟲，然後敲響迫害響鐘，吸引附近甲蟲的注意。"},[29863]={title="暗言術：痛",text="塞卡吟誦黑暗的咒語，每3秒對一名敵人造成48點暗影傷害，持續18秒。"},[29862]={title="暗影箭雨",text="塞卡射出多支黑暗魔法箭，對附近敵人造成128到172點暗影傷害。"},[5006]={title="暗影變形",text="生命力剩餘30%時，『殉教者』塞卡會變形，提高自身對物理和暗影傷害的抗性，持續30秒。"},[5005]={title="熱疫",text="『殉教者』塞卡使用瘟疫感染一名玩家，造成自然傷害，並且每5秒造成更多傷害，持續3分鐘。"},[4980]={title="淹擊波",text="水占師維蕾薩召喚颱風，對面前的所有玩家造成冰霜傷害，並將其擊退。"},[4979]={title="水箭",text="水占師維蕾薩向一名玩家射出水箭，造成冰霜傷害。"},[4978]={title="治療波",text="水占師維蕾薩為一名盟友治療694到806點生命力。"},[4992]={title="安圖蘇爾的僕從",text="生命力剩餘75%和25%時，安圖蘇爾會召喚安圖蘇爾的僕從來協助他戰鬥。"},[4993]={title="僵化",text="安圖蘇爾的僕從會使一名玩家昏迷8秒，但護甲值提高30%。"},[4991]={title="安圖蘇爾的治療波",text="生命力剩餘25%時，安圖蘇爾會治療自己。"},[4990]={title="閃電鏈",text="安圖蘇爾以閃電箭攻擊一名敵人，閃電會彈向附近的其他玩家，造成185到215點自然傷害，並跳向附近最多3名敵人。"},[4989]={title="大地震擊",text="安圖蘇爾電擊一名玩家，造成164到180點自然傷害並中斷施法，持續2秒。"},[4988]={title="陷地圖騰",text="安圖蘇爾在腳下召喚一個陷地圖騰，持續30秒。陷地圖騰每5秒使10碼內的所有玩家無法移動，持續4秒，直到被摧毀為止。"},[4987]={title="治療結界",text="安圖蘇爾在腳下召喚一個強效治療結界，持續30秒。強效治療結界每3秒治療10碼內安圖蘇爾的所有盟友，直到被摧毀為止。"},[4986]={title="治療波",text="安圖蘇爾為一名盟友治療694到806點生命力。"},[5017]={title="暗影箭雨",text="巫醫祖穆拉恩擲出黑暗魔法飛彈，對30碼內的所有玩家造成128到172點暗影傷害。"},[5016]={title="暗影箭",text="巫醫祖穆拉恩向一名玩家射出黑暗魔法箭，造成128到172點暗影傷害。"},[5015]={title="治療波",text="巫醫祖穆拉恩為一名盟友治療694到806點生命力。"},[5013]={title="祖穆拉恩結界",text="巫醫祖穆拉恩在腳邊召喚出祖穆拉恩結界，持續20秒。祖穆拉恩結界每5秒召喚出一具祖穆拉恩骷髏。"},[5014]={title="祖穆拉恩骷髏",text="祖穆拉恩骷髏為巫醫祖穆拉恩戰鬥。"},[5011]={title="喚醒祖爾法拉克殭屍",text="巫醫祖穆拉恩從附近的墳墓復活一個祖爾法拉克殭屍。"},[5012]={title="祖爾法拉克殭屍",text="祖爾法拉克殭屍從墳墓中復活，為巫醫祖穆拉恩而戰。"},[4983]={title="加茲瑞拉猛擊",text="加茲瑞拉踐踏地面，對20碼內的所有玩家造成物理傷害，並將其擊飛。"},[4982]={title="冰霜凝固",text="加茲瑞拉冰凍一名玩家，將其擊昏，且每3秒造成冰霜傷害，持續10秒。"},[4981]={title="冰柱",text="加茲瑞拉發射一支寒冰箭，對一名隨機玩家造成冰霜傷害，使其移動速度降低50%，持續10秒。"},[5020]={title="暗影祭司塞瑟斯"},[5024]={title="治療術",text="暗影祭司塞瑟斯為一名盟友治療590到684點生命力。"},[5023]={title="恢復",text="暗影祭司塞瑟斯對一名盟友使用恢復，每3秒使其恢復部分生命力，持續20秒。"},[5022]={title="心靈尖嘯",text="暗影祭司塞瑟斯發出心靈尖嘯，使8碼範圍內的所有玩家逃跑，持續6秒。"},[5021]={title="暗影箭",text="暗影祭司塞瑟斯向一名玩家射出黑暗魔法箭，造成128到172點暗影傷害。"},[5019]={title="耐克倫‧嚼腸者"},[29720]={title="順劈斬",text="耐克倫‧嚼腸者對面前的敵人造成物理傷害。"},[5018]={title="熱疫",text="耐克倫‧嚼腸者使用瘟疫感染一名玩家，造成自然傷害，並且每5秒造成更多傷害，持續3分鐘。"},[29882]={title="盧茲魯"},[29884]={title="狂怒",text="當烏克茲死亡時，盧茲魯會陷入狂怒，提高其造成的傷害與攻擊速度。"},[29887]={title="順劈斬",text="盧茲魯對面前最多2個敵人造成物理傷害。"},[29886]={title="斬殺",text="盧茲魯嘗試斬殺受傷的敵人，對生命力低於20%的目標造成大量物理傷害。"},[29888]={title="烏克茲‧沙頂"},[29885]={title="狂怒",text="當盧茲魯死亡時，烏克茲會陷入狂怒，提高其造成的傷害與攻擊速度。"},[5027]={title="狂亂",text="烏克茲‧沙頂進入狂暴狀態，提高其攻擊速度，持續2分鐘。"},[5026]={title="順劈斬",text="烏克茲‧沙頂對面前的敵人造成物理傷害。"},[5025]={title="揮砍",text="烏克茲‧沙頂對他面前所有玩家造成物理傷害。"},[10506003]={title="飛撲",text="基爾圖諾斯朝目標俯衝，造成物理傷害並使其短暫昏迷。"},[10506002]={title="龍翼攻擊",text="基爾圖諾斯以翅膀拍擊前方區域，造成物理傷害並將玩家擊退。"},[10506001]={title="眼之詛咒",text="基爾圖諾斯以眼之詛咒詛咒一名玩家，將其變為幽魂形態，並在一段時間內剝奪其技能。"},[10503003]={title="女妖哀嚎",text="詹迪斯對一名敵人發出女妖哀嚎，造成大量暗影傷害。"},[10503002]={title="血之詛咒",text="詹迪斯詛咒一名玩家的血液，使其受到的物理傷害提高。"},[10503001]={title="幻象",text="詹迪斯隱身並召喚出大量幻象分身。團隊必須從中找出真正的詹迪斯並加以攻擊。"},[11622002]={title="戰爭踐踏",text="血骨傀儡以碎骨之力踐踏地面，使附近所有玩家昏迷。"},[11622001]={title="順劈斬",text="血骨傀儡的巨刃對面前所有敵人使出順劈斬，造成巨額物理傷害。"},[10433003]={title="狂暴",text="馬杜克陷入狂暴，提高其攻擊速度與造成的傷害。"},[10433002]={title="順劈斬",text="馬杜克對面前所有敵人使出順劈斬，造成大量物理傷害。"},[10433001]={title="旋風斬",text="黑衣守衛馬杜克捲起旋風，對附近所有玩家造成物理傷害。"},[10432002]={title="狂暴",text="維克圖斯陷入狂暴，大幅提高其攻擊速度。"},[10432001]={title="火焰之盾",text="維克圖斯以火焰之盾環繞自身，對任何近戰攻擊他的敵人造成火焰傷害。"},[10508003]={title="恐懼術",text="萊斯·霜語使團隊心生恐懼，讓附近的玩家恐懼逃跑。"},[10508002]={title="冰凍新星",text="萊斯·霜語釋放冰凍新星，對附近玩家造成冰霜傷害並將其凍結在原地。"},[10508001]={title="寒冰箭",text="萊斯·霜語朝目標擲出寒冰箭，造成冰霜傷害並使其減速。"},[10505004]={title="恢復",text="講師瑪麗希亞對自己或一名盟友施放恢復，在一段時間內恢復生命力。"},[10505003]={title="精神鞭笞",text="講師瑪麗希亞鞭笞一名玩家的心靈，在引導期間造成暗影傷害並使其減速。"},[10505002]={title="痛苦詛咒",text="講師瑪麗希亞以痛苦詛咒一名玩家，造成持續且逐漸增強的暗影傷害。"},[10505001]={title="快速治療",text="講師瑪麗希亞施放快速治療，恢復自己或一名盟友的生命力。"},[11261004]={title="狂暴",text="卡斯迪諾夫陷入狂暴，以大幅提高的攻擊速度屠戮團隊。"},[11261003]={title="順劈斬",text="卡斯迪諾夫對面前所有敵人使出順劈斬，造成大量物理傷害。"},[11261002]={title="反手一擊",text="卡斯迪諾夫反手一擊打中目標，造成物理傷害並使其短暫昏迷。"},[11261001]={title="撕裂",text="赤紅外科醫師撕裂目標，造成物理傷害並使其持續流血。"},[10901002]={title="黑暗瘟疫",text="普克爾特以黑暗瘟疫折磨一名玩家，這種疾病會逐漸惡化並造成持續性的自然傷害。"},[10901001]={title="快速傳染",text="普克爾特以不穩定的疾病感染一名玩家，造成持續性的自然傷害。"},[10507003]={title="擊倒",text="拉文尼亞將目標擊倒在地，使其短暫昏迷。"},[10507002]={title="順劈斬",text="拉文尼亞對面前所有敵人使出順劈斬，造成大量物理傷害。"},[10507001]={title="踐踏",text="拉文尼亞踐踏周圍的玩家，對附近所有目標造成物理傷害。"},[10504003]={title="暗影震擊",text="阿萊克斯·巴羅夫領主以暗影能量衝擊附近的敵人，造成暗影傷害。"},[10504002]={title="獻祭",text="阿萊克斯·巴羅夫領主以火焰吞噬一名敵人，立即造成火焰傷害，並在一段時間內造成額外的火焰傷害。"},[10504001]={title="暗影迷霧",text="阿萊克斯·巴羅夫領主以暗影帷幕籠罩一名玩家，大幅降低其受到的治療效果。"},[10502004]={title="暗影震擊",text="伊露希亞·巴羅夫女士以暗影能量衝擊附近的敵人，造成暗影傷害。"},[10502003]={title="恐懼術",text="伊露希亞·巴羅夫女士使團隊心生恐懼，讓附近的玩家恐懼逃跑。"},[10502002]={title="沉默",text="伊露希亞·巴羅夫女士使附近的施法者沉默，使其數秒內無法施法。"},[10502001]={title="痛苦詛咒",text="伊露希亞·巴羅夫女士以痛苦詛咒一名玩家，造成持續且逐漸增強的暗影傷害。"},[1853004]={title="暗影之盾",text="加丁以暗影之盾包裹自身，對任何近戰攻擊他的敵人造成暗影傷害。"},[1853003]={title="秘法飛彈",text="加丁朝目標引導一連串秘法飛彈，造成秘法傷害。"},[1853002]={title="黑暗主宰詛咒",text="加丁詛咒一名玩家，以黑暗魔法削弱其力量。"},[1853001]={title="暗影之門",text="黑暗院長加丁透過暗影之門將一名隨機玩家放逐到其中一間側邊教室，並將其與一名致命的召喚敵人一同封閉在內，直到該敵人被殺死為止。"},[4633]={title="暗影之盾",text="高階審問者格斯塔恩將她自己包覆在一層黑暗護盾之內，吸收傷害，持續30秒。"},[4632]={title="暗言術：痛",text="高階審問者格斯塔恩對一名玩家使用暗言術：痛。暗言術：痛每3秒造成一次暗影傷害，持續18秒。"},[4631]={title="心靈尖嘯",text="高階審問者格斯塔恩使8碼範圍內的所有玩家因恐懼而逃跑，持續6秒。"},[4630]={title="法力燃燒",text="高階審問者格斯塔恩對一名玩家造成暗影傷害，並吸收其一部分的法力。"},[4474]={title="烈焰震擊",text="洛考爾領主對一名玩家造成火焰傷害。烈焰震擊將繼續燃燒該名玩家，每3秒造成火焰傷害，持續12秒。"},[4473]={title="大地震擊",text="洛考爾領主對一名玩家造成自然傷害並中斷任何其正在施放的法術。"},[4472]={title="地面震顫",text="洛考爾領主使20碼範圍內的所有玩家昏迷2秒。"},[4629]={title="快跑!快跑!",text="馴犬者格雷布瑪爾會在生命力上限低於15%的時候逃跑。"},[6439]={title="嗜血術",text="馴犬者格雷布瑪爾使一名盟友進入狂亂狀態，使其攻擊速度提高30%，持續30秒。"},[4628]={title="拳擊",text="馴犬者格雷布瑪爾對一名玩家造成物理傷害，並中斷任何施法，持續5秒。"},[4627]={title="挫志怒吼",text="馴犬者格雷布瑪爾使10碼範圍內的所有玩家攻擊強度降低，持續30秒。"},[4626]={title="雙武器",text="馴犬者格雷布瑪爾雙手各拿著一把武器。"},[4547]={title="接受審判!",text="裁決者格里斯通在秩序競技場中宣判玩家死刑。玩家必須面對隨機選中的怪物並擊敗他們才能繼續。"},[4567]={title="最後裁決!",text="裁決者格里斯通派出一個最後的怪物與玩家戰鬥。"},[4565]={title="『修行者』高羅什"},[4607]={title="致死打擊",text="『修行者』高羅什對一名玩家造成物理傷害。致死打擊使被影響的玩家受到的治療效果降低50%，持續5秒。"},[4606]={title="嗜血術",text="『修行者』高羅什使他的近戰攻擊速度提高30%，持續30秒。"},[4605]={title="旋風斬",text="『修行者』高羅什對8碼範圍內的所有玩家造成物理傷害。"},[4604]={title="雙武器",text="『修行者』高羅什雙手各拿著一把武器。"},[4564]={title="『蠕行者』赫杜姆"},[4616]={title="麻痺之毒",text="『蠕行者』赫杜姆使一名玩家昏迷8秒。"},[4615]={title="癲狂",text="『蠕行者』赫杜姆會週期性地將目前目標的威脅值設為零。"},[4614]={title="蛛網爆炸",text="『蠕行者』赫杜姆使30碼範圍內的所有玩家定身10秒。"},[4613]={title="禍害之毒",text="『蠕行者』赫杜姆對一名玩家造成自然傷害。禍害之毒會繼續對被影響的玩家每5秒造成自然傷害，持續2分鐘。禍害之毒可堆疊最多3次。"},[4563]={title="『破壞者』奧科索爾"},[4603]={title="變形術",text="『破壞者』奧科索爾將一名玩家變形成綿羊，持續20秒。"},[4602]={title="減速術",text="『破壞者』奧科索爾使20碼範圍內的所有玩家近戰與遠程攻擊速度、施法速度與移動速度降低，持續10秒。攻擊速度與施法速度降低54%。移動速度降低60%。"},[4601]={title="魔爆術",text="『破壞者』奧科索爾對30碼範圍內的所有玩家造成秘法傷害。"},[4600]={title="秘法箭",text="『破壞者』奧科索爾對一名玩家造成秘法傷害。"},[4562]={title="剔骨者"},[4599]={title="暗影箭雨",text="剔骨者對30碼範圍內的所有玩家造成暗影傷害。"},[4598]={title="邪惡撕裂",text="剔骨者邪惡地撕裂一名玩家，每3秒造成物理傷害，持續15秒。"},[4597]={title="反魔法護盾",text="剔骨者將自己包覆在反魔法護盾之內阻擋所有魔法傷害，持續10秒。"},[4561]={title="阿努希爾"},[4612]={title="虛弱詛咒",text="阿努希爾使一名玩家造成的物理傷害降低，持續2分鐘。"},[4611]={title="放逐術",text="阿努希爾將一名玩家放逐到虛無之中。在被放逐時，玩家對所有攻擊與法術免疫;但無法執行任何行動。"},[4610]={title="惡魔護甲",text="阿努希爾被惡魔能量保護。惡魔護甲使阿努希爾的護甲值、暗影抗性與生命力恢復速度提高。"},[4609]={title="包圍之網",text="阿努希爾將一名玩家困在網中，持續8秒。包圍之網會防止所有法術的施放，使被影響的玩家定身，並使其近戰攻擊速度降低100%。"},[4608]={title="語言詛咒",text="阿努希爾強迫30碼範圍內的所有玩家用惡魔語說話，使其施法速度降低50%，持續15秒。"},[4596]={title="暗影箭",text="阿努希爾對一名玩家造成暗影傷害。"},[4560]={title="格里茲爾"},[4595]={title="地面震顫",text="格里茲爾使20碼範圍內的所有玩家昏迷2秒。"},[4594]={title="順劈斬",text="格里茲爾對一名玩家與鄰近的玩家造成物理傷害。"},[4593]={title="狂亂",text="當格里茲爾剩下50%生命力時，他的近戰攻擊速度將會提高，持續2分鐘。"},[4566]={title="開場致詞",text="裁決者格里斯通首先會選擇一種隨機怪物和玩家在秩序競技場中戰鬥。兩波同樣的怪物將攻擊玩家。可能會出現的怪物為以下幾種。"},[4559]={title="洞穴爬蛛"},[4592]={title="慢性毒藥",text="洞穴爬蛛讓30碼範圍內的所有玩家染上慢性毒藥，持續5分鐘。慢性毒藥會使受影響玩家所受物理傷害提高30%。"},[4591]={title="蛛網",text="洞穴爬蛛使一名玩家定身10秒。"},[4590]={title="放毒",text="洞穴爬蛛會使任何受到牠近戰攻擊的玩家中毒。放毒每3秒對受到影響的玩家造成自然傷害，持續30秒。"},[4558]={title="掘泥蟲"},[4583]={title="病弱",text="掘泥蟲使30碼範圍內的所有玩家的所有屬性降低25%，持續5分鐘。"},[4582]={title="放毒",text="掘泥蟲每3秒對一名玩家造成自然傷害，持續30秒。"},[4581]={title="毒液噴吐",text="掘泥蟲對一名玩家造成自然傷害。毒液噴吐將繼續每5秒對受影響的玩家造成自然傷害，持續10秒。"},[4557]={title="黑暗尖嘯者"},[4580]={title="聽覺震盪",text="黑暗尖嘯者使30碼範圍內的所有玩家施法速度降低35%，持續5分鐘。"},[4579]={title="音爆",text="黑暗尖嘯者對10碼範圍內的所有玩家造成物理傷害，並防止其施法10秒。"},[4556]={title="深淵釘刺者"},[4578]={title="倒鉤之刺",text="深淵釘刺者使30碼範圍內的所有玩家近戰攻擊速度降低54%，持續5分鐘。"},[4577]={title="減速毒藥",text="深淵釘刺者對受到牠近戰攻擊命中的玩家造成減速毒藥效果。減速毒藥使玩家的近戰攻擊速度降低25%，並降低其移動速度，持續25秒。"},[4576]={title="順劈斬",text="深淵釘刺者對一名玩家及鄰近的目標造成物理傷害。"},[4555]={title="鑽孔甲蟲"},[4575]={title="腐爛蛋白",text="鑽孔甲蟲使30碼範圍內的玩家所受自然傷害和暗影傷害提高50%，持續5分鐘。"},[4574]={title="刺穿護甲",text="鑽孔甲蟲使一名玩家的護甲值降低50%，持續20秒。"},[4548]={title="洞穴雷霆蜥蜴"},[4551]={title="分離",text="洞穴雷霆蜥蜴對30碼範圍內的玩家造成分離效果。分離效果會使玩家受到的火焰、冰霜與秘法傷害提高50%，持續5分鐘。"},[4550]={title="雷霆一擊",text="洞穴雷霆蜥蜴對10碼範圍內的所有玩家造成自然傷害。雷霆一擊使玩家的近戰攻擊速度降低33%，移動速度降低55%，持續10秒。"},[4549]={title="蜥蜴之矢",text="洞穴雷霆蜥蜴對一名玩家造成自然傷害。"},[4500]={title="防護火焰結界",text="火占師羅格雷恩保護他自己抵抗火焰傷害，持續1分鐘或直到防護火焰結界吸收了太多火焰傷害。"},[4499]={title="熔岩爆裂",text="火占師羅格雷恩對一名玩家造成火焰傷害。"},[4498]={title="烈焰震擊",text="火占師羅格雷恩對一名玩家造成火焰傷害。烈焰震擊將繼續燃燒該名玩家，每3秒造成火焰傷害，持續12秒。"},[4496]={title="灼燒圖騰",text="火占師羅格雷恩在腳邊召喚出灼燒圖騰來攻擊玩家，持續35秒。"},[4497]={title="灼燒",text="灼燒圖騰對一名玩家造成火焰傷害。"},[4479]={title="元素之王的詛咒",text="伊森迪奧斯領主使45碼範圍內的所有玩家之火焰抗性降低100點，持續1分鐘。此效果最多可堆疊3次。"},[4478]={title="全力一擊",text="伊森迪奧斯領主對一名玩家造成物理傷害並將其擊退。"},[4477]={title="火焰爆發",text="伊森迪奧斯領主選擇一個直徑20碼的區域，對其中的所有玩家造成火焰傷害。"},[4476]={title="火焰風暴",text="伊森迪奧斯領主選擇一個直徑10碼的區域，對其中的所有玩家造成火焰傷害。火焰風暴將對該區域內的所有玩家每3秒造成火焰傷害，持續30秒。"},[6455]={title="維雷克"},[6458]={title="狂怒",text="當維雷克的生命力上限剩下25%，他會進入狂怒狀態，使其物理傷害和攻擊速度提高，持續2分鐘。"},[6457]={title="痛擊",text="維雷克做出痛擊，額外攻擊兩次。"},[6456]={title="血之詛咒",text="維雷克詛咒一名玩家，使其從所有來源受到的物理傷害提高10分鐘。"},[4390]={title="防護冰霜結界",text="護衛斯迪爾基斯以護盾保護他自己抵抗冰霜傷害，持續1分鐘或直到防護冰霜結界吸收了太多冰霜傷害。"},[4388]={title="霜甲術",text="護衛斯迪爾基斯用霜甲保護自己，使其護甲提高，並讓近戰攻擊到他的人遭到冰凍。"},[4389]={title="冰凍",text="霜甲術使近戰攻擊護衛斯迪爾基斯的玩家冰凍。被冰凍的玩家移動速度降低30%，攻擊速度降低25%。冰凍持續5秒。"},[4387]={title="寒冰箭",text="護衛斯迪爾基斯對一名玩家造成冰霜傷害。寒冰箭會使該名玩家的移動速度降低50%，持續4秒。"},[4386]={title="冰霜新星",text="護衛斯迪爾基斯對10碼範圍內的玩家造成冰霜傷害。被冰霜新星傷害的玩家將被定身8秒。"},[4542]={title="清算聖印",text="弗諾斯‧達克維爾為他自己或一名盟友祝福，使其在每一次近戰攻擊對玩家造成傷害時能恢復生命力。清算聖印持續30秒。"},[4541]={title="腳踢",text="弗諾斯‧達克維爾對一名玩家造成物理傷害，並中斷任何正在施放的法術。"},[4540]={title="聖光術",text="弗諾斯‧達克維爾治療他自己或一名盟友。"},[4539]={title="虔誠光環",text="虔誠光環使弗諾斯‧達克維爾與在30碼範圍內任何盟友的護甲值提高1080點。"},[4538]={title="神聖打擊",text="弗諾斯‧達克維爾對一名玩家造成神聖傷害。"},[4533]={title="召喚貝爾加的產物",text="貝爾加對一個隨機地點內的索有玩家造成火焰傷害，並召喚一個貝爾加的產物協助他戰鬥。"},[4648]={title="貝爾加的產物",text="貝爾加的產物會在戰鬥中防衛貝爾加。"},[4532]={title="岩漿噴濺",text="近戰攻擊貝爾加的玩家將每3秒受到火焰傷害，持續30秒。岩漿噴濺可堆疊最多3次。"},[4511]={title="入侵警報!",text="安格弗將軍在生命力上限剩下40%時呼叫援軍，召喚出幾名鐵怒預備兵和鐵怒醫護兵來協助他。"},[4517]={title="鐵怒醫護兵"},[4518]={title="快跑!",text="鐵怒醫護兵在剩下15%生命力時會逃離玩家。"},[4522]={title="真言術：韌",text="鐵怒醫護兵使一名盟友的耐力提高39點。"},[4521]={title="心靈震爆",text="鐵怒醫護兵對一名玩家造成暗影傷害。"},[4520]={title="治療禱言",text="鐵怒醫護兵治療30碼範圍內的所有盟友。"},[4519]={title="治療術",text="鐵怒醫護兵治療一名盟友。"},[4512]={title="鐵怒預備兵",text="鐵怒預備兵協助安格弗將軍。"},[4516]={title="戰鬥怒吼",text="鐵怒預備兵使附近的盟友攻擊強度提高208點，持續2分鐘。"},[4515]={title="射擊",text="鐵怒預備兵從遠距對一名玩家造成物理傷害。"},[4514]={title="斷筋",text="鐵怒預備兵對一名玩家造成物理傷害，並使其移動速度降低60%，持續10秒。"},[4513]={title="打擊",text="鐵怒預備兵對一名玩家造成物理傷害。"},[4510]={title="狂怒",text="安格弗將軍每次被近戰攻擊造成致命一擊時會進入狂怒狀態。狂怒使安格弗將軍造成的物理傷害提高55點，且近戰攻擊速度提高30%。狂怒持續5秒。"},[4509]={title="亂舞",text="每當安格弗將軍對一名玩家造成致命一擊時，他將獲得30%近戰加速。亂舞可堆疊最多3次，持續15秒。"},[4508]={title="破甲攻擊",text="安格弗將軍使玩家的護甲降低，持續30秒，使他們所受物理傷害提高。"},[4503]={title="閃電之盾",text="魔像領主阿格曼奇用3顆閃電球包圍自己。閃電之盾有50%的機率會反擊玩家所做的任何攻擊。反擊時，閃電之盾造成自然傷害並消耗一顆閃電球。直到消耗所有閃電球，閃電之盾才會消失。"},[4502]={title="震擊",text="魔像領主阿格曼奇對一名玩家造成自然傷害。"},[4501]={title="閃電鏈",text="魔像領主阿格曼奇對一名玩家造成自然傷害。閃電鏈會跳至附近15碼範圍內的一名玩家，再次造成自然傷害。閃電鏈最多可擊中5個目標。"},[4495]={title="醉酒怒氣",text="霍爾雷‧黑息使他的攻擊速度提高50%，造成的物理傷害也會提高。此效果持續15秒。"},[4494]={title="火息術",text="霍爾雷‧黑息對面前錐形範圍內的所有敵人造成火焰傷害。"},[4506]={title="火球箭雨",text="法拉克斯對20碼範圍內的所有玩家造成火焰傷害。"},[4505]={title="雷霆一擊",text="法拉克斯對10碼範圍內的所有玩家造成自然傷害。雷霆一擊使所有其擊中的玩家近戰攻擊速度降低33%，移動速度降低57%，持續10秒。"},[4504]={title="全力一擊",text="法拉克斯對一名玩家造成物理傷害並將其擊退。"},[4490]={title="放逐術",text="普拉格‧史帕齊林將一名玩家放逐到虛無之中。被放逐的玩家無法做出任何行動，且對所有攻擊和法術免疫。"},[4489]={title="語言詛咒",text="普拉格‧史帕齊林詛咒一名玩家，使其說惡魔語。受到語言詛咒的玩家施法速度降低50%，持續15秒。"},[4488]={title="惡魔護甲",text="普拉格‧史帕齊林被惡魔能量所保護。惡魔護甲使普拉格‧史帕齊林的護甲值、暗影抗性與生命力恢復速度提高。"},[4487]={title="獻祭",text="普拉格‧史帕齊林對一名玩家造成火焰傷害。獻祭每3秒對該名玩家繼續造成火焰傷害，持續21秒。"},[4486]={title="暗影箭",text="普拉格‧史帕齊林對一名玩家造成暗影傷害。"},[4485]={title="黑鐵酒吧之主",text="普拉格‧史帕齊林帶著黑鐵酒吧的鑰匙。如果玩家從普拉格‧史帕齊林身上偷竊，他會警告所有的顧客來攻擊玩家。這會使黑鐵酒吧中所有顧客從中立變成敵對。"},[4484]={title="火焰衝擊",text="弗萊拉斯大使對他近戰擊中的玩家造成220到260點火焰傷害。"},[4482]={title="燃靈",text="燃靈會從位於弗萊拉斯大使房間邊緣的7個烈焰符文生成。燃靈會朝向弗萊拉斯大使移動，並施放燃靈術。"},[4483]={title="燃靈",text="當燃靈術進入到弗萊拉斯大使1碼範圍內時會犧牲自己，給予他燃靈術效果。\n燃靈術效果會提高弗萊拉斯大使造成的傷害，並使其體型增大。燃靈術最多可堆疊50次。"},[4397]={title="杜姆雷爾"},[4434]={title="暗影箭雨",text="杜姆雷爾對30碼範圍內的所有玩家造成暗影傷害。"},[4433]={title="獻祭",text="杜姆雷爾對一名玩家造成火焰傷害。獻祭每3秒對該名玩家繼續造成火焰傷害，持續21秒。"},[4432]={title="惡魔護甲",text="杜姆雷爾被惡魔能量所保護。惡魔護甲使杜姆雷爾的護甲值、暗影抗性與生命力恢復速度提高。"},[6440]={title="虛弱詛咒",text="杜姆雷爾詛咒一名玩家，使其造成的物理傷害降低，持續2分鐘。"},[4431]={title="放逐術",text="杜姆雷爾將一名玩家放逐到虛無之中。被放逐的玩家無法移動或行動，且其他玩家或怪物無法與其互動。放逐術持續15秒。"},[4430]={title="虛無行者",text="杜姆雷爾召喚三個虛無行者協助他戰鬥。"},[4396]={title="黑特雷爾"},[4429]={title="亂舞",text="每當黑特雷爾對一名玩家造成致命一擊時，她將獲得30%近戰加速。亂舞可堆疊最多3次並持續15秒。"},[4428]={title="暗影之盾",text="黑特雷爾以黑暗之盾圍繞她自己，吸收傷害，持續30秒。"},[4427]={title="打擊",text="黑特雷爾以她的武器對一名玩家造成額外物理傷害。"},[4426]={title="暗影箭",text="黑特雷爾對一名玩家造成暗影傷害。"},[4395]={title="瓦勒雷爾"},[4425]={title="心靈震爆",text="瓦勒雷爾對一名玩家造成暗影傷害。"},[4424]={title="真言術:盾",text="瓦勒雷爾保護他自己或一名盟友避免受到更多傷害。有護盾的目標施法將不會被中斷。真言術:盾持續30秒或直到它吸收了太多傷害。"},[4423]={title="治療禱言",text="瓦勒雷爾治療他自己與30碼範圍內任何他的盟友。"},[4422]={title="治療術",text="瓦勒雷爾治療他自己或他的盟友。"},[4394]={title="格魯雷爾"},[4421]={title="魯莽",text="格魯雷爾在剩下25%生命力時獲得魯莽，此效果持續15秒。\n魯莽使格魯雷爾造成致命一擊的機率提高100%。\n魯莽使格魯雷爾的護甲值降低35%。\n魯莽使格魯雷爾對恐懼免疫。"},[4420]={title="癲狂",text="格魯雷爾在剩下66%及33%生命力時將會把他目前的目標威脅值設為零。"},[4419]={title="斷筋",text="格魯雷爾使一名玩家的移動速度降低60%，持續10秒。"},[4418]={title="致死打擊",text="格魯雷爾對一名玩家造成物理傷害，並使其受到的治療效果降低50%，持續5秒。"},[4417]={title="順劈斬",text="格魯雷爾對他面前的玩家造成物理傷害。"},[4393]={title="多普雷爾"},[4416]={title="閃避",text="多普雷爾在剩下25%生命力時獲得閃避。閃避使多普雷爾閃躲機率提高50%，持續15秒。"},[4415]={title="割裂",text="多普雷爾使一名玩家流血，每2秒造成物理傷害，持續10秒。"},[4414]={title="鑿擊",text="多普雷爾以此攻擊使一名玩家癱瘓。多普雷爾只能對正面面對他的玩家使用此技能。"},[4413]={title="背刺",text="當多普雷爾從背後攻擊一名玩家時將造成大量的物理傷害。"},[4412]={title="邪惡攻擊",text="多普雷爾以此攻擊對一名玩家造成額外物理傷害。"},[4411]={title="雙武器",text="多普雷爾雙手各拿著一把匕首。"},[4392]={title="西斯雷爾"},[4410]={title="冰錐術",text="西斯雷爾對她面前錐形範圍內的玩家造成冰霜傷害。冰錐術使被其擊中的玩家移動速度降低50%，持續8秒。"},[4409]={title="冰霜新星",text="西斯雷爾對10碼範圍內的所有玩家造成冰霜傷害。被冰霜新星擊中的玩家將被定身8秒。"},[4408]={title="防護冰霜結界",text="西斯雷爾以護盾保護她自己抵抗冰霜傷害，持續1分鐘或直到防護冰霜結界吸收了太多冰霜傷害。"},[4407]={title="寒冰箭",text="西斯雷爾對一名玩家造成冰霜傷害。寒冰箭使其擊中的玩家緩速50%，持續4秒。"},[4406]={title="暴風雪",text="西斯雷爾製造一陣暴風雪，持續10秒。暴風雪對任何被捲入的玩家造成冰霜傷害。"},[4404]={title="霜甲術",text="西斯雷爾以寒冰做為她的護甲，使其護甲值提高，並使對她的近戰攻擊造成冰凍效果。"},[4405]={title="冰凍",text="被冰凍的玩家移動速度降低30%，攻擊速度降低25%，持續5秒。"},[4391]={title="安格雷爾"},[4403]={title="盾牆",text="安格雷爾在剩下25%生命力時提高他的防禦，持續10秒。當盾牆作用時，安格雷爾受到的傷害降低75%。"},[4402]={title="破甲攻擊",text="安格雷爾使一名玩家的護甲值降低。玩家在護甲值降低時將受到額外的傷害。可堆疊5次。"},[4401]={title="盾牌格擋",text="安格雷爾使他格擋受到攻擊的機率提高75%，持續5秒。"},[4400]={title="打擊",text="安格雷爾以他的武器對一名玩家造成物理傷害。"},[4398]={title="易怒",text="安格雷爾在玩家對他造成致命一擊時會進入狂怒狀態。"},[4399]={title="狂怒",text="安格雷爾造成的傷害提高55點，且攻擊速度提高30%。狂怒持續5秒。"},[4471]={title="七賢",text="杜姆雷爾召喚他的矮人同伴們的鬼魂與玩家戰鬥。鬼魂將一次一個地輪流被召喚。當其他六個鬼魂被擊敗時，杜姆雷爾將會加入戰鬥。"},[4481]={title="火焰爆發",text="瑪格姆斯選擇一個直徑20碼的區域，對其中的所有玩家造成火焰傷害。"},[4480]={title="戰爭踐踏",text="瑪格姆斯對5碼範圍內的所有玩家造成物理傷害並將其擊退。被戰爭踐踏擊中的玩家將會昏迷，持續8秒。"},[6441]={title="茉艾拉‧銅鬚公主"},[6444]={title="心靈震爆",text="茉艾拉‧銅鬚公主爆震一名玩家的心靈，造成暗影傷害。"},[6443]={title="恢復",text="茉艾拉‧銅鬚公主幫助一名盟友恢復，每3秒治療一次，持續20秒。"},[6442]={title="治療",text="茉艾拉‧銅鬚公主呼喚神聖魔法治療一名盟友。"},[4647]={title="索瑞森之手",text="達格蘭‧索瑞森大帝對一名玩家造成火焰傷害，並使其昏迷，持續5秒。"},[4646]={title="鐵敵之錘",text="達格蘭‧索瑞森大帝握有強大的鐵敵之錘。達格蘭‧索瑞森大帝的近戰攻擊有一定的機率觸發3次額外攻擊，並使其造成致命一擊的機率提高10%，持續5秒。"},[4645]={title="烈焰化身",text="達格蘭‧索瑞森大帝變形成烈焰化身，持續10秒。烈焰化身對所有魔法免疫，且在近戰攻擊命中玩家時會造成火焰傷害。"},[4905]={title="鞭笞",text="哈卡的化身鞭笞目前目標，使其昏迷2秒。此外，鞭笞有10%的機率使目標繳械。"},[4904]={title="語言詛咒",text="哈卡的化身詛咒一名玩家，使其施法速度降低50%，持續15秒。"},[4903]={title="導致瘋狂",text="哈卡的化身將一名玩家逼瘋，使其攻擊自己的盟友，持續6秒。瘋狂的玩家攻擊速度提高50%，移動速度提高80%。"},[4938]={title="可悲的奧戈姆",text="可悲的奧戈姆在戰鬥中加入『預言者』迦瑪蘭。"},[4941]={title="暗影箭",text="可悲的奧戈姆對一名玩家丟出一支黑暗魔法箭，造成暗影傷害。"},[4940]={title="暗言術：痛",text="可悲的奧戈姆說出黑暗的語言，每3秒對一名玩家造成暗影傷害，持續18秒。"},[4939]={title="虛弱詛咒",text="可悲的奧戈姆詛咒一名玩家，使其造成的物理傷害降低。"},[4937]={title="迦瑪蘭的妖術",text="『預言者』迦瑪蘭對一名玩家使用妖術，使其傷害提高400%，將其變形並攻擊盟友。"},[4936]={title="陷地圖騰",text="『預言者』迦瑪蘭在他腳邊召喚一個陷地圖騰，持續30秒。陷地圖騰每5秒使10碼範圍內的所有玩家定身。"},[4935]={title="烈焰風暴",text="『預言者』迦瑪蘭召喚出火柱，對目標區域5碼範圍內的所有玩家造成火焰傷害，同時每2秒造成一次額外的火焰傷害，持續8秒。"},[4934]={title="治療波",text="『預言者』迦瑪蘭治療一名盟友。"},[6114]={title="夢境看守者",text="德姆塞卡爾、德拉維沃爾、摩弗拉斯和哈札斯用生命保衛伊蘭尼庫斯之影。"},[4943]={title="拍翼",text="夢境看守者拍動他們的翅膀，將他們面前的玩家擊退。"},[4942]={title="酸液之息",text="夢境看守者吐出酸液之息，立即對前方所有玩家造成自然傷害，和每5秒一次的額外自然傷害，持續45秒。"},[4953]={title="酸液之息",text="伊蘭尼庫斯之影噴出酸液，對他面前的所有玩家立即造成自然傷害，並每5秒造成額外自然傷害，持續45秒。"},[4952]={title="戰爭踐踏",text="伊蘭尼庫斯之影踐踏地面，使5碼範圍內的所有玩家昏迷5秒。"},[4951]={title="痛擊",text="伊蘭尼庫斯之影痛擊目前目標，造成2次額外攻擊。"},[4950]={title="深度沉睡",text="伊蘭尼庫斯之影將一名玩家催眠15秒，使其昏迷且不會受到傷害。"},[4524]={title="狂亂",text="當歐莫克大王剩下50%生命力時，他會進入狂暴狀態，提高其攻擊速度。"},[4523]={title="擊退",text="歐莫克大王對目前目標造成物理傷害，並將其擊退。"},[4526]={title="血之詛咒",text="暗影獵手沃許加斯詛咒10碼範圍內的所有玩家，使其受到的物理傷害提高90點，持續10分鐘。"},[4525]={title="妖術",text="暗影獵手沃許加斯將一名隨機玩家變形成一隻青蛙，使其無法攻擊或施法，持續10秒。"},[4534]={title="階段三：將領",text="當將領沃恩剩下40%生命力時，他會毫不保留地展開他最後的攻擊。"},[4537]={title="拳擊",text="將領沃恩以拳擊攻擊一名隨機玩家，造成物理傷害並中斷其施法5秒。"},[4536]={title="上鉤拳",text="將領沃恩用上鉤拳攻擊當前目標，造成物理傷害將其擊退。"},[4535]={title="猛踢",text="將領沃恩猛踢目前目標，造成物理傷害並使其昏迷2秒。"},[4529]={title="階段二：打鬥者",text="當將領沃恩的生命力上限剩下65%，他會改變姿態，更加兇猛地攻擊玩家。"},[4531]={title="致死打擊",text="將領沃恩對目前目標造成物理傷害，使其受到的治療效果降低50%，持續5秒。"},[4530]={title="順劈斬",text="將領沃恩對當前目標與其最近的盟友造成物理傷害，最多影響3個目標。"},[4527]={title="階段一：痛擊",text="將領沃恩以高速無情地攻擊他的敵人。"},[6464]={title="擲斧",text="當將領沃恩改變他的姿態時，他會對一名隨機玩家丟出一把巨大的斧頭，造成1750點物理傷害，並使其昏迷2秒。"},[4528]={title="痛擊",text="將領沃恩痛擊目前目標，造成2次額外攻擊。"},[4545]={title="召喚尖塔小蜘蛛",text="死亡後，三隻尖塔小蜘蛛從煙網蛛后的屍體爬出。"},[4546]={title="尖塔小蜘蛛",text="煙網蛛后的小蜘蛛。"},[4544]={title="蛛后的乳汁",text="煙網蛛后對一名隨機玩家下毒，使其與在30碼範圍內的任何盟友週期性地被定身。"},[4543]={title="結晶",text="煙網蛛后使她面前所有玩家昏迷6秒。"},[4554]={title="打擊",text="烏洛克‧末日嚎攻擊目前目標，造成物理傷害。"},[4553]={title="撕裂",text="烏洛克‧末日嚎撕裂目前目標，每3秒造成一次物理傷害。"},[4552]={title="破膽咆哮",text="烏洛克‧末日嚎發出咆哮，使8碼範圍內的所有玩家因恐懼而逃跑，持續8秒。"},[4571]={title="射擊",text="當軍需官茲格雷斯目前目標不在近戰範圍內時，會對其射擊，造成物理傷害。"},[4570]={title="昏迷炸彈",text="軍需官茲格雷斯對隨機一名玩家投出炸彈，對5碼範圍內的所有玩家造成火焰傷害並使其昏迷，持續5秒。"},[4569]={title="飲用治療藥水",text="軍需官茲格雷斯飲用一瓶治療藥水，治療他自己。"},[4568]={title="鉤網",text="軍需官茲格雷斯投擲一張網子，對一名隨機玩家造成物理傷害並使其定身10秒。"},[4573]={title="撕裂",text="哈雷肯撕裂當前目標，每3秒造成一次物理傷害。"},[4572]={title="痛擊",text="哈雷肯痛擊目前目標，造成2次額外攻擊。"},[4586]={title="感染撕咬",text="『奴役者』基茲盧爾撕咬目前目標，每10秒造成自然傷害，並使其受到的物理傷害提高。"},[4585]={title="亡命刺痛",text="『奴役者』基茲盧爾啃咬當前目標，造成物理傷害並吸取生命力。基茲盧爾會恢復其所吸取生命力的兩倍。"},[4584]={title="狂亂",text="『奴役者』基茲盧爾進入狂暴狀態，提高其攻擊速度，持續2分鐘。"},[6465]={title="主宰的防禦",text="當維姆薩拉克主宰剩下50%生命力時，他會召喚兩名他的守衛來在戰鬥中防衛他。"},[6472]={title="血斧精兵"},[6474]={title="拳擊",text="血斧精兵拳擊一名玩家，造成物理傷害並中斷其正在施放的法術，持續5秒。"},[6473]={title="猛踢",text="血斧精兵腳踢一名玩家，造成物理傷害並使其昏迷2秒。"},[6469]={title="燃棘狂戰士"},[6471]={title="打擊",text="燃棘狂戰士打擊一名玩家，造成物理傷害。"},[6470]={title="致死打擊",text="燃棘狂戰士使一名玩家受到致死重傷，造成物理傷害並使其受到的所有治療效果降低50%，持續5秒。"},[6466]={title="尖石督軍"},[6468]={title="狂亂",text="尖石督軍進入狂亂狀態，使攻擊速度提高，持續2分鐘。"},[6467]={title="強化意志",text="尖石督軍強化其盟友，從其身上驅散變形術、魅惑或癱瘓效果。"},[4589]={title="挫志怒吼",text="維姆薩拉克主宰怒吼，使10碼範圍內的所有玩家近戰攻擊強度降低，持續30秒。"},[4588]={title="順劈斬",text="維姆薩拉克主宰對目前目標與其最靠近的盟友造成物理傷害，可影響最多3個目標。"},[4587]={title="橫掃猛擊",text="維姆薩拉克主宰對他面前的所有玩家造成物理傷害，並將其擊退。"},[4920]={title="糾纏",text="特迪斯‧扭木將一名玩家傳送至身邊，用根鬚纏住該玩家，每3秒造成25點自然傷害，並使其無法移動，持續10秒。"},[4919]={title="纏繞之藤",text="特迪斯‧扭木對10碼內的所有玩家造成525到675點物理傷害，將其擊倒並使其無法移動，持續10秒。"},[4918]={title="踐踏",text="特迪斯‧扭木對10碼內的所有玩家造成物理傷害。"},[4913]={title="侵入者警報!",text="當玩家開始戰鬥時，特迪斯‧扭木會召喚任何還活著的鐵桉保衛者來協助他。"},[4914]={title="鐵桉保衛者"},[4917]={title="糾纏根鬚",text="埃隆巴克保衛者用根鬚纏住玩家，每3秒造成40點自然傷害，並使其無法移動，持續10秒。"},[4916]={title="擊退",text="埃隆巴克保衛者對一名玩家造成物理傷害，將其擊退，並使該玩家的威脅值降低50%。"},[4915]={title="踐踏",text="埃隆巴克保衛者對10碼內的所有玩家造成物理傷害。"},[4912]={title="震盪射擊",text="伊琳娜‧鴉橡使一名玩家暈眩，使其移動速度降低50%，持續3秒。震盪射擊有50%的機率使玩家昏迷3秒。"},[4911]={title="獻祭陷阱",text="伊琳娜‧鴉橡朝附近投擲一個獻祭陷阱。獻祭陷阱持續1分鐘，或直到玩家走過它為止。\n\n獻祭陷阱會對觸發該陷阱的玩家造成火焰傷害。"},[4910]={title="亂射",text="伊琳娜‧鴉橡對一個區域內的所有玩家發射大量箭雨。亂射會造成秘法傷害。"},[4909]={title="多重射擊",text="伊琳娜‧鴉橡對面前最多10名玩家造成物理傷害。"},[4906]={title="費拉",text="費拉是伊琳娜‧鴉橡忠實的夥伴，會誓死在她身邊戰鬥。"},[4908]={title="槌擊",text="費拉對一名玩家造成物理傷害。"},[4907]={title="衝鋒",text="費拉朝一名玩家衝鋒，造成物理傷害，並使其昏迷2秒。"},[4840]={title="支配心智",text="博學者卡雷迪斯魅惑一名玩家。被魅惑的玩家將為博學者卡雷迪斯而戰，但近戰攻擊速度降低100%。支配心智持續10秒。"},[4839]={title="心靈震爆",text="博學者卡雷迪斯對一名玩家造成暗影傷害。"},[4838]={title="精神鞭笞",text="博學者卡雷迪斯朝一名玩家引導黑暗魔法，每1秒造成240點暗影傷害，持續3秒，並使該目標的移動速度降低50%。"},[4837]={title="暗言術：痛",text="博學者卡雷迪斯吟誦黑暗咒語，每3秒對一名敵人造成48點暗影傷害，持續18秒。"},[4836]={title="暗影形態",text="當博學者卡雷迪斯的生命力剩餘50%時，會進入暗影形態。暗影形態使所有受到的傷害降低，並使造成的暗影傷害提高40%，持續4分鐘。"},[4827]={title="踐踏",text="伊莫塔爾對10碼內的所有玩家造成物理傷害。"},[4826]={title="狂亂",text="伊莫塔爾的攻擊速度提高，持續2分鐘。"},[4825]={title="感染撕咬",text="伊莫塔爾撕咬一名玩家和距離最接近的盟友，每10秒造成45點自然傷害，並提高其受到的物理傷害，持續3分鐘。"},[4824]={title="伊莫塔爾傳送門",text="伊莫塔爾會週期性地將玩家召喚到其位置，並使其威脅值歸零。"},[4822]={title="伊莫塔爾之眼",text="伊莫塔爾召喚伊莫塔爾之眼，隨機攻擊一名玩家。"},[4823]={title="伊莫塔爾的凝視",text="伊莫塔爾之眼會降低玩家的移動速度與加速，並造成暗影傷害，持續4秒。此效果可堆疊。"},[29895]={title="秘法射擊",text="托塞德林王子對一個遠方的敵人造成秘法傷害。"},[29894]={title="召喚",text="近戰範圍內沒有任何敵人時，托塞德林王子會召喚一個敵人到身邊。"},[4756]={title="法術反制",text="托塞德林王子中斷一名玩家施法，並防止其施放其他法術，持續15秒。"},[4755]={title="旋風斬",text="托塞德林王子對8碼內的所有玩家造成物理傷害，並將其擊退。"},[4754]={title="秘法衝擊",text="托塞德林王子對一名玩家造成875到1125點秘法傷害，並將其擊退。"},[5000]={title="匹姆吉布"},[5003]={title="烈焰打擊",text="匹姆吉布對一名玩家造成火焰傷害，並提高該玩家受到所有來源的火焰傷害，持續20秒。此效果可堆疊。"},[5002]={title="火球術",text="匹姆吉布對一名玩家造成點火焰傷害。"},[5001]={title="衝擊波",text="匹姆吉布對10碼內的所有玩家造成122到140點火焰傷害，並使其移動速度降低50%，持續6秒。"},[29889]={title="蕾瑟塔蒂絲"},[4999]={title="巨化術",text="蕾瑟塔蒂絲將匹姆吉布變大，持續30秒。變大時，匹姆吉布造成的傷害提高，施法速度提高100%。"},[4998]={title="獻祭",text="蕾瑟塔蒂絲對目前目標造成火焰傷害。獻祭會持續對敵人造成火焰傷害，持續21秒。"},[4997]={title="語言詛咒",text="蕾瑟塔蒂絲詛咒一名玩家使用惡魔語，持續15秒。語言詛咒使施法速度降低50%。"},[4996]={title="荊棘詛咒",text="蕾瑟塔蒂絲以荊棘詛咒詛咒一名玩家。被詛咒的玩家每次使用近戰攻擊時，荊棘詛咒都有50%的機率對被詛咒的玩家造成暗影傷害。荊棘詛咒持續3分鐘。"},[4995]={title="暗影箭雨",text="蕾瑟塔蒂絲對30碼內的所有玩家造成128到172點暗影傷害。"},[4994]={title="虛無箭",text="蕾瑟塔蒂絲對目標造成925到1075點暗影傷害。"},[5009]={title="小水浪",text="當生命力剩餘66%和33%時，海多斯博恩會召喚2個小水浪。"},[5010]={title="噴液",text="每當小水浪在近戰距離內攻擊一名玩家時，有一定機率將其擊退，並使其威脅值歸零。"},[5008]={title="巨型噴泉",text="海多斯博恩召喚一個巨型噴泉，對10碼範圍內的所有玩家造成463到537點冰霜傷害，並將其擊退。"},[5007]={title="激流",text="海多斯博恩對附近的所有玩家造成85到115點冰霜傷害，並將其擊退。受激流影響的玩家會被繳械，持續4秒。"},[5004]={title="沉沒",text="海多斯博恩降低附近所有玩家的耐力，持續1分鐘。此效果可堆疊。"},[29563]={title="暗影箭雨",text="瑟雷姆‧刺蹄射出多支黑暗魔法飛彈，對附近30碼內的敵人造成128到172點暗影傷害。"},[4656]={title="犧牲",text="瑟雷姆‧刺蹄將一名玩家傳送至他的獻祭壇上。犧牲會使被獻祭的玩家昏迷並每1秒損失300點生命力，持續8秒。"},[4655]={title="劇烈痛楚",text="瑟雷姆‧刺蹄每3秒對20碼內的所有玩家造成200點暗影傷害，持續15秒。此效果可堆疊。"},[4984]={title="快來吧，爪牙們!",text="當『狂野變形者』奧茲恩剩下50%生命力時會召喚數個小鬼協助他戰鬥。"},[4985]={title="奧茲恩的爪牙",text="奧茲恩的爪牙每次近戰攻擊成功命中時會將目前目標的威脅值設為零。"},[4925]={title="恐狼形態",text="『狂野變形者』奧茲恩變形成一隻恐狼，攻擊速度提高75%，近戰傷害提高50%，持續30秒。在恐狼形態下，『狂野變形者』奧茲恩會使用這些技能。"},[4928]={title="兇惡撕咬",text="『狂野變形者』奧茲恩對他面前最多2名玩家造成物理傷害。"},[29719]={title="痛擊",text="『狂野變形者』奧茲恩在狼形態下會獲得額外攻擊次數。"},[4929]={title="割碎",text="『狂野變形者』奧茲恩割碎一名玩家，使其移動速度降低50%，且每2秒造成200點物理傷害，持續20秒。"},[4926]={title="樹形",text="『狂野變形者』奧茲恩變形成一棵樹，提高護甲值，並使近戰傷害提高25%，持續30秒。在樹形態下，『狂野變形者』奧茲恩會使用這些技能。"},[29976]={title="糾纏根鬚",text="『狂野變形者』奧茲恩用根鬚纏住一名玩家，持續10秒，使其無法移動，同時每3秒造成40點自然傷害。"},[4931]={title="繳械",text="『狂野變形者』奧茲恩繳械一名玩家，持續6秒。"},[4932]={title="擊退",text="『狂野變形者』奧茲恩對一名玩家造成物理傷害並將其擊退。擊退會使受影響玩家的威脅值歸零。"},[4933]={title="野性恢復",text="『狂野變形者』奧茲恩每2秒恢復生命力，持續20秒。"},[4921]={title="薩特形態",text="『狂野變形者』奧茲恩在薩特形態時會使用這些技能。"},[4924]={title="荊棘術",text="『狂野變形者』奧茲恩用荊棘包裹自身，對所有攻擊『狂野變形者』奧茲恩的玩家造成自然傷害。"},[4923]={title="枯萎",text="『狂野變形者』奧茲恩對一名玩家造成740到860點自然傷害，並留下凋萎疾病，每3秒額外造成139到161點自然傷害，並降低其力量、智力或敏捷，持續21秒。"},[4922]={title="弱化",text="『狂野變形者』奧茲恩侵蝕一名玩家，每1秒汲取200點法力，持續10秒。"},[4798]={title="多重射擊",text="爐邊歌手弗瑞斯坦對他面前最多10名玩家造成物理傷害。"},[4796]={title="靈體防禦",text="爐邊歌手弗瑞斯坦閃躲攻擊的機率提高50%。"},[4795]={title="挫志怒吼",text="爐邊歌手弗瑞斯坦發出怒吼，降低10碼內所有玩家的耐力和主要屬性，持續30秒。"},[4794]={title="催眠曲",text="爐邊歌手弗瑞斯坦將一名玩家催眠，使其昏迷10秒或直到受到傷害為止。"},[6217]={title="復仇的魅影",text="不可寬恕者由四個復仇的魅影陪同。"},[6463]={title="冰霜震擊",text="復仇的魅影用冰霜震擊玩家，造成89到95點冰霜傷害，並使其移動速度降低50%，持續8秒。"},[4833]={title="無情苦痛",text="不可寬恕者將一波痛苦和悲傷導入受害者，使該目標減速並造成暗影傷害。"},[29845]={title="語言詛咒",text="郵政局長瑪羅恩強迫敵人使用惡魔語，使其施法速度降低50%，持續15秒。"},[29844]={title="反手一擊",text="郵政局長瑪羅恩對敵人發動反手一擊，使其昏迷2秒。"},[29843]={title="虛弱詛咒",text="郵政局長瑪羅恩降低附近敵人造成的物理傷害，持續2分鐘。"},[29842]={title="恐懼",text="郵政局長瑪羅恩使敵人因恐懼而逃跑，持續4秒。在同一時間內，只能對1個目標造成恐懼效果。"},[29847]={title="克服萬難，郵件必達",text="郵政局長瑪羅恩會派出不死族郵差追趕亂動郵箱的人。亂動郵箱三次後，郵政局長就會親自出手解決問題。"},[29848]={title="不死族郵差"},[29851]={title="哀嚎死者",text="不死族郵差的哀嚎會降低附近敵人的所有屬性，持續6秒。"},[29850]={title="墓之呼喚",text="不死族郵差在60秒後對敵人造成暗影傷害。"},[29849]={title="無形防禦",text="不死族郵差閃躲攻擊的機率提高50%。"},[4801]={title="狂怒",text="當殘忍的提米的生命力剩餘50%時，他會進入狂怒狀態，使其造成的傷害與攻擊速度提高30%。"},[4800]={title="困獸之爪",text="殘忍的提米猛烈攻擊，對面前的所有敵人造成925到1075點物理傷害，並為自己治療相當於所造成傷害100%的生命力。"},[4799]={title="痛擊",text="殘忍的提米使出痛擊，造成2次額外攻擊。"},[6454]={title="暗影箭雨",text="指揮官瑪洛爾擲出黑暗魔法飛彈，對30碼內的所有玩家造成128到172點暗影傷害。"},[6453]={title="裂顱",text="指揮官瑪洛爾降低一名玩家的耐力，持續20秒。"},[6452]={title="地面潰擊",text="指揮官瑪洛爾猛擊地面，對10碼內的所有玩家造成96到128點物理傷害，並使其昏迷3秒。"},[4804]={title="拳擊",text="威利‧希望破除者隨機拳擊一名玩家，造成45點物理傷害並中斷施法，持續5秒。"},[4803]={title="射擊",text="威利·希望破除者射擊目前目標，造成物理傷害。"},[4802]={title="擊退",text="威利·希望破除者對目前目標造成物理傷害，並將其擊退。"},[4807]={title="血色火砲",text="在威利‧希望破除者附近的血色火砲可以被裝填砲彈，然後對接近的復活的步槍兵開火。"},[4805]={title="召喚復活的步槍兵",text="威利‧希望破除者每5秒召喚復活的步槍兵協助他戰鬥。"},[4806]={title="復活的步槍兵",text="復活的步槍兵協助威利‧希望破除者戰鬥，射擊一名隨機玩家，造成物理傷害。"},[4810]={title="燃燒之風",text="古卷管理者加爾福特以燃燒之風包圍當前目標，每1秒造成200點火焰傷害，並使其昏迷8秒。"},[4809]={title="炎爆術",text="古卷管理者加爾福特對目前目標造成火焰傷害。"},[4808]={title="火焰新星",text="古卷管理者加爾福特釋放火焰新星，對10碼內的所有敵人造成197到227點火焰傷害。"},[4832]={title="心靈尖嘯",text="巴納札爾發出心靈尖嘯，使8碼內的所有玩家陷入恐懼，持續6秒。"},[4831]={title="催眠術",text="巴納札爾強迫一名隨機玩家陷入沉睡，使其昏迷直到受到傷害為止。"},[4830]={title="支配",text="巴納札爾控制一名隨機玩家，持續15秒。"},[4829]={title="暗影震擊",text="巴納札爾對附近的所有玩家造成暗影傷害。"},[4828]={title="心靈震爆",text="巴納札爾對目前目標造成暗影傷害。"},[4743]={title="侵入者警報!",text="當守衛摩爾達剩下50%生命力時會施放狂亂並呼叫幫助。"},[4744]={title="狂亂",text="守衛摩爾達的攻擊速度提高，持續2分鐘。"},[4742]={title="打擊",text="守衛摩爾達對一名玩家造成物理傷害。"},[4741]={title="盾牌衝鋒",text="守衛摩爾達對一名玩家衝鋒，將其擊退並造成物理傷害。"},[4740]={title="盾擊",text="守衛摩爾達對一名玩家造成物理傷害並中斷任何正在施放的法術，持續8秒。"},[4737]={title="你害我翻倒了我的酒!",text="踐踏者克雷格的生命力上限低於50%時會進入醉酒怒氣狀態，並施放狂亂。"},[4739]={title="醉酒怒氣",text="踐踏者克雷格每一次近戰攻擊命中玩家時會將目前目標的威脅值設為零。醉酒怒氣同時使踐踏者克雷格的移動速度提高100%，持續1分鐘。"},[4738]={title="狂亂",text="踐踏者克雷格的攻擊速度提高，持續2分鐘。"},[4736]={title="旋風斬",text="踐踏者克雷格對8碼範圍內的所有玩家造成物理傷害。"},[4735]={title="戰爭踐踏",text="踐踏者克雷格擊退5碼範圍內的所有玩家。"},[4734]={title="噴酒",text="踐踏者克雷格對面前錐形範圍內的所有玩家噴酒。使被噴酒擊中的玩家命中機率降低75%，並陷入酒醉，持續10秒。"},[4728]={title="侵入者警報!",text="當守衛芬古斯剩下50%生命力時會施放狂亂並呼叫幫助。"},[4729]={title="狂亂",text="守衛芬古斯的攻擊速度提高，持續2分鐘。"},[4727]={title="打擊",text="守衛芬古斯對一名玩家造成物理傷害。"},[4726]={title="盾牌衝鋒",text="守衛芬古斯朝一名玩家衝鋒，將他們擊退並造成物理傷害。"},[4725]={title="盾擊",text="守衛芬古斯對一名玩家造成物理傷害，並中斷任何正在施放的法術，持續8秒。"},[4719]={title="入侵警報!",text="守衛斯里基克的生命力上限低於50%時會施放狂亂，並呼喚援助。"},[4720]={title="狂亂",text="守衛斯里基克的攻擊速度提高60%，持續2分鐘。"},[4718]={title="打擊",text="守衛斯里基克對一名玩家造成物理傷害。"},[4717]={title="盾牌衝鋒",text="守衛斯里基克對一名玩家衝鋒，將其擊退並造成物理傷害。"},[4716]={title="盾擊",text="守衛斯里基克對一名玩家造成物理傷害，並打斷所有法術的施放，持續8秒。"},[4707]={title="放馬過來!",text="當隊長克羅卡斯剩下25%生命力時會啟動反擊風暴。"},[4708]={title="反擊風暴",text="隊長克羅卡斯反擊所有在近戰攻擊他的玩家，造成物理傷害，持續15秒。"},[4695]={title="侵入者警報!",text="當隊長克羅卡斯剩下50%生命力時會召喚兩個戈多克劫奪者協助他戰鬥。"},[4696]={title="戈多克劫奪者"},[4699]={title="致死打擊",text="戈多克劫奪者對一名玩家造成物理傷害。受致死打擊影響的玩家受到的治療效果降低50%，持續5秒。"},[4698]={title="破甲攻擊",text="戈多克劫奪者使一名玩家的護甲值降低，而使其受到的物理傷害提高。破甲攻擊可堆疊最多5次，持續30秒。"},[4697]={title="順劈斬",text="戈多克劫奪者對一名玩家與其鄰近的一名額外玩家造成物理傷害。"},[4706]={title="致死順劈斬",text="隊長克羅卡斯對一名玩家與其身旁的額外一名玩家造成物理傷害。致死順劈斬使受影響玩家所受的所有治療降低50%，持續5秒。"},[4705]={title="恫嚇怒吼",text="隊長克羅卡斯使8碼範圍內的所有玩家因恐懼而逃跑，持續8秒。"},[4673]={title="我今天想當個什麼樣的巨魔?",text="『觀察者』克魯什在生成時會選擇成為一名牧師、薩滿或法師。"},[4685]={title="法師克魯什"},[4689]={title="冰霜新星",text="『觀察者』克魯什對10碼範圍內的所有玩家造成冰霜傷害。冰霜新星使受影響的玩家定身8秒。"},[4688]={title="火球術",text="『觀察者』克魯什對一名玩家造成火焰傷害。"},[4687]={title="嗜血術",text="『觀察者』克魯什給予他自己或一名盟友嗜血術。受影響的敵人近戰攻擊速度提高60%，持續30秒。"},[4686]={title="魔爆術",text="『觀察者』克魯什對附近的所有玩家造成秘法傷害。"},[4679]={title="薩滿克魯什"},[4684]={title="閃電箭",text="『觀察者』克魯什對一名玩家造成自然傷害。"},[4682]={title="陷地圖騰",text="『觀察者』克魯什在他身邊召喚一個陷地圖騰，持續30秒。"},[4683]={title="陷地",text="陷地圖騰每5秒使10碼範圍內的所有玩家定身。"},[4681]={title="治療波",text="『觀察者』克魯什治療他自己或一名盟友。"},[4680]={title="閃電鏈",text="『觀察者』克魯什對一名玩家與最多2個附近目標造成自然傷害。"},[4674]={title="牧師克魯什"},[4678]={title="心靈尖嘯",text="『觀察者』克魯什使8碼範圍內的所有玩家因恐懼而逃跑，持續4秒。"},[4677]={title="真言術:盾",text="『觀察者』克魯什給予他自己或一名盟友一個神聖能量的護盾來吸收傷害，並防止施法被中斷。真言術:盾持續30秒或直到它吸收了太多傷害。"},[4676]={title="心靈震爆",text="『觀察者』克魯什對一名玩家造成暗影傷害。"},[4675]={title="治療術",text="『觀察者』克魯什治療他自己或一名盟友。"},[4669]={title="戰爭踐踏",text="戈多克大王對5碼範圍內的所有玩家造成物理傷害並使其昏迷，持續5秒。"},[4668]={title="致死打擊",text="戈多克大王對一名玩家造成物理傷害。致死打擊使玩家受到的治療效果降低50%，持續5秒。"},[4667]={title="破甲攻擊",text="戈多克大王使一名玩家的護甲值降低，而受到的物理傷害提高，持續30秒。破甲攻擊可堆疊最多5次。"},[4666]={title="狂暴衝鋒",text="戈多克大王衝向隨機一名玩家，將其踢飛並造成物理傷害。"},[4844]={title="女妖詛咒",text="安娜絲塔麗男爵夫人詛咒10碼內的所有玩家，降低其命中機率，持續12秒。"},[4843]={title="沉默",text="安娜絲塔麗男爵夫人使10碼範圍內的所有玩家沉默而無法施法，持續10秒。"},[4842]={title="女妖哀嚎",text="安娜絲塔麗男爵夫人發出痛苦的哀嚎，對目前目標造成128到172點暗影傷害。"},[4841]={title="佔據",text="安娜絲塔麗男爵夫人隨機控制一名玩家。佔據會使該目標的生命力上限與造成的傷害提高100%，但會降低其受到的治療效果與護甲值。該控制會持續2分鐘，或直到目標的剩餘生命力達到50%為止。"},[4850]={title="覆體之網",text="奈幽布恩坎將一名玩家囚禁在網內，使其無法移動並使其近戰攻擊間隔時間延長100%，持續6秒。"},[4849]={title="刺穿護甲",text="奈幽布恩坎刺穿當前目標，使其護甲值降低50%，持續20秒。"},[4848]={title="地穴甲蟲",text="奈幽布恩坎朝玩家釋放甲蟲，造成物理傷害。"},[4845]={title="復活不死甲蟲",text="奈幽布恩坎復活死去的甲蟲協助她戰鬥。"},[4846]={title="不死甲蟲",text="不死甲蟲協助奈幽布恩坎作戰，毒害他們的目標。"},[4847]={title="放毒",text="不死甲蟲的近戰攻擊有一定機率使當前目標中毒，每3秒造成24點自然傷害，持續30秒。"},[4854]={title="寒冰箭",text="蒼白的瑪勒基對目前目標造成48到64點冰霜傷害，使其移動速度降低50%，持續4秒。"},[4853]={title="寒冰之墓",text="蒼白的瑪勒基將目前目標困在寒冰之墓中，使其昏迷10秒。"},[4852]={title="霜甲術",text="蒼白的瑪勒基以一層冰霜包覆自身，降低其受到的物理傷害。近戰攻擊者會被冰凍，移動速度降低30%，加速降低25%。"},[4851]={title="吸取生命",text="蒼白的瑪勒基吸取目前目標的生命，每1秒造成暗影傷害，持續5秒，並為自己治療所造成傷害的100%。"},[4858]={title="吸血一擊",text="巴瑟拉斯鎮長造成致命一擊時，會從當前目標身上吸取250點生命力，並為自己恢復相當於吸取量的生命力。"},[4856]={title="狂烈憤怒",text="巴瑟拉斯鎮長陷入狂怒，使造成的物理傷害與近戰攻擊速度提高4%，持續1分鐘。此效果可堆疊。"},[4857]={title="全力衝鋒",text="巴瑟拉斯鎮長隨機衝向一個目標，造成物理傷害，並使其昏迷。"},[4855]={title="群體打擊",text="巴瑟拉斯鎮長拳擊10碼內的所有玩家，造成物理傷害，中斷施法5秒，並將其擊退。"},[4861]={title="亂舞",text="『暴食者』拉姆斯登在造成致命一擊後，接下來3次攻擊的攻擊速度提高30%。"},[4860]={title="踐踏",text="『暴食者』拉姆斯登對10碼內的所有玩家造成物理傷害。"},[4859]={title="擊昏",text="『暴食者』拉姆斯登對目前目標造成物理傷害，將其擊退，使其威脅值減半，並使其昏迷6秒。"},[4868]={title="順劈斬",text="奧里爾斯‧瑞文戴爾領主砍劈當前目標，對該目標及其最近盟友造成物理傷害。"},[4867]={title="致死打擊",text="奧里爾斯·瑞文戴爾領主攻擊目前目標，造成物理傷害，並使任何對其施放的治療效果降低50%，持續5秒。"},[4866]={title="暗影炸彈",text="奧里爾斯·瑞文戴爾領主向一名玩家射出大型黑暗魔法箭，造成288到388點暗影傷害。"},[29936]={title="暗影箭",text="奧里爾斯·瑞文戴爾領主向一名玩家射出黑暗魔法箭，造成128到172點暗影傷害。"},[4865]={title="穢邪光環",text="奧里爾斯‧瑞文戴爾領主的穢邪光環每2秒對30碼內的所有玩家造成150點暗影傷害。"},[4862]={title="死者復生",text="奧里爾斯‧瑞文戴爾領主召喚出6具無腦的骷髏來為他而戰。"},[4864]={title="死亡契約",text="奧里爾斯‧瑞文戴爾領主在12秒後犧牲任何剩下的無腦的骷髏，恢復他自己相當於他們剩餘的生命力。"},[4863]={title="無腦的骷髏",text="無腦的骷髏協助奧里爾斯‧瑞文戴爾領主戰鬥。"},[12118003]={title="暗影震擊",text="魯西弗隆以暗影能量衝擊附近的敵人，造成暗影傷害。"},[12118002]={title="魯西弗隆的詛咒",text="魯西弗隆詛咒團隊，大幅提高其法術與技能的法力消耗。"},[12118001]={title="末日降臨",text="魯西弗隆對一名玩家施加末日，數秒後爆發，造成大量暗影傷害。"},[11982004]={title="熔岩噴吐",text="瑪格曼達朝敵人噴吐熔岩，造成火焰傷害。"},[11982003]={title="熔岩炸彈",text="瑪格曼達朝一名遠方的玩家投擲熔岩炸彈，產生一灘火焰，對站在其中的任何人造成大量火焰傷害。"},[11982002]={title="恐慌",text="瑪格曼達發出恐怖的咆哮，使附近的玩家在熔岩地面上恐懼逃跑。"},[11982001]={title="狂亂",text="瑪格曼達陷入狂暴，大幅提高其攻擊速度。獵人的寧神射擊可以安撫這種狂暴。"},[12259003]={title="暗影箭",text="基赫納斯朝目標擲出暗影箭，造成大量暗影傷害。"},[12259002]={title="火焰之雨",text="基赫納斯召喚火焰之雨，對區域內所有敵人造成持續性的火焰傷害。"},[12259001]={title="基赫納斯的詛咒",text="基赫納斯詛咒團隊，使其受到的所有治療效果降低75%。"},[12057002]={title="熔岩鐐銬",text="加爾以熔岩束縛附近的玩家，大幅降低其移動速度。"},[12057001]={title="反魔法脈衝",text="加爾釋放反魔法脈衝，驅散附近玩家身上的有益魔法效果。"},[12264005]={title="衰減魔法",text="沙斯拉爾以護盾保護自己，降低其受到的魔法傷害。"},[12264004]={title="魔爆術",text="沙斯拉爾釋放秘法能量爆發，對附近所有敵人造成大量秘法傷害。"},[12264003]={title="法術反制",text="沙斯拉爾反制一名敵人的法術，使該系魔法數秒內無法施放。"},[12264002]={title="沙斯拉爾之門",text="沙斯拉爾閃現到一名隨機玩家身邊，重置他的威脅值並傳送到團隊之中。"},[12264001]={title="沙斯拉爾的詛咒",text="沙斯拉爾詛咒一名玩家，提高其受到的魔法傷害。"},[12056004]={title="末日決戰",text="瀕死時，迦頓男爵會釋放末日決戰，以毀滅性的火焰傷害重創整個團隊。"},[12056003]={title="點燃法力",text="迦頓男爵點燃一名玩家的法力，在法力燃燒殆盡的同時吸取法力並造成火焰傷害。"},[12056002]={title="地獄火",text="迦頓男爵爆發出煉獄之火，在數秒內對附近所有玩家脈衝造成逐漸增強的火焰傷害。"},[12056001]={title="活化炸彈",text="迦頓男爵將一名玩家變成活化炸彈。數秒後該玩家會爆炸，對附近所有人造成大量火焰傷害並將其擊退。爆炸前請遠離團隊。"},[12098004]={title="擊倒",text="薩弗隆將目標擊倒，使其短暫昏迷。"},[12098003]={title="挫志怒吼",text="薩弗隆發出挫志怒吼，降低附近敵人的攻擊強度。"},[12098002]={title="靈感",text="薩弗隆激勵他的喚焰者祭司，提高他們的攻擊與施法速度。"},[12098001]={title="拉格納羅斯之手",text="薩弗隆以拉格納羅斯之手重擊地面，對附近的玩家造成火焰傷害並將其擊退。"},[11988003]={title="炎爆術",text="古雷曼格朝一名遠方的敵人擲出巨大的炎爆術，造成大量火焰傷害。"},[11988002]={title="地震術",text="古雷曼格踐踏地面，對附近所有玩家造成物理傷害並使其短暫昏迷。"},[11988001]={title="熔岩噴濺",text="古雷曼格的攻擊會將熔岩濺到目標身上，這種可堆疊的減益效果會提高目標受到的火焰傷害。"},[12018003]={title="衝擊波",text="管理者埃克索圖斯釋放火焰衝擊波，對附近的玩家造成火焰傷害並使其減速。"},[12018002]={title="傷害護盾",text="管理者埃克索圖斯以傷害護盾環繞自身，將部分近戰傷害反射回攻擊者。"},[12018001]={title="魔法反射",text="管理者埃克索圖斯為自己和他的衛士施加護盾，將有害的魔法反射回施法者。在護盾消失之前請停止施法。"},[11502005]={title="烈焰之子",text="拉格納羅斯會不時潛回火源之界，並召喚他的烈焰之子攻擊團隊，之後再重新現身。"},[11502004]={title="元素火焰",text="拉格納羅斯以元素火焰灼燒目標，造成持續性的火焰傷害。"},[11502003]={title="熔岩噴濺",text="拉格納羅斯使熔岩從火源之界噴發，對位在噴發點上方的任何玩家造成大量火焰傷害。"},[11502002]={title="拉格納羅斯之手",text="拉格納羅斯重擊熔岩地面，對附近所有玩家造成火焰傷害並將其擊退。"},[11502001]={title="拉格納羅斯之怒",text="拉格納羅斯以怒火攻擊一名玩家，造成火焰傷害，並以巨大的力量將其擊飛。"},[10184007]={title="奧妮克希亞幼龍",text="在空中階段，奧妮克希亞會從洞穴邊緣的龍蛋中召喚一波波奧妮克希亞幼龍圍攻團隊。"},[10184006]={title="龍尾掃擊",text="奧妮克希亞揮掃尾巴，將站在她身後的玩家掃飛到洞穴的另一頭。"},[10184005]={title="龍翼攻擊",text="奧妮克希亞以翅膀拍擊前方區域，造成物理傷害、將玩家擊退並降低其威脅值。"},[10184004]={title="火球術",text="奧妮克希亞在空中時會朝隨機玩家擲出火球，造成大量火焰傷害。"},[10184003]={title="低沉咆哮",text="在最後階段，奧妮克希亞會不斷發出低沉咆哮，使整個團隊恐懼逃跑。"},[10184002]={title="火息術",text="奧妮克希亞朝面前噴出錐形火焰，對範圍內所有敵人造成大量火焰傷害。"},[10184001]={title="深呼吸",text="奧妮克希亞深吸一口氣，接著吐出一道橫越整個洞穴的火牆，對路徑上的任何人造成毀滅性的火焰傷害。"},[12435004]={title="順劈斬",text="拉佐格爾對面前所有敵人使出順劈斬，造成大量物理傷害。"},[12435003]={title="破膽咆哮",text="拉佐格爾發出破膽咆哮，使附近的玩家恐懼逃跑。"},[12435002]={title="連珠火球",text="拉佐格爾釋放連珠火球，對多名敵人造成火焰傷害。"},[12435001]={title="燃燒",text="拉佐格爾使一名玩家陷入焚焰，造成持續性的火焰傷害，並使其困惑地四處逃竄。"},[13020005]={title="龍尾掃擊",text="瓦拉斯塔茲揮掃尾巴，對身後的敵人造成物理傷害並將其擊退。"},[13020004]={title="順劈斬",text="瓦拉斯塔茲對面前所有敵人使出順劈斬，造成大量物理傷害。"},[13020003]={title="火息術",text="瓦拉斯塔茲噴出錐形火焰，對面前所有敵人造成大量火焰傷害。"},[13020002]={title="燃燒刺激",text="瓦拉斯塔茲使一名玩家受到燃燒刺激的影響；該玩家的施法會變成瞬發，但最終會引發致命的爆炸，對附近所有人造成巨額火焰傷害。目前的坦克會定期受到影響，且無法存活。"},[13020001]={title="紅龍精華",text="瓦拉斯塔茲賜予團隊紅龍精華，為他們注入大量法力、怒氣和能量，讓他們能在燃燒刺激吞噬所有人之前將他擊倒。"},[12017004]={title="順劈斬",text="幼龍領主勒西雷爾對面前所有敵人使出順劈斬，造成大量物理傷害。"},[12017003]={title="衝擊波",text="幼龍領主勒西雷爾釋放火焰衝擊波，對附近的玩家造成火焰傷害並將其擊退。"},[12017002]={title="擊飛",text="幼龍領主勒西雷爾擊退目標，造成物理傷害並大幅降低其威脅值。"},[12017001]={title="致死打擊",text="幼龍領主勒西雷爾使出致死打擊，造成大量物理傷害，並降低目標受到的治療效果。"},[11983003]={title="龍翼打擊",text="費爾默以翅膀拍擊前方區域，造成物理傷害、將玩家擊退並降低其威脅值。"},[11983002]={title="烈焰打擊",text="費爾默以火焰拍擊面前的敵人，這種可堆疊的減益效果會提高其受到的火焰傷害，直到他們脫離視線為止。"},[11983001]={title="暗影烈焰",text="費爾默在大範圍的錐形區域噴出暗影烈焰，造成毀滅性的暗影傷害，並使受害者變得脆弱。"},[14601003]={title="龍翼打擊",text="埃博諾克以翅膀拍擊前方區域，造成物理傷害、將玩家擊退並降低其威脅值。"},[14601002]={title="暗影烈焰",text="埃博諾克在大範圍的錐形區域噴出暗影烈焰，造成毀滅性的暗影傷害，並使受害者變得脆弱。"},[14601001]={title="埃博諾克之影",text="埃博諾克以他的陰影詛咒目標，每當他攻擊該目標時便會治療自己。受影響的坦克必須換下，直到減益效果消失為止。"},[11981003]={title="龍翼打擊",text="弗萊格爾以翅膀拍擊前方區域，造成物理傷害、將玩家擊退並降低其威脅值。"},[11981002]={title="暗影烈焰",text="弗萊格爾在大範圍的錐形區域噴出暗影烈焰，造成毀滅性的暗影傷害，並使受害者變得脆弱。"},[11981001]={title="瘋狂",text="弗萊格爾會定期進入狂暴狀態，提高其攻擊速度。獵人的寧神射擊可以安撫這種狂暴。"},[14020005]={title="瘋狂",text="克洛瑪古斯陷入狂暴，提高其攻擊速度。獵人的寧神射擊可以安撫這種狂暴。"},[14020004]={title="腐蝕酸液",text="克洛瑪古斯噴出腐蝕酸液，造成持續性的自然傷害，並降低被擊中者的護甲值。"},[14020003]={title="燒盡",text="克洛瑪古斯噴出洶湧的火焰，對面前所有敵人造成大量火焰傷害。"},[14020002]={title="時間流逝",text="克洛瑪古斯的時間流逝吐息會造成秘法傷害，並扭曲受害者周圍的時間，大幅降低其威脅值。"},[14020001]={title="龍血之痛",text="克洛瑪古斯以五種顏色的龍血之痛折磨團隊。同時身中全部五種的玩家會突變成炫彩龍獸，因此必須謹慎地歸類並淨化這些折磨效果。"},[11583005]={title="順劈斬",text="奈法利安對面前所有敵人使出順劈斬，造成大量物理傷害。"},[11583004]={title="龍尾掃擊",text="奈法利安甩動尾巴，對站在他身後的敵人造成物理傷害並使其昏迷。"},[11583003]={title="低沉咆哮",text="奈法利安發出低沉咆哮，使整個團隊恐懼逃跑。"},[11583002]={title="職業呼喚",text="在最後階段中，奈法利安會對特定職業喊出嘲弄的命令——讓戰士陷入狂暴、使獵人的遠程武器失效、將團隊中的法師變形等等——每一種都會干擾該職業數秒。"},[11583001]={title="暗影烈焰",text="奈法利安噴出暗影烈焰，對他面前大範圍弧形區域內的所有敵人造成毀滅性的暗影傷害。"},[14507004]={title="毒液噴吐",text="生命力偏低時，溫諾希斯會變身為巨大的眼鏡蛇，噴吐毒液造成持續性的自然傷害，並使團隊中毒。"},[14507003]={title="恢復",text="溫諾希斯對自己施放恢復，在一段時間內恢復生命力。"},[14507002]={title="神聖新星",text="溫諾希斯釋放神聖能量爆發，對附近所有敵人造成神聖傷害。"},[14507001]={title="神聖之火",text="溫諾希斯以神聖之火吞噬一名敵人，立即造成神聖傷害，並在一段時間內造成額外的神聖傷害。"},[14517005]={title="蝙蝠群",text="在整場戰鬥中，耶克里克會召喚成群的瘋狂蝙蝠騷擾團隊。"},[14517004]={title="強效治療術",text="耶克里克引導強力的治療來恢復自己的生命力。中斷它以持續施壓。"},[14517003]={title="心靈尖嘯",text="在食人妖形態下，耶克里克會發出心靈尖嘯，使附近的玩家恐懼逃跑。"},[14517002]={title="衝鋒",text="耶克里克衝向一名遠方的玩家，拉近距離並使其短暫昏迷。"},[14517001]={title="音爆",text="在蝙蝠形態下，耶克里克會發出音爆，造成大量物理傷害並使被擊中者沉默。"},[14510004]={title="狂怒",text="瀕死時，瑪俐會陷入狂怒，提高其攻擊速度與造成的傷害。"},[14510003]={title="衝鋒",text="瑪俐衝向一名遠方的玩家，拉近距離並使其昏迷。"},[14510002]={title="瑪俐的爪牙",text="瑪俐變身為巨大的蜘蛛，產下大量瑪俐的爪牙，這些爪牙孵化後會成長為致命的幼蛛。"},[14510001]={title="毒箭之雨",text="瑪俐擲出毒液箭雨，對團隊造成自然傷害。"},[11382005]={title="奧根",text="曼多基爾騎著他的魔暴龍奧根投入戰鬥；奧根被殺死後，血領主會徒步作戰。"},[11382004]={title="旋風斬",text="曼多基爾捲起旋風，對附近所有玩家造成物理傷害。"},[11382003]={title="衝鋒",text="曼多基爾衝向一名遠方的玩家，拉近距離並對其造成物理傷害。"},[11382002]={title="血領主之怒",text="曼多基爾每殺死一名玩家就會變得更強，在剩餘的戰鬥中提高其體型與造成的傷害。"},[11382001]={title="威懾凝視",text="曼多基爾以威懾凝視盯住一名玩家。若被盯住的玩家移動或採取行動，他便會衝鋒並將其擊殺——請站著不動直到凝視結束。"},[15114003]={title="猛擊",text="加茲蘭卡猛擊一名附近的玩家，造成大量物理傷害。"},[15114002]={title="冰息術",text="加茲蘭卡噴出錐形冰霜，造成冰霜傷害並使被擊中者減速。"},[15114001]={title="巨型噴泉",text="加茲蘭卡在一名玩家腳下召喚巨型噴泉，將其高高拋向空中。"},[14509005]={title="狂暴",text="以猛虎形態復活的塞卡爾會進入狂暴狀態，以迅速而兇殘的攻擊撕裂團隊。"},[14509004]={title="嗜血",text="塞卡爾陷入嗜血狀態，提高其攻擊速度。"},[14509003]={title="沉默",text="塞卡爾使附近的施法者沉默，使其數秒內無法施法。"},[14509002]={title="致死順劈",text="塞卡爾劈砍目標，造成大量物理傷害並降低其受到的治療效果。"},[14509001]={title="復活",text="塞卡爾和他的兩名高階狂熱者會互相復活，除非三者在極短時間內相繼被擊敗。"},[14515004]={title="暗言術：痛",text="阿洛克使一名玩家承受灼熱的痛苦，造成持續性的暗影傷害。"},[14515003]={title="旋風斬",text="阿洛克捲起旋風，對附近所有玩家造成物理傷害。"},[14515002]={title="鑿擊",text="阿洛克鑿擊目標，造成物理傷害並使其短暫無法行動。"},[14515001]={title="阿洛克的印記",text="阿洛克標記一名玩家後消失，並召喚成群的獵豹鎖定並衝向被標記的目標。"},[11380004]={title="治療結界",text="金度召喚一個治療結界來迅速治療自己；必須將其摧毀才能取得進展。"},[11380003]={title="金度之影",text="金度召喚出幽暗的陰影，追擊並吸取團隊中施法者的法力。"},[11380002]={title="強力妖術",text="金度對一名玩家施放妖術，將其變成無害的青蛙並剝奪其技能，直到詛咒被移除為止。"},[11380001]={title="洗腦圖騰",text="金度插下洗腦圖騰，控制附近玩家的心智。請盡快將其摧毀。"},[14834004]={title="導致瘋狂",text="哈卡使一名玩家陷入瘋狂，使其在一段時間內轉而攻擊盟友。"},[14834003]={title="腐化之血",text="哈卡以腐化之血感染一名玩家，這種劇烈的病痛會造成大量暗影傷害，並擴散至站在附近的任何人。"},[14834002]={title="血液虹吸",text="哈卡虹吸團隊的血液，吸取他們的生命力來治療自己。"},[14834001]={title="哈卡萊的守護",text="在每一名高階祭司被殺死之前，哈卡都能使用他們的守護之力——耶克里克的蝙蝠、溫諾希斯的恢復、瑪俐的毒素、塞卡爾的狂暴，以及阿洛克的凝視。先清除這些祭司便能剝奪這些力量。"},[15082003]={title="槌擊",text="格里雷克以兇猛的雙手重擊槌擊目標，造成大量物理傷害。"},[15082002]={title="大地震顫",text="格里雷克猛砸地面，對附近的玩家造成物理傷害並中斷其施法。"},[15082001]={title="衝鋒",text="格里雷克衝向一名遠方的玩家，拉近距離並對其造成大量物理傷害。"},[15083003]={title="夢魘幻影",text="哈札拉爾召喚夢魘幻影攻擊團隊，並藏身於其中。"},[15083002]={title="法力燃燒",text="哈札拉爾燃燒一名玩家的法力，依燒毀的法力量造成相應的暗影傷害。"},[15083001]={title="催眠術",text="哈札拉爾使一名玩家陷入沉睡，使其無法行動，直到受到傷害為止。"},[15084003]={title="消失與伏擊",text="雷納塔基消失在視線中，並在一名隨機玩家身後重新出現，伏擊造成巨額物理傷害。"},[15084002]={title="鑿擊",text="雷納塔基鑿擊目標，造成物理傷害並使其短暫無法行動。"},[15084001]={title="千刃",text="雷納塔基以千刃攻擊目標，迅速爆發造成大量物理傷害。"},[15085003]={title="戰爭踐踏",text="烏蘇雷踐踏地面，使附近所有玩家短時間昏迷。"},[15085002]={title="閃電鏈",text="烏蘇雷擲出一道在附近玩家之間彈跳的閃電，造成自然傷害。"},[15085001]={title="落雷之雲",text="烏蘇雷在地面上方召喚落雷之雲，對站在其下的任何玩家造成自然傷害。"},[15348003]={title="狂怒",text="在戰鬥過程中，庫林納克斯會逐漸陷入狂怒，提高其造成的傷害——必須在變得致命之前將他殺死。"},[15348002]={title="沙漠陷阱",text="庫林納克斯在團隊腳下召喚沙漠陷阱，受到觸動時便會爆發，造成大量自然傷害並將玩家拋向空中。"},[15348001]={title="重傷",text="庫林納克斯的攻擊會造成重傷，這種可堆疊的減益效果會降低目標受到的治療效果。"},[15341003]={title="雷霆一擊",text="拉賈克斯重擊地面，對附近的玩家造成自然傷害並降低其攻擊速度。"},[15341002]={title="雷霆震裂",text="拉賈克斯釋放雷霆震裂，造成自然傷害並使附近所有玩家昏迷。"},[15341001]={title="召喚大軍",text="拉賈克斯指揮一波又一波由上尉率領的其拉大軍攻擊團隊，之後他才親自加入戰局。"},[15340003]={title="召喚法力惡魔",text="莫阿姆召喚法力惡魔吸取團隊的法力，並在能量完全充滿後化為石頭以進行充能。"},[15340002]={title="秘法爆發",text="以竊取的法力充能完畢後，莫阿姆會爆發出秘法能量，對整個團隊造成大量秘法傷害。"},[15340001]={title="吸取法力",text="莫阿姆吸取團隊中施法者的法力，將其轉化為秘法能量，並逐漸累積成毀滅性的釋放。"},[15370003]={title="蟲群瘟疫",text="在蟲卵消失後，布魯會以蟲群瘟疫折磨團隊，造成持續且逐漸增強的自然傷害。"},[15370002]={title="蟲卵爆炸",text="在蟲卵被摧毀之前，布魯受到的傷害會大幅降低。每顆蟲卵在被打破時都會劇烈爆炸，削弱布魯但也會傷害團隊。"},[15370001]={title="致傷射擊",text="布魯鎖定一名玩家並全速追擊，無視其他所有人。團隊必須引著他在他的蟲卵之間移動。"},[15369003]={title="毒性釘刺",text="阿亞米斯在空中時，會朝一名遠方的玩家射出毒性釘刺，造成大量自然傷害。"},[15369002]={title="釘刺噴射",text="阿亞米斯噴射一連串釘刺，對她面前的玩家造成自然傷害。"},[15369001]={title="麻痹",text="阿亞米斯麻痹一名隨機玩家並將其浮空送到祭壇上，除非團隊介入，否則她的蟲群會吞噬該玩家。"},[15339003]={title="至高模式",text="若沒有及時在水晶處削弱奧斯里安，他便會進入至高模式，以壓倒性的力量摧毀團隊。"},[15339002]={title="沙塵風暴",text="沙之龍捲風橫掃競技場，將碰到的任何玩家高高拋向空中。"},[15339001]={title="奧斯里安之力",text="奧斯里安會獲得可堆疊的增益效果，使其傷害逐漸提高。只有將他引到散落在競技場周圍的其中一座水晶上才能移除此效果。"},[15263004]={title="鏡像",text="斯克拉姆會不時分裂成數個幻象分身，每個分身都能施放他的法術。必須擊倒這些幻象才能找出真正的預言者。"},[15263003]={title="地面震擊",text="斯克拉姆以地震術轟擊一名玩家，造成自然傷害並中斷其施法。"},[15263002]={title="魔爆術",text="斯克拉姆釋放秘法能量爆發，對附近所有玩家造成大量秘法傷害。"},[15263001]={title="充實",text="斯克拉姆控制一名玩家的心智，使其在一段時間內轉而攻擊團隊。"},[15511006]={title="亞爾基公主：恐懼術",text="亞爾基公主使附近的玩家陷入恐懼而逃跑，並在死亡時召喚亞爾基的子嗣。"},[15511005]={title="亞爾基公主：治療術",text="亞爾基公主會對她的兄弟引導強力的治療，除非被中斷，否則會抵銷團隊的進度。"},[15511004]={title="維姆之怒",text="若維姆比他的手足先倒下，亞爾基公主與克里領主會在剩餘的戰鬥中陷入狂怒——維姆必須最後擊殺。"},[15511003]={title="維姆：衝鋒與擊退",text="維姆衝過房間並將目標擊退，不斷地拉近並重置距離。"},[15511002]={title="克里領主：毒雲",text="克里領主死亡時，他的屍體會爆發成一團持久的毒雲，對逗留其中的任何人造成大量自然傷害。"},[15511001]={title="克里領主：毒性箭雨",text="克里領主射出一陣毒刺，造成自然傷害並使團隊中毒。"},[15516004]={title="皇家衛士",text="戰地衛士沙爾圖拉與她的皇家衛士並肩作戰，這些衛士同樣會使出旋風斬，團隊必須加以控制。"},[15516003]={title="狂怒",text="戰地衛士沙爾圖拉陷入狂怒，提高其攻擊速度與造成的傷害。"},[15516002]={title="破甲順劈",text="戰地衛士沙爾圖拉對面前所有敵人使出順劈斬，造成大量物理傷害。"},[15516001]={title="旋風斬",text="戰地衛士沙爾圖拉捲起不停歇的旋風，在難以預測的移動中對附近所有玩家造成大量物理傷害。"},[15510003]={title="召喚爪牙",text="范克里斯將玩家傳送到他的子嗣之中，並召喚范克里斯的爪牙與維克尼斯雛蟲來擊潰團隊。"},[15510002]={title="糾纏",text="范克里斯以蛛網纏住一名隨機玩家，使其定身，並產生一隻范克里斯的爪牙攻擊該玩家。"},[15510001]={title="道德創傷",text="范克里斯的攻擊會造成重傷，這種可堆疊的減益效果會降低目標受到的治療效果。"},[15299003]={title="劇毒",text="維希度斯以劇烈的毒素使攻擊者中毒，造成持續性的自然傷害。"},[15299002]={title="毒箭之雨",text="維希度斯擲出毒液箭雨，對團隊造成自然傷害。"},[15299001]={title="冰霜易傷",text="維希度斯容易受到冰霜傷害。受到足夠的冰霜傷害後，他會先減速再完全凍結，之後一陣近戰攻擊便能將他擊碎成許多維希度斯水滴。"},[15509004]={title="蠍尾獅釘刺",text="哈霍蘭螫刺一名玩家，使其陷入中毒的沉睡，直到毒液效果結束為止。"},[15509003]={title="致命劇毒",text="哈霍蘭噴灑致命劇毒，對被擊中者造成持續性的自然傷害。"},[15509002]={title="狂暴",text="生命力低於30%時，哈霍蘭會陷入狂怒，對整個團隊不斷釋放洶湧的毒液，直到她倒下為止。"},[15509001]={title="瘋狂",text="哈霍蘭會定期進入狂暴狀態，提高其攻擊與施法速度。獵人的寧神射擊可以安撫這種狂暴。"},[15276006]={title="維克尼拉斯：上勾拳",text="維克尼拉斯大帝以強力的上勾拳將目標打上半空。"},[15276005]={title="維克尼拉斯：失衡打擊",text="維克尼拉斯大帝使出失衡打擊，造成大量物理傷害並降低目標的防禦。"},[15276004]={title="維克洛爾：暴風雪",text="維克洛爾大帝召喚暴風雪，對大範圍區域造成冰霜傷害。"},[15276003]={title="維克洛爾：秘法爆裂",text="受到近戰攻擊時，維克洛爾大帝會釋放秘法爆裂，造成大量秘法傷害並擊退附近的玩家——必須以遠程攻擊與他作戰。"},[15276002]={title="維克洛爾：暗影箭",text="維克洛爾大帝從遠處朝團隊擲出強力的暗影箭。"},[15276001]={title="雙子傳送與治療",text="兩位大帝每三十秒交換一次位置，而且只要靠近彼此就會將對方治療至滿血——必須將他們分開遠遠地坦住，並同時將他們擊倒。"},[15517004]={title="狂怒",text="若戰鬥拖得太久，奧羅會陷入狂怒，大幅提高其造成的傷害。"},[15517003]={title="潛地與召喚",text="奧羅會定期鑽入沙中，召喚土堆與奧羅甲蟲，之後再重新竄出地面。"},[15517002]={title="大地破裂",text="當奧羅從沙中竄出時，團隊腳下的地面會破裂，造成物理傷害並將玩家擊退。"},[15517001]={title="沙塵爆裂",text="奧羅釋放沙塵爆裂，對他面前的玩家造成巨額自然傷害。"},[15727004]={title="消化酸液",text="被吞入克蘇恩胃中的玩家會浸泡在消化酸液中，持續受到自然傷害，直到逃出為止。"},[15727003]={title="血肉觸鬚與胃部",text="在本體階段，克蘇恩會將玩家整個吞入胃中，必須在胃裡摧毀兩條血肉觸鬚，克蘇恩才會變得脆弱。整個階段中，巨型利爪觸鬚與眼球觸鬚會不斷從本體竄出。"},[15727002]={title="魔眼光束",text="克蘇恩的眼睛射出綠色光束，在附近的玩家之間連鎖彈跳，造成自然傷害。"},[15727001]={title="黑暗閃耀",text="在眼睛階段，克蘇恩的巨眼會釋放旋轉的黑暗閃耀——一道橫掃的光束，會立即殺死碰到的任何事物。請躲到房間的柱子後方。"},[15956003]={title="甲蟲屍體",text="被殺死的地穴守衛與首領自身的屍體會冒出甲蟲屍體，蜂擁攻擊團隊。"},[15956002]={title="蝗蟲風暴",text="阿努比瑞克漢以蝗蟲群環繞自身，吸取附近玩家的生命力並使其沉默。坦克必須引著他遠離團隊，直到效果結束為止。"},[15956001]={title="刺穿",text="阿努比瑞克漢從地面竄出一排穿刺尖刺，造成大量物理傷害並將玩家拋向空中。"},[15953003]={title="狂暴",text="費琳娜陷入狂怒，大幅提高其傷害。以精神控制操縱她的一名信奉者並釋放寡婦之擁，即可移除她的狂暴並使她沉默。"},[15953002]={title="火焰之雨",text="費琳娜召喚火焰之雨，對區域內所有玩家造成火焰傷害。"},[15953001]={title="毒箭之雨",text="費琳娜擲出毒液箭雨，對團隊造成大量自然傷害。"},[15952004]={title="狂暴",text="生命力低於30%時，梅克絲娜會陷入狂暴，攻擊速度大幅提高。"},[15952003]={title="墓地毒",text="梅克絲娜的撕咬會注入墓地毒，大幅降低目標受到的治療效果。"},[15952002]={title="撒網",text="梅克絲娜對團隊噴灑蛛網，使所有人昏迷數秒。"},[15952001]={title="纏繞的蜘蛛網",text="梅克絲娜將玩家甩到洞穴的牆壁上，以蛛網將其包成繭，直到被盟友救出為止。"},[15954003]={title="閃現術與復活死者",text="諾斯會閃現脫離近戰範圍，並復活瘟疫勇士與瘟疫戰士，還會定期傳送到他的陽台上派出骷髏攻擊團隊。"},[15954002]={title="殘廢術",text="諾斯使一名玩家殘廢，降低其攻擊與移動速度並削弱其力量。"},[15954001]={title="瘟疫者詛咒",text="諾斯詛咒團隊；數秒後詛咒爆發，對仍身中詛咒的任何人造成大量暗影傷害。"},[15936003]={title="法術擾亂",text="海根擾亂周圍的魔法，大幅提高團隊法術的法力消耗。"},[15936002]={title="衰弱疾病",text="海根以衰弱疾病折磨團隊，這種疾病會造成持續性的自然傷害並降低生命力上限。"},[15936001]={title="爆發",text="海根引導瘟疫爆發，依序橫掃地面。玩家必須隨著節奏在安全區域之間移動——也就是惡名昭彰的「安全舞步」——否則會立即死亡。"},[16011003]={title="孢子",text="憎恨者會定期釋放孢子；玩家要分散開來吸收孢子，以獲得發揮最大傷害所需的真菌成長增益效果。"},[16011002]={title="無可避免的末日",text="隨著戰鬥進行，憎恨者施放無可避免的末日的間隔會越來越短，造成逐漸增強的暗影傷害，治療者必須在亡域光環的空檔之間撐過去。"},[16011001]={title="亡域光環",text="憎恨者散發出亡域光環，幾乎阻止所有治療效果。治療只能在光環脈衝之間的短暫空檔生效，因此必須精確掌握冷卻時間。"},[16061003]={title="混亂怒吼",text="拉祖維斯發出混亂怒吼，對他附近的所有人造成大量傷害。"},[16061002]={title="失衡打擊",text="拉祖維斯使出失衡打擊，造成大量物理傷害並降低目標的防禦。"},[16061001]={title="實習者",text="只有拉祖維斯的死亡騎士實習者才能坦住他，團隊必須以服從水晶精神控制這些實習者，用來坦住他。"},[16060003]={title="靈魂割取",text="高希割取附近玩家的靈魂，造成暗影傷害。"},[16060002]={title="暗影箭",text="一旦降下作戰，高希會朝團隊擲出暗影箭，造成大量暗影傷害。"},[16060001]={title="分裂的領域",text="高希將團隊以一道大門分隔成生者與亡者兩側，並派出一波波不死生物，這些不死生物被殺死後會越過大門到另一側。在所有小怪倒下之前，無法攻擊到他。"},[16065005]={title="死亡凋零",text="瑞文戴爾男爵以死亡凋零覆蓋地面的部分區域，對停留其中的任何人造成持續性的暗影傷害。"},[16065004]={title="神聖憤怒",text="違背自身意志而戰的札里克爵士，會對團隊釋放神聖憤怒與神聖閃電鏈。"},[16065003]={title="虛無區域",text="布洛莫斯女士在地面上召喚暗影虛無區域，對站在其中的任何人造成大量傷害。"},[16065002]={title="隕石術",text="寇斯艾茲族長擲出熾熱的隕石，造成由附近玩家分攤的巨額火焰傷害。"},[16065001]={title="騎士印記",text="每位騎士都會在目標身上烙下印記，印記會越疊越高、越來越痛。坦克與團隊必須在房間的四個角落之間輪替，避免印記層數變得致命。"},[16028002]={title="狂怒",text="生命力低於5%時，縫補者會陷入狂怒，大幅提高其攻擊速度，展開瘋狂的最後猛攻。"},[16028001]={title="憎恨打擊",text="縫補者以憎恨打擊重擊近戰範圍內生命力最高的玩家，造成巨額物理傷害。副坦克必須靠近站位來承受這些攻擊。"},[15931003]={title="軟泥噴灑",text="葛羅巴斯噴出錐形軟泥，造成自然傷害並產生一隻輻射軟泥怪。"},[15931002]={title="毒雲",text="葛羅巴斯移動時會留下毒氣雲，毒雲會逐漸擴散並造成逐漸增強的自然傷害——團隊必須保持地面淨空。"},[15931001]={title="突變注射",text="葛羅巴斯對一名玩家注射突變劑。當效果結束或被驅散時，會爆發成持久的毒雲，因此受影響的玩家必須將其帶到房間邊緣。"},[15932004]={title="殭屍狗頭人",text="源源不絕的殭屍狗頭人蹣跚地走向古魯斯；任何一隻抵達他身邊都會大幅治療他。"},[15932003]={title="恐嚇咆哮",text="古魯斯發出恐嚇咆哮，使附近的玩家恐懼逃跑。"},[15932002]={title="重傷",text="古魯斯的撕咬會造成重傷，這種可堆疊的減益效果會降低他的坦克受到的治療效果。"},[15932001]={title="屠殺",text="古魯斯屠殺團隊和他的殭屍狗頭人，使所有人的生命力只剩一點點。必須在殭屍抵達並治療他之前將其擊倒。"},[15928003]={title="斯塔拉格與伏晨",text="泰迪斯由傀儡斯塔拉格與伏晨守衛，兩者必須在數秒內相繼被殺死；在兩者倒下之前，他們的力量澎湃與靜止力場會不斷懲罰團隊。"},[15928002]={title="閃電鏈",text="泰迪斯釋放在團隊之間彈跳的閃電鏈，對被擊中的所有人造成自然傷害。"},[15928001]={title="兩極移形",text="泰迪斯賦予每名玩家正電荷或負電荷。同極電荷會互相增強；異極電荷接觸時則會致命——團隊必須立即依極性分開站位。"},[15989005]={title="暴風雪",text="薩菲隆召喚四處遊走的暴風雪，對困在其中的任何人造成大量冰霜傷害。"},[15989004]={title="吸取生命",text="薩菲隆同時吸取數名玩家的生命力，並依造成的傷害治療自己。"},[15989003]={title="冰箭",text="在飛行階段，薩菲隆會將玩家冰封在冰塊中，這些冰塊之後可作為抵擋冰息術的掩護。"},[15989002]={title="冰息術",text="薩菲隆從空中朝整個房間吐出毀滅性的冰息術。只有躲在冰塊後方的玩家才能存活。"},[15989001]={title="冰霜光環",text="薩菲隆散發出冰霜光環，對整個團隊持續造成冰霜傷害——冰霜抗性至關重要。"},[15990006]={title="法力爆裂",text="科爾蘇加德引爆團隊中施法者的法力，依摧毀的法力量造成秘法傷害。"},[15990005]={title="連發寒冰箭",text="科爾蘇加德射出連發寒冰箭，對附近所有玩家造成冰霜傷害。"},[15990004]={title="暗影裂縫",text="科爾蘇加德在團隊腳下開啟暗影裂縫；裂縫爆發時仍站在其上的任何玩家都會被殺死。"},[15990003]={title="科爾蘇加德之鍊",text="科爾蘇加德以暗影鎖鍊奴役數名玩家，使他們轉而攻擊團隊，直到鎖鍊被打斷為止。"},[15990002]={title="冰霜衝擊",text="科爾蘇加德以冰霜包覆一名玩家，將其完全凍結，並將致命的寒氣擴散給站在其附近的任何人。"},[15990001]={title="冰霜箭",text="科爾蘇加德朝團隊擲出巨大的寒冰箭，造成大量冰霜傷害。"}},
