MUI_MountDB:Localize(loadstring([=[return {
[22719]={name="黑色作戰陸行鳥",lore="在戰場上，適當加速過的地精會是美麗而致命的角色。- 大工匠梅卡托克",vendor="卡特爾中尉"},
[26656]={name="黑色其拉作戰坦克",lore="雖然現在還是可以在安其拉廢墟中找到各式各樣的其拉作戰坦克，但是色澤最黑的品種只有在聖甲蟲之鑼敲響的時候才會出現。"},
[470]={name="黑馬",lore="由於一身黑色毛皮，謠傳軍情七處最喜歡用牠來執行夜間任務。",vendor="凱蒂·亨特"},
[22718]={name="黑色作戰科多獸",lore="柯爾克隆獸欄管理員是看上了充滿侵略、無法預測的習性而飼養黑色作戰科多獸。聽見牠們的高聲吼叫，就代表要見血了。",vendor="狼騎兵波爾克"},
[22720]={name="黑色戰羊",lore="矮人重視自己的山羊夥伴，因為它們總是無懼地衝進戰鬥中。",vendor="卡特爾中尉"},
[22721]={name="黑色戰鬥迅猛龍",lore="這種迅猛龍來自和奧根相同的殘暴家系，並為古拉巴什帝國帶來勝利。",vendor="狼騎兵波爾克"},
[22717]={name="黑色戰駒",lore="受過訓練，可以在戰場上面對兇惡的近距離對戰。",vendor="卡特爾中尉"},
[22723]={name="黑色戰虎",lore="就像牠們的夜刃豹遠親一樣，老虎最出名的就是鋒利的爪子、難以置信的敏捷度，以及喜歡有人幫牠抓抓耳朵後面的地方。",vendor="卡特爾中尉"},
[22724]={name="黑色戰狼",lore="這種生物有著十分敏銳的嗅覺，讓奧格瑪的守衛讚譽有加。",vendor="狼騎兵波爾克"},
[10969]={name="藍色機械陸行鳥",lore="「外部動態地形繪圖系統可以透過液壓成像的原理，與平衡強化器共同運作…」- 賓吉‧羽哨",vendor="米利·羽哨"},
[25953]={name="藍色其拉作戰坦克",lore="只有在安其拉的沙漠中，才能找到這些相對馴化的異種蠍。"},
[17463]={name="藍色骸骨戰馬",lore="被遺忘者認為如果失去目標，就算是負重的野獸也會感受到不死之身所帶來的痛苦。",vendor="撒迦利亞·普斯特"},
[458]={name="棕馬",lore="基於出眾的耐性和精力，深得暴風城守衛的喜好。",vendor="凱蒂·亨特"},
[18990]={name="棕色科多獸",lore="「科多獸是我們人民生活的骨幹。只要有部落在的地方，不管是在貿易、建立聚落或戰爭上，你都可以看到這些強大的科多獸。」- 哈布‧爪蹄",vendor="哈布·爪蹄"},
[6899]={name="棕山羊",lore="公羊經常用厚重的頭骨相互對撞，以搏取母羊的青睬。在這方面，牠們的表現很像矮人。",vendor="維隆·凍石"},
[17464]={name="棕色骸骨戰馬",lore="被遺忘者認為如果失去目標，就算是負重的野獸也會感受到不死之身所帶來的痛苦。",vendor="撒迦利亞·普斯特"},
[6654]={name="暗棕狼",lore="咆哮聲在數里之外都還清晰可聞。",vendor="奧古納羅"},
[23214]={name="戰騎",lore="由聖光救贖。向目標獻身。"},
[6648]={name="栗色馬",lore="結實又穩重，暴風城就是靠這些馬匹打造出來的。",vendor="凱蒂·亨特"},
[6653]={name="恐狼",lore="原先認為在極北地區之外的恐狼已經絕種。那些準備過冬的人會不斷尋找牠們的蹤跡。",vendor="奧古納羅"},
[23161]={name="恐懼戰馬",lore="警告：牠只渴望魔化能量。不要餵蘋果。牠討厭種子。"},
[8395]={name="翡翠迅猛龍",lore="從來自各地最殘暴的獸群中挑選出來並加以培育，保證不會大口咬人。",vendor="祖尼爾"},
[5784]={name="惡魔戰馬",lore="受到惡魔的力量腐化，並被迫服從於暗影議會。"},
[23509]={name="霜狼嗥叫者",lore="由霜狼氏族在奧特蘭克山脈中飼養。",vendor="葛蘭達·狼心"},
[18989]={name="灰色科多獸",lore="「科多獸是我們人民生活的骨幹。只要有部落在的地方，不管是在貿易、建立聚落或戰爭上，你都可以看到這些強大的科多獸。」- 哈布‧爪蹄",vendor="哈布·爪蹄"},
