[23249]={name="大型棕色科多獸",lore="做為獸群中最強大的一份子，這種科多獸是北貧瘠之地各種神奇生物的最佳代表，牠們四處踏行時就有如打雷一般。",vendor="哈布·爪蹄"},
[23248]={name="大型灰色科多獸",lore="做為獸群中最強大的一份子，這種科多獸是淒涼之地各種神奇生物的最佳代表，牠們四處踏行時就有如打雷一般。",vendor="哈布·爪蹄"},
[23247]={name="大型白色科多獸",lore="這個稀有的白化品種首先於淒涼之地發現。當地的半人馬認為白色的科多獸是末日將至的徵兆。",vendor="哈布·爪蹄"},
[17453]={name="綠色機械陸行鳥",lore="「外部動態地形繪圖系統可以透過液壓成像的原理，與平衡強化器共同運作…」- 賓吉‧羽哨",vendor="米利·羽哨"},
