[17465]={name="綠色骷髏戰馬",lore="當殞落的英雄以不死的形式重生，他們的坐騎也會一同復甦。",vendor="撒迦利亞·普斯特"},
[472]={name="雜色馬",lore="牠的性情冷靜，很適合用來讓年輕孩童練習上馬馳騁。",vendor="凱蒂·亨特"},
[23246]={name="紫色骷髏戰馬",lore="當殞落的英雄以不死的形式重生，他們的坐騎也會一同復甦。",vendor="撒迦利亞·普斯特"},
