[17481]={name="瑞文戴爾的死亡戰騎",lore="當瑞文戴爾男爵成為天譴軍的勇士時，他詛咒了他的愛馬，一同加入不死的命運。",drop="瑞文戴爾男爵"},
[10789]={name="斑點霜刃豹",lore="這種健壯的坐騎有著兇狠的食欲，為牠們博得夜精靈語中的「龍腹」之名",vendor="萊蘭奈"},
[23510]={name="雷矛軍用戰騎",lore="雷矛氏族的坐騎訓練師有個流傳多年的傳統，就是在他們養的戰羊左角上刻上名字。",vendor="蓋爾丁·錘匠"},
[8394]={name="條紋霜刃豹",lore="這種健壯的坐騎有著兇狠的食欲，為牠們博得夜精靈語中的「龍腹」之名。",vendor="萊蘭奈"},
[10793]={name="條紋夜刃豹",lore="牠們是艾澤拉斯最完美的掠食者之一，這些敏捷的野獸可以在濃密的叢林中穿梭而不發出一絲聲響。",vendor="萊蘭奈"},
[23241]={name="迅捷藍色迅猛龍",lore="食人妖永遠的好朋友，這些叢林中的獵人與牠們的主人形成一種特別的連繫。讓牠們同時是坐騎、守護者和朋友。",vendor="祖尼爾"},
[23238]={name="迅捷棕山羊",lore="巴拉克托爾山羊有著厚重的頭骨和大角，很適合用來衝過一群身披戰甲的敵人。",vendor="維隆·凍石"},
[23229]={name="迅捷棕馬",lore="經歷過銀白十字軍最艱苦戰役的沙場老將。",vendor="凱蒂·亨特"},
[23250]={name="迅捷棕狼",lore="部落將狼群視為朋友，而非馴養的家畜。",vendor="奧古納羅"},
[23221]={name="迅捷霜刃豹",lore="夜精靈從小就開始飼養霜刃幼豹，在騎士與野獸之間培養出一輩子的信任與羈絆。",vendor="萊蘭奈"},
[23239]={name="迅捷灰山羊",lore="巴拉克托爾山羊有著厚重的頭骨和大角，很適合用來衝過一群身披戰甲的敵人。",vendor="維隆·凍石"},
[23252]={name="迅捷灰狼",lore="部落將狼群視為朋友，而非馴養的家畜。",vendor="奧古納羅"},
[23225]={name="迅捷綠色機械陸行鳥",lore="我們改進了許多項目，但仍然是以梅卡托克的設計為主。- 米利‧羽哨",vendor="米利·羽哨"},
[23219]={name="迅捷霧刃豹",lore="有些歷史學家宣稱這種坐騎的霧灰色毛皮，是遠古精靈貴族在夜刃豹身上的實驗成果。",vendor="萊蘭奈"},
[23242]={name="迅捷綠色迅猛龍",lore="食人妖永遠的好朋友，這些叢林中的獵人與牠們的主人形成一種特別的連繫。讓牠們同時是坐騎、守護者和朋友。",vendor="祖尼爾"},
