[23227]={name="迅捷褐色馬",lore="在服從紀律和堅定不移方面，受到養馬人的一致推崇。",vendor="凱蒂·亨特"},
[24242]={name="迅捷拉札希迅猛龍",lore="這種迅猛龍已經絕跡數年了。而目前唯一為人所知的拉札希迅猛龍，據說是在祖爾格拉布的血領主曼多基爾看管之下。",drop="血領主曼多基爾"},
[23338]={name="迅捷雷刃豹",lore="謠傳這個品種是依照有名的大德魯伊瑪法里恩‧怒風所命名的。",vendor="萊蘭奈"},
[23251]={name="迅捷森林狼",lore="部落將狼群視為朋友，而非馴養的家畜。",vendor="奧古納羅"},
