[24252]={name="迅捷祖利安猛虎",lore="目前最後為人所知的祖利安猛虎，是由祖爾格拉布深處的高階祭司塞卡爾所看管。聽說牠們遭到濫捕獵殺而接近滅絕。",drop="高階祭司塞卡爾"},
